_PROVIDER_UNAVAILABLE_CATEGORIES = {
    "quota",
    "transport",
    "model_unavailable",
    "provider_error",
    "billing",
    "auth",
    "policy",
    "turn_deadline",
}


def _planner_provider_unavailable_details(
    planner_client: ChatClient | None,
) -> dict[str, Any]:
    """Project structured provider failure provenance without raw error text."""

    resource_plan = (
        getattr(planner_client, "resource_plan", {})
        if planner_client is not None
        else {}
    )
    if not isinstance(resource_plan, dict):
        return {}
    provenance = provider_invocation_provenance(resource_plan)
    invocation_reason = _compact_text(
        provenance.get("final_invocation_error_reason")
        or resource_plan.get("invocation_error_reason")
    )
    if not invocation_reason:
        return {}
    history = [
        dict(row)
        for row in list(
            provenance.get("normalized_error_history")
            or resource_plan.get("normalized_error_history")
            or []
        )
        if isinstance(row, dict)
    ]
    normalized = history[-1] if history else {}
    category = _compact_text(
        provenance.get("final_error_category")
        or normalized.get("category")
    ).casefold()
    if (
        category not in _PROVIDER_UNAVAILABLE_CATEGORIES
        and invocation_reason == "empty_response"
    ):
        category = "model_unavailable"
        normalized = {
            "provider_code": resource_plan.get("provider_code"),
            "category": category,
            "retryable": True,
            "quota_scope": "model",
            "status_code": None,
            "safe_message": (
                "Seçili model iki bounded denemede de boş cevap döndürdü."
            ),
        }
    if category not in _PROVIDER_UNAVAILABLE_CATEGORIES:
        return {}
    try:
        status_code = int(normalized.get("status_code") or 0) or None
    except (TypeError, ValueError):
        status_code = None
    return {
        "provider_code": _compact_text(
            normalized.get("provider_code")
            or resource_plan.get("provider_code")
        ).casefold(),
        "category": category,
        "retryable": bool(normalized.get("retryable")),
        "quota_scope": _compact_text(
            provenance.get("final_quota_scope")
            or normalized.get("quota_scope")
            or resource_plan.get("quota_scope")
        ).casefold(),
        "status_code": (
            provenance.get("final_status_code")
            if provenance.get("final_status_code") is not None
            else status_code
        ),
        "safe_message": _compact_text(normalized.get("safe_message")),
        "model_fallback_allowed": bool(
            provenance.get("final_model_fallback_allowed")
            if provenance.get("final_model_fallback_allowed") is not None
            else normalized.get("model_fallback_allowed")
        ),
        "retry_after_seconds": (
            provenance.get("final_retry_after_seconds")
            if provenance.get("final_retry_after_seconds") is not None
            else normalized.get("retry_after_seconds")
        ),
        "invocation_error_reason": invocation_reason,
        "fallback_blocked_reason": _compact_text(
            provenance.get("final_fallback_blocked_reason")
            or resource_plan.get("fallback_blocked_reason")
        ),
        "requested_model": _compact_text(
            provenance.get("requested_model")
        ),
        "actual_model": _compact_text(provenance.get("final_actual_model")),
        "last_successful_actual_model": _compact_text(
            provenance.get("last_successful_actual_model")
        ),
    }


def _provider_unavailable_answer(details: dict[str, Any] | None) -> str:
    category = _compact_text((details or {}).get("category")).casefold()
    quota_scope = _compact_text(
        (details or {}).get("quota_scope")
    ).casefold()
    if category == "quota":
        if quota_scope == "model":
            reason = "seçili modelin kota/rate-limit sınırına takıldı"
        elif quota_scope == "free_tier":
            reason = (
                "provider'ın ücretsiz model havuzu kota/rate-limit sınırına "
                "takıldı; bu sonuç ücretli model bakiyesinin bittiğini göstermez"
            )
        elif quota_scope in {"project", "account", "provider"}:
            reason = "provider hesabının genel kota/rate-limit sınırına takıldı"
        else:
            reason = "kapsamı doğrulanamayan bir kota/rate-limit yanıtı verdi"
    elif category == "transport":
        reason = "provider bağlantısı kurulamadı veya zaman aşımına uğradı"
    elif category == "turn_deadline":
        reason = (
            "ortak cloud turunun süre bütçesini tamamlayamadan tüketti; "
            "bu sonuç kota veya bakiyenin bittiğini göstermez"
        )
    elif category == "model_unavailable":
        reason = "seçili model provider üzerinde şu anda kullanılamıyor"
    elif category == "billing":
        reason = (
            "API anahtarının harcama sınırına takıldı"
            if quota_scope == "key_limit"
            else "provider hesabının harcama sınırına takıldı"
            if quota_scope == "account"
            else "provider hesabının ödeme veya kredi erişimine takıldı"
        )
    elif category == "auth":
        reason = "provider kimlik doğrulamasında başarısız oldu"
    elif category == "policy":
        reason = "provider erişim politikası tarafından engellendi"
    else:
        reason = "provider isteği geçici olarak başarısız oldu"
    retry_after = _compact_text((details or {}).get("retry_after_seconds"))
    retry_notice = (
        f" Güvenli yeniden deneme süresi: yaklaşık {retry_after} saniye."
        if retry_after
        else ""
    )
    return (
        f"Seçili cloud model {reason}. İstek çalıştırılmadı; hiçbir business tool, "
        "API, DB, dosya veya yazıcı işlemi yapılmadı. Provider erişimi düzeldiğinde "
        f"aynı isteği tekrar deneyebilirsin.{retry_notice}"
    )


def provider_unavailable_details(
    planner_client: ChatClient | None,
) -> dict[str, Any]:
    """Public, secret-safe provider failure projection for UI orchestration."""

    return _planner_provider_unavailable_details(planner_client)


def provider_unavailable_answer(details: dict[str, Any] | None) -> str:
    """Render the one canonical user-facing provider-unavailable explanation."""

    return _provider_unavailable_answer(details)

_TASK_PLAN_RESPONSE_SCHEMA: dict[str, Any] = {
    "type": "object",
    "properties": {
        "reason": {"type": "string"},
        "steps": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "id": {"type": "string"},
                    "operation_id": {"type": "string"},
                    # Provider structured-output dialects cannot reliably
                    # express an arbitrary operation-specific object here.
                    # Keep the wire schema simple, then parse and validate the
                    # object against the selected operation schema below.
                    "arguments_json": {"type": "string"},
                    "depends_on": {
                        "type": "array",
                        "items": {"type": "string"},
                    },
                    "objective": {"type": "string"},
                    "expected_evidence": {
                        "description": "Separate exact machine field names from this operation's output schema; no prose or comma-joined lists.",
                        "type": "array",
                        "items": {"type": "string"},
                    },
                },
                "required": [
                    "id",
                    "operation_id",
                    "arguments_json",
                    "depends_on",
                    "objective",
                    "expected_evidence",
                ],
                "additionalProperties": False,
            },
        }
    },
    "required": ["steps"],
    "additionalProperties": False,
}

