def _safe_reasoning_effort(value: Any) -> str:
    effort = _compact_text(value).casefold()
    return effort if effort in _REASONING_EFFORTS else ""


def _retryable_step_failure(result: Result, data: dict[str, Any]) -> bool:
    if result.success:
        return False
    if data.get("retryable") is True:
        return True
    if isinstance(result.error, (TimeoutError, ConnectionError)):
        return True
    message = _compact_text(result.message or result.error).casefold()
    return any(marker in message for marker in _TRANSIENT_STEP_FAILURE_MARKERS)


