def _compact_text(value: Any) -> str:
    return str(value or "").strip()


def _normalized(value: Any) -> str:
    # Source-app/provider boundaries can occasionally expose UTF-8 text decoded
    # once as Latin-1 or Windows-1252. Repair only when a strict round-trip
    # produces valid UTF-8 and reduces mojibake markers; ordinary Turkish,
    # German, French, etc. text is therefore left untouched.
    text = _compact_text(value)
    suspicious = ("Ã", "Ä", "Å", "Â", "â", "ã", "ä", "å", "\x80", "\x9f")
    for _attempt in range(2):
        current_score = sum(text.count(marker) for marker in suspicious)
        if current_score <= 0:
            break
        repaired = ""
        for encoding in ("cp1252", "latin-1"):
            try:
                candidate = text.encode(encoding).decode("utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                continue
            candidate_score = sum(candidate.count(marker) for marker in suspicious)
            if candidate_score < current_score:
                repaired = candidate
                break
        if not repaired:
            break
        text = repaired

    # Unicode casefold turns Turkish capital I-with-dot into ``i`` plus a
    # combining dot. Remove that mark so real Turkish output compares cleanly.
    text = text.casefold().replace("\u0307", "")
    return (
        text.replace("ı", "i")
        .replace("ğ", "g")
        .replace("ü", "u")
        .replace("ş", "s")
        .replace("ö", "o")
        .replace("ç", "c")
    )


def _task_step_kind(domain: str, step_id: str) -> str:
    clean_domain = _compact_text(domain).casefold()
    spec = TASK_DOMAIN_STEP_CATALOGS.get(clean_domain, {}).get(_compact_text(step_id)) or {}
    explicit = _compact_text(spec.get("step_kind")).casefold()
    if explicit:
        return explicit
    return "write_prepare" if _compact_text(step_id) in _WRITE_STEP_IDS else "read"


def _domain_write_step_allowed_for_goal(domain: str, step_id: str, goal: str) -> bool:
    clean_domain = _compact_text(domain).casefold()
    clean_step = _compact_text(step_id)
    spec = TASK_DOMAIN_STEP_CATALOGS.get(clean_domain, {}).get(clean_step) or {}
    if _task_step_kind(clean_domain, clean_step) != "write_prepare":
        return True
    text = _normalized(goal)
    intent_tokens = tuple(spec.get("write_intent_tokens") or ())
    return bool(intent_tokens) and any(_normalized(token) in text for token in intent_tokens)


def _validate_domain_plan_step_ids(
    domain: str,
    step_ids: list[str],
    goal: str,
    max_steps: int,
) -> tuple[list[str], list[str]]:
    clean_domain = _compact_text(domain).casefold()
    catalog = TASK_DOMAIN_STEP_CATALOGS.get(clean_domain, {})
    accepted: list[str] = []
    rejected: list[str] = []
    for raw_step_id in step_ids:
        step_id = _compact_text(raw_step_id)
        if not step_id or step_id in accepted or step_id in rejected:
            continue
        if step_id not in catalog or not _domain_write_step_allowed_for_goal(clean_domain, step_id, goal):
            rejected.append(step_id)
            continue
        accepted.append(step_id)
        if len(accepted) >= max(1, int(max_steps or 1)):
            break
    return accepted, rejected


def _step_prompt(step_id: str, goal: str) -> str:
    if step_id == "orders.fetch.prepare":
        normalized_goal = _normalized(goal)
        has_explicit_account_or_environment_scope = (
            any(
                token in f" {normalized_goal} "
                for token in (
                    " stage ",
                    " staging ",
                    " production ",
                    " prod ",
                    " canli ortam ",
                    " gercek magaza ",
                )
            )
            or bool(re.search(r"\b\d{3,}\b", _compact_text(goal)))
        )
        if has_explicit_account_or_environment_scope:
            return _compact_text(goal)
        if any(
            token in normalized_goal
            for token in ("iade", "iadeleri", "return", "claim")
        ):
            return (
                "Trendyol siparis ve iade verilerini cek, kaydet "
                "ve lokal kayitlarla senkronize et"
            )
    if step_id == "orders.recent":
        return _recent_orders_prompt_from_goal(goal)
    if step_id == "orders.labels.prepare" and _goal_has_order_identifier(goal):
        return f"{', '.join(_order_identifiers_from_goal(goal))} siparislerini yazdir"
    if step_id == "orders.labels.extracted.prepare" and _goal_has_order_identifier(goal):
        return f"{', '.join(_order_identifiers_from_goal(goal))} siparislerini fis cikarildi olarak isaretle"
    if step_id == "orders.full_context" and _goal_has_ready_context_intent(goal):
        return _full_context_prompt_from_goal(goal)
    spec = ORDERS_TASK_STEP_CATALOG.get(step_id) or {}
    prompt = _compact_text(spec.get("prompt"))
    return prompt.format(goal=_compact_text(goal)) if "{goal}" in prompt else prompt


def _task_step_prompt(domain: str, step_id: str, goal: str) -> str:
    clean_domain = _compact_text(domain).casefold()
    if clean_domain == "orders":
        return _step_prompt(step_id, goal)
    spec = TASK_DOMAIN_STEP_CATALOGS.get(clean_domain, {}).get(step_id) or {}
    prompt = _compact_text(spec.get("prompt"))
    return prompt.format(goal=_compact_text(goal)) if "{goal}" in prompt else prompt


def _stock_template_step_ids(goal: str) -> list[str]:
    text = _normalized(goal)
    write_requested = _domain_write_step_allowed_for_goal(
        "stock",
        "stock.manual_write.prepare",
        goal,
    )
    if any(token in text for token in ("operasyon", "toparla")) and not write_requested:
        return [
            "stock.inventory_overview",
            "stock.low_stock",
            "stock.zero_or_negative_count",
        ]
    low_metric_requested = any(
        token in text for token in ("dusuk", "azalan", "kritik")
    ) and not bool(
        re.search(
            r"(?<!\w)(?:dusuk|azalan|kritik).{0,48}"
            r"(?:birak|cik|haric|dahil etme|tekrar etme|tekrarlama|isteme|istemiyorum)(?!\w)",
            text,
        )
    )
    zero_metric_requested = any(
        token in text for token in ("sifir", "negatif", "tukenen")
    ) and not bool(
        re.search(
            r"(?<!\w)(?:sifir|negatif|tukenen).{0,48}"
            r"(?:birak|cik|haric|dahil etme|tekrar etme|tekrarlama|isteme|istemiyorum)(?!\w)",
            text,
        )
    )
    selected: list[str] = []
    if any(token in text for token in ("genel", "envanter")):
        selected.append("stock.inventory_overview")
    if low_metric_requested:
        selected.append("stock.low_stock")
    if zero_metric_requested:
        selected.append("stock.zero_or_negative_count")
    if (
        any(token in text for token in ("say", "adet", "kac", "toplam"))
        and not zero_metric_requested
        and not low_metric_requested
    ):
        selected.append("stock.item_count")
    if any(token in text for token in ("liste", "goster", "urunler")):
        selected.append("stock.items_list")
    if write_requested:
        has_sequence = any(
            token in text
            for token in (" sonra", "ardindan", " once ", " ve ", ",", ";")
        )
        return [*selected, "stock.manual_write.prepare"] if has_sequence and selected else [
            "stock.manual_write.prepare"
        ]
    return selected or [
        "stock.inventory_overview",
        "stock.low_stock",
        "stock.zero_or_negative_count",
    ]


def _domain_template_step_ids(domain: str, goal: str) -> list[str]:
    clean_domain = _compact_text(domain).casefold()
    if clean_domain == "stock":
        return _stock_template_step_ids(goal)
    catalog = TASK_DOMAIN_STEP_CATALOGS.get(clean_domain, {})
    text = _normalized(goal)
    write_selected = [
        step_id
        for step_id in catalog
        if _task_step_kind(clean_domain, step_id) == "write_prepare"
        and _domain_write_step_allowed_for_goal(clean_domain, step_id, goal)
    ]
    selected = [
        step_id
        for step_id, spec in catalog.items()
        if _task_step_kind(clean_domain, step_id) == "read"
        if any(_normalized(token) in text for token in tuple(spec.get("intent_tokens") or ()))
    ]
    if write_selected:
        has_sequence = any(
            token in text
            for token in (" sonra", "ardindan", " once ", " ve ", ",", ";")
        )
        return [*selected, *write_selected] if has_sequence and selected else write_selected
    read_catalog = [
        step_id
        for step_id in catalog
        if _task_step_kind(clean_domain, step_id) == "read"
    ]
    return selected or read_catalog


def _orders_template_step_ids(goal: str) -> list[str]:
    text = _normalized(goal)

    if _goal_has_fetch_intent(goal):
        return ["orders.fetch.prepare"]

    if _goal_has_stale_return_restore_intent(goal):
        return ["returns.stale.restore.prepare"]

    if _goal_has_stale_return_intent(goal):
        if any(token in text for token in ("temizle", "kaldir", "sil", "gizle", "pasifle", "isaretle", "duzelt", "cleanup")):
            return ["returns.stale.mark.prepare"]
        return ["returns.stale.reconcile"]

    if any(token in text for token in ("iade", "return", "claim")):
        if _goal_has_return_approval_intent(goal):
            return ["returns.waiting.list", "returns.approve.prepare"]
        if any(token in text for token in ("say", "adet", "kac", "toplam")):
            return ["returns.waiting.count"]
        return ["returns.waiting.list"]

    if (
        _goal_has_contextual_item_sales_quantity_intent(goal)
        or _goal_has_contextual_item_sales_order_count_intent(goal)
        or _goal_has_contextual_item_sales_amount_intent(goal)
    ):
        return [
            "orders.product_public_identities",
            "orders.item_sales_summary",
        ]

    if _goal_has_count_projection(goal):
        return [
            "orders.ready_to_ship_count"
            if _goal_has_ready_context_intent(goal)
            else "orders.count"
        ]

    if _explicit_read_listing_requested(goal) and any(
        marker in text
        for marker in (
            "siparis numara",
            "siparis no",
            "order number",
            "order no",
        )
    ):
        return [
            "orders.ready_to_ship"
            if _goal_has_ready_context_intent(goal)
            else "orders.recent"
        ]

    if _goal_has_order_detail_intent(goal) and _goal_has_ready_context_intent(goal) and not _goal_has_order_identifier(goal):
        return ["orders.ready_to_ship", "orders.full_context"]

    if _goal_has_order_detail_intent(goal):
        return ["orders.full_context"]

    if _goal_has_label_intent(goal) or _goal_has_label_extracted_intent(goal):
        step_ids = [] if _goal_has_order_identifier(goal) else [_order_scope_read_step(goal)]
        if _goal_has_label_intent(goal):
            step_ids.append("orders.labels.prepare")
        if _goal_has_label_extracted_intent(goal):
            step_ids.append("orders.labels.extracted.prepare")
        return step_ids

    if _goal_has_cargo_change_intent(goal):
        cargo_step = "orders.cargo.bulk_change.prepare" if _goal_has_cargo_bulk_change_intent(goal) else "orders.cargo.change.prepare"
        return ([cargo_step] if _goal_has_order_identifier(goal) else [_order_scope_read_step(goal), cargo_step])

    if _goal_has_profit_export_intent(goal):
        step_ids = []
        if not _goal_has_order_identifier(goal):
            step_ids.append(_order_scope_read_step(goal))
        step_ids.append("orders.profit.export.prepare")
        return step_ids

    if any(token in text for token in ("kargo", "cargo", "firma", "firmasi", "firmasini", "provider")) and any(
        token in text for token in ("degistir", "deÄŸiÅŸtir", "yap", "ayarla", "guncelle", "gÃ¼ncelle", "aras", "mng", "yurtici", "ptt", "surat")
    ):
        return ["orders.ready_to_ship", "orders.cargo.change.prepare"]

    if _goal_has_operation_overview_intent(goal):
        return [
            "orders.ready_to_ship",
            "orders.fulfillment_risk",
            "returns.waiting.list",
        ]
    if _goal_has_ready_context_intent(goal):
        return ["orders.ready_to_ship"]
    return ["orders.summary"]


def _orders_task_prompts(goal: str) -> list[str]:
    return [_step_prompt(step_id, goal) for step_id in _orders_template_step_ids(goal)]


def _extract_json_payload(text: str) -> Any:
    raw = _compact_text(text)
    if not raw:
        raise ValueError("empty planner response")
    try:
        return json.loads(raw)
    except Exception:
        pass
    decoder = json.JSONDecoder()
    decoded: list[Any] = []
    index = 0
    while index < len(raw):
        starts = [
            candidate
            for candidate in (raw.find("{", index), raw.find("[", index))
            if candidate >= 0
        ]
        if not starts:
            break
        start = min(starts)
        try:
            payload, end = decoder.raw_decode(raw, start)
        except Exception:
            index = start + 1
            continue
        if isinstance(payload, (dict, list)):
            decoded.append(payload)
        index = max(end, start + 1)
    if decoded:
        return decoded[-1]
    raise ValueError("planner response has no complete JSON payload")


def _planner_step_specs(payload: Any) -> list[dict[str, Any]]:
    candidates = payload
    # Provider structured-output implementations occasionally preserve the
    # requested object but wrap it in a singleton array or under a named plan
    # envelope.  This is JSON dialect canonicalization only: every extracted
    # operation and argument still passes the same catalog/schema/policy
    # verifier below.
    for _depth in range(3):
        if isinstance(candidates, list):
            if (
                len(candidates) == 1
                and isinstance(candidates[0], dict)
                and not _compact_text(
                    candidates[0].get("operation_id")
                    or candidates[0].get("tool")
                )
                and any(
                    key in candidates[0]
                    for key in ("steps", "plan", "step_ids", "goal_plan", "task_plan")
                )
            ):
                candidates = candidates[0]
                continue
            break
        if isinstance(candidates, dict):
            nested_key = next(
                (
                    key
                    for key in ("steps", "plan", "step_ids", "goal_plan", "task_plan")
                    if key in candidates
                ),
                "",
            )
            if nested_key:
                candidates = candidates.get(nested_key)
                continue
            if _compact_text(
                candidates.get("operation_id") or candidates.get("tool")
            ):
                candidates = [candidates]
            break
        break
    if not isinstance(candidates, list):
        return []
    specs: list[dict[str, Any]] = []
    for index, item in enumerate(candidates, start=1):
        if isinstance(item, str):
            spec: dict[str, Any] = {"id": _compact_text(item)}
        elif isinstance(item, dict):
            operation_id = _compact_text(
                item.get("operation_id") or item.get("tool")
            )
            step_id = _compact_text(
                item.get("id") or item.get("step_id") or item.get("name")
            ) or (f"step_{index}" if operation_id else "")
            spec = {"id": step_id}
            if operation_id:
                spec["operation_id"] = operation_id
            if isinstance(item.get("arguments"), dict):
                spec["arguments"] = dict(item.get("arguments") or {})
            elif isinstance(item.get("arguments_json"), dict):
                # Text-only/local models often follow the semantic contract
                # but emit the JSON object directly instead of stringifying
                # it.  Accept the typed object here; the authoritative tool
                # schema validator below still owns field/type safety.
                spec["arguments"] = dict(item.get("arguments_json") or {})
            elif _compact_text(item.get("arguments_json")):
                try:
                    parsed_arguments = json.loads(
                        _compact_text(item.get("arguments_json"))
                    )
                except Exception:
                    parsed_arguments = None
                if isinstance(parsed_arguments, dict):
                    spec["arguments"] = dict(parsed_arguments)
            if isinstance(spec.get("arguments"), dict):
                # A provider following the item-summary schema may wrap its
                # whole-array dependency placeholder in a singleton list,
                # e.g. ``product_identities: [{"$from_step": ...}]``.  The
                # graph dialect represents that one whole-value binding as an
                # object; after resolution it is already the upstream array.
                # This repair is intentionally field-specific: arguments such
                # as ``web_observations`` are arrays *of* bindings and must
                # retain their list container even when only one source is
                # present.
                normalized_arguments: dict[str, Any] = {}
                for argument_name, argument_value in dict(
                    spec.get("arguments") or {}
                ).items():
                    if (
                        argument_name == "product_identities"
                        and
                        isinstance(argument_value, list)
                        and len(argument_value) == 1
                        and isinstance(argument_value[0], dict)
                        and _compact_text(
                            argument_value[0].get("$from_step")
                        )
                        and _compact_text(argument_value[0].get("path"))
                    ):
                        normalized_arguments[argument_name] = dict(
                            argument_value[0]
                        )
                    else:
                        normalized_arguments[argument_name] = argument_value
                spec["arguments"] = normalized_arguments
            if "depends_on" in item:
                spec["depends_on"] = [
                    _compact_text(value)
                    for value in list(item.get("depends_on") or [])
                    if _compact_text(value)
                ]
            objective = _compact_text(item.get("objective"))
            if objective:
                spec["objective"] = objective
            expected_evidence = [
                _compact_text(value)
                for value in list(item.get("expected_evidence") or [])
                if _compact_text(value)
            ]
            if expected_evidence:
                spec["expected_evidence"] = expected_evidence
        else:
            spec = {}
        if _compact_text(spec.get("id")):
            specs.append(spec)
    return specs


def _planner_step_ids(payload: Any) -> list[str]:
    return [
        _compact_text(spec.get("id"))
        for spec in _planner_step_specs(payload)
        if _compact_text(spec.get("id"))
    ]


