def _has_literal_step_argument_value(value: Any) -> bool:
    """Return whether a dataflow argument also embeds a model-authored literal."""

    if _is_step_output_binding(value):
        return False
    if isinstance(value, list):
        return any(_has_literal_step_argument_value(child) for child in value)
    return bool(_compact_text(value))


def _exact_record_id_step_binding(value: Any, *, record_field: str) -> bool:
    """Recognize a dependency binding that resolves one observed record id."""

    if not _is_step_output_binding(value):
        return False
    source_path = _compact_text(value.get("path"))
    escaped = re.escape(_compact_text(record_field))
    return bool(
        re.search(
            rf"(?:\.|\[\d+\]\.){escaped}$",
            source_path,
        )
        or re.search(
            rf"\.(?:returned_)?{escaped}s\[\d+\]$",
            source_path,
        )
    )








def _tool_result_fields(tool: Any) -> set[str]:
    schema = tool.result_schema if isinstance(tool.result_schema, dict) else {}
    properties = schema.get("properties")
    if not isinstance(properties, dict):
        return set()
    return {
        _compact_text(name)
        for name in properties
        if _compact_text(name)
    }


def _goal_has_web_research_intent(goal: str) -> bool:
    text = _normalized(goal)
    return bool(re.search(r"https?://", _compact_text(goal), flags=re.I)) or any(
        token in text
        for token in (
            "webde",
            "web'de",
            "internet",
            "internette",
            "internetten",
            "online arastir",
            "online ara",
            "kaynaklariyla",
            "kaynaklari ile",
            "guncel dokuman",
            "guncel bilgi",
            "hakkinda neler konusuluyor",
        )
    )


def _goal_has_public_opinion_research_intent(goal: str) -> bool:
    """Return whether public user opinion/experience evidence is requested."""

    # Domain/path names such as ``review.example.org`` are source identities,
    # not user authority to change the requested research facet.
    text = re.sub(r"https?://\S+", " ", _normalized(goal), flags=re.I)
    return bool(
        re.search(
            r"(?<!\w)(?:yorum|degerlendirme|deneyim|memnuniyet|sikayet|"
            r"review|rating|feedback)\w*(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:insanlar|kullanicilar|musteriler|people|users|customers)"
            r"\w*.{0,48}(?:ne\s+soyl|neler\s+soyl|dusun|konus|say|think)",
            text,
        )
    )


def _contextual_product_ordinal(goal: str) -> int | None:
    """Return a one-based ordinal for an explicitly selected product line."""

    text = _normalized(goal)
    product = r"(?:urun|kalem|product|item)\w*"
    ordinal_words = {
        "ilk": 1,
        "birinci": 1,
        "ikinci": 2,
        "ucuncu": 3,
        "dorduncu": 4,
        "besinci": 5,
        "first": 1,
        "second": 2,
        "third": 3,
        "fourth": 4,
        "fifth": 5,
    }
    for word, ordinal in ordinal_words.items():
        if re.search(
            rf"(?<!\w){word}(?!\w).{{0,24}}{product}(?!\w)|"
            rf"(?<!\w){product}(?!\w).{{0,24}}{word}(?!\w)",
            text,
        ):
            return ordinal
    numeric = re.search(
        rf"(?<!\w)(\d{{1,2}})\s*(?:inci|nci|uncu|ncu)?\s*{product}(?!\w)|"
        rf"(?<!\w){product}(?!\w).{{0,16}}?(\d{{1,2}})\s*(?:inci|nci|uncu|ncu)?(?!\w)",
        text,
    )
    if not numeric:
        return None
    raw = numeric.group(1) or numeric.group(2)
    return max(1, min(100, int(raw)))


def _goal_has_web_comparison_intent(goal: str) -> bool:
    text = _normalized(goal)
    return any(
        token in text
        for token in ("karsilastir", "compare", "dogrula", "iki kaynak", "celiski", "farkli kaynak")
    )


def _web_claim_from_goal(goal: str) -> str:
    ignored = {
        "ara",
        "arastir",
        "dogrula",
        "dogrulama",
        "hazirla",
        "internet",
        "internette",
        "iki",
        "karsilastir",
        "kaynak",
        "kaynakla",
        "kaynakli",
        "rapor",
        "raporla",
        "ve",
    }
    words = re.findall(
        r"[0-9A-Za-zÀ-ÖØ-öø-ÿĞğİıŞşÇçÜüÖö_-]+",
        _compact_text(goal),
    )
    kept = [word for word in words if _normalized(word) not in ignored]
    return " ".join(kept[:30]) or _compact_text(goal)[:500]


def _web_template_step_specs(goal: str) -> list[dict[str, Any]]:
    """Provider-independent minimal search -> open template.

    Search candidates are not evidence.  The first authoritative source is
    therefore opened through an explicit dependency; comparison goals open a
    second source and compare the two typed observations.
    """

    urls = [
        match.rstrip(".,;:)]}")
        for match in re.findall(r"https?://[^\s<>'\"]+", _compact_text(goal), flags=re.I)
    ]
    wants_comparison = _goal_has_web_comparison_intent(goal)
    wants_export = _goal_has_report_export_intent(goal)
    wants_report = wants_export or "rapor" in _normalized(goal) or "report" in _normalized(goal)
    search_step_id = ""
    if urls:
        operation_id = "web.document.read" if urls[0].casefold().endswith(".pdf") else "web.open"
        specs: list[dict[str, Any]] = [
            {
                "id": "web_open_primary",
                "operation_id": operation_id,
                "operation_domain": "web",
                "arguments": {"url": urls[0], "query_summary": _compact_text(goal)[:240]},
                "depends_on": [],
                "objective": "Kullanicinin verdigi exact public kaynagi ac",
                "expected_evidence": ["web_observation", "observation_id", "url"],
            }
        ]
        if wants_comparison and len(urls) >= 2:
            secondary_operation_id = (
                "web.document.read" if urls[1].casefold().endswith(".pdf") else "web.open"
            )
            specs.extend(
                [
                    {
                        "id": "web_open_secondary",
                        "operation_id": secondary_operation_id,
                        "operation_domain": "web",
                        "arguments": {"url": urls[1], "query_summary": _compact_text(goal)[:240]},
                        "depends_on": [],
                        "objective": "Kullanicinin verdigi ikinci exact public kaynagi ac",
                        "expected_evidence": ["web_observation", "observation_id", "url"],
                    },
                    {
                        "id": "web_compare",
                        "operation_id": "web.compare_sources",
                        "operation_domain": "web",
                        "arguments": {
                            "web_observations": [
                                {"$from_step": "web_open_primary", "path": "tool_result.web_observation"},
                                {"$from_step": "web_open_secondary", "path": "tool_result.web_observation"},
                            ],
                            "claim": _web_claim_from_goal(goal),
                        },
                        "depends_on": ["web_open_primary", "web_open_secondary"],
                        "objective": "Iki exact acilmis kaynagi provenance ve celiski bakimindan karsilastir",
                        "expected_evidence": ["comparison", "citations", "status"],
                    },
                ]
            )
    else:
        search_step_id = "web_search"
        specs = [
            {
                "id": "web_search",
                "operation_id": "web.search",
                "operation_domain": "web",
                "arguments": {"query": _compact_text(goal), "limit": 5},
                "depends_on": [],
                "objective": "Privacy-safe aday kaynaklari ara",
                "expected_evidence": ["primary_url", "secondary_url", "query_summary"],
            },
            {
                "id": "web_open_primary",
                "operation_id": "web.open",
                "operation_domain": "web",
                "arguments": {
                    "url": {"$from_step": "web_search", "path": "tool_result.primary_url"},
                    "query_summary": {"$from_step": "web_search", "path": "tool_result.query_summary"},
                    "title": {"$from_step": "web_search", "path": "tool_result.primary_title"},
                    "published_at": {"$from_step": "web_search", "path": "tool_result.primary_published_at"},
                    "official": {"$from_step": "web_search", "path": "tool_result.primary_official"},
                    "public_product_fields": {"$from_step": "web_search", "path": "tool_result.public_product_fields"},
                },
                "depends_on": ["web_search"],
                "objective": "En guvenilir arama sonucunu ac ve WebObservation uret",
                "expected_evidence": ["web_observation", "observation_id", "url"],
            },
        ]
    if wants_comparison and not urls:
        specs.extend(
            [
                {
                    "id": "web_open_secondary",
                    "operation_id": "web.open",
                    "operation_domain": "web",
                    "arguments": {
                        "url": {"$from_step": "web_search", "path": "tool_result.secondary_url"},
                        "query_summary": {"$from_step": "web_search", "path": "tool_result.query_summary"},
                        "title": {"$from_step": "web_search", "path": "tool_result.secondary_title"},
                        "published_at": {"$from_step": "web_search", "path": "tool_result.secondary_published_at"},
                        "official": {"$from_step": "web_search", "path": "tool_result.secondary_official"},
                        "public_product_fields": {"$from_step": "web_search", "path": "tool_result.public_product_fields"},
                    },
                    "depends_on": ["web_search"],
                    "objective": "Ikinci bagimsiz arama sonucunu ac",
                    "expected_evidence": ["web_observation", "observation_id", "url"],
                },
                {
                    "id": "web_compare",
                    "operation_id": "web.compare_sources",
                    "operation_domain": "web",
                    "arguments": {
                        "web_observations": [
                            {"$from_step": "web_open_primary", "path": "tool_result.web_observation"},
                            {"$from_step": "web_open_secondary", "path": "tool_result.web_observation"},
                        ],
                        "claim": _web_claim_from_goal(goal),
                    },
                    "depends_on": ["web_open_primary", "web_open_secondary"],
                    "objective": "Iki acilmis kaynagi iddia ve provenance bakimindan karsilastir",
                    "expected_evidence": ["comparison", "citations", "status"],
                },
            ]
        )
    if wants_report:
        observation_step_ids = ["web_open_primary"]
        if wants_comparison and (not urls or len(urls) >= 2):
            observation_step_ids.append("web_open_secondary")
        report_dependencies = list(observation_step_ids)
        if search_step_id:
            report_dependencies.insert(0, search_step_id)
        if wants_comparison and (not urls or len(urls) >= 2):
            report_dependencies.append("web_compare")
        report_arguments: dict[str, Any] = {
            "title": _compact_text(goal)[:180] or "Web Arastirma Raporu",
            "query_summary": (
                {"$from_step": search_step_id, "path": "tool_result.query_summary"}
                if search_step_id
                else _compact_text(goal)[:240]
            ),
            "web_observations": [
                {"$from_step": step_id, "path": "tool_result.web_observation"}
                for step_id in observation_step_ids
            ],
            "claims": [],
            "public_product_fields": (
                {"$from_step": search_step_id, "path": "tool_result.public_product_fields"}
                if search_step_id
                else []
            ),
        }
        specs.append(
            {
                "id": "web_research_report",
                "operation_id": "web.research_report",
                "operation_domain": "web",
                "arguments": report_arguments,
                "depends_on": report_dependencies,
                "objective": "Acilmis kaynaklari immutable ResearchReportSnapshot olarak birlestir",
                "expected_evidence": ["research_snapshot", "report_snapshot", "source_count"],
            }
        )
    if wants_export:
        specs.append(
            {
                "id": "web_research_xlsx",
                "operation_id": "web.research_report_xlsx.prepare",
                "operation_domain": "web",
                "arguments": {
                    "report_snapshot": {
                        "$from_step": "web_research_report",
                        "path": "tool_result.report_snapshot",
                    }
                },
                "depends_on": ["web_research_report"],
                "objective": "Ayni research snapshot'i dogrulanmis Excel dosyasina hazirla",
                "expected_evidence": ["action", "snapshot_id", "output_path"],
            }
        )
    return specs


