def _explicit_business_read_domains(
    active_domain: str,
    goal: str,
    interpretation: dict[str, Any] | None,
) -> set[str]:
    """Bound cross-business reads to domains named in a typed read request."""

    primary = _compact_text(active_domain).casefold()
    allowed = {primary}
    typed = dict(interpretation or {})
    if typed.get("intent_kind") != "data_read" or typed.get("mode") != "inspect":
        return allowed
    words = set(re.findall(r"[a-z0-9]+", _normalized(goal)))
    explicitly_named = {
        domain
        for domain, stems in _CROSS_BUSINESS_READ_SIGNALS.items()
        if any(word.startswith(stem) for word in words for stem in stems)
    }
    if len(explicitly_named) >= 2 and primary in _CROSS_BUSINESS_READ_SIGNALS:
        allowed.update(explicitly_named)
    return allowed


def _missing_business_read_domains(
    specs: list[dict[str, Any]],
    read_domains: set[str],
) -> list[str]:
    if len(read_domains) < 2:
        return []
    covered = {
        _compact_text(spec.get("operation_domain")).casefold()
        for spec in specs
        if isinstance(spec, dict)
    }
    return [
        f"cross_business_read_domain_missing:{domain}"
        for domain in sorted(read_domains - covered)
    ]


def _active_business_read_domains(state: AgentSessionState) -> set[str]:
    """Reconstruct the original typed read scope for continuation plans."""
    domain = _compact_text(state.active_domain).casefold()
    active = state.active_entities if isinstance(state.active_entities, dict) else {}
    interpretation = active.get("turn_interpretation")
    authorized = _explicit_business_read_domains(
        domain,
        state.goal,
        interpretation if isinstance(interpretation, dict) else {},
    )
    recorded = {
        _compact_text(value).casefold()
        for value in list(active.get("business_read_domains") or [])
    }
    allowed = authorized.intersection(recorded) | {domain} if recorded else authorized
    allowed.update(
        _compact_text(tool.domain).casefold()
        for tool in _discovered_operation_candidates(state).values()
        if tool.read_only and not tool.destructive
        and not tool.requires_approval and tool.action_type == "read"
    )
    return allowed


def _discovered_operation_candidates(state: AgentSessionState) -> dict[str, Any]:
    """Trust discovered identities only after resolving them in the live registry."""
    from AI.processors.tools import available_tools

    registry = available_tools()
    discovered: dict[str, Any] = {}
    for step in state.completed_steps:
        if step.status != "completed" or step.tool_names != ["operations.discover"]:
            continue
        result = dict((step.result_data or {}).get("tool_result") or {})
        for row in list(result.get("operations") or []):
            if not isinstance(row, dict):
                continue
            operation_id = _compact_text(row.get("operation_id"))
            tool = registry.get(operation_id)
            if tool is not None and tool.read_only and not tool.destructive:
                discovered[operation_id] = tool
    return discovered


def _continuation_operation_candidates(state: AgentSessionState, retrieved: dict[str, Any]) -> dict[str, Any]:
    """Retain schemas already granted to the task across observation replans."""
    from AI.processors.operation_catalog import build_operation_catalog, close_operation_prerequisites
    from AI.processors.tools import available_tools

    registry = available_tools()
    prior = list(((state.active_entities or {}).get("task_plan") or {}).get("operation_candidate_ids") or [])
    pending = [operation for step in state.remaining_steps for operation in step.operation_candidates]
    discovered = _discovered_operation_candidates(state)
    names = list(dict.fromkeys([*pending, *prior, *retrieved, *discovered]))
    allowed = {
        name for name in names if name in registry
        and _direct_operation_domain_allowed(state.active_domain, registry[name], state.goal, read_domains=_active_business_read_domains(state))
    }
    entries = close_operation_prerequisites(
        [name for name in names if name != "operations.discover"], catalog=build_operation_catalog(registry, include_manual=False),
        limit=64, mandatory_operation_ids=("operations.discover",) if "operations.discover" in allowed else (),
        allowed_operation_ids=allowed,
    )
    return {entry.name: registry[entry.name] for entry in entries}


def _planner_operation_candidates(
    domain: str,
    goal: str,
    *,
    limit: int = 20,
    read_domains: set[str] | None = None,
) -> dict[str, Any]:
    """Return the bounded real tool surface shown to and accepted from the planner."""

    from AI.processors.operation_catalog import (
        build_operation_catalog,
        close_operation_prerequisites,
        retrieve_operation_candidates,
    )
    from AI.processors.tools import available_tools

    clean_domain = _compact_text(domain).casefold()
    cross_domain_web = bool(
        clean_domain != "web" and _goal_has_web_research_intent(goal)
    )
    allowed_domains = {clean_domain, *(read_domains or set()), "general", "workflows", "reports", "analysis", "files", "artifacts"}
    if cross_domain_web:
        allowed_domains.add("web")
    registry = available_tools()
    if clean_domain == "general":
        allowed_domains.update(
            _compact_text(tool.domain).casefold()
            for tool in registry.values()
        )
    catalog = build_operation_catalog(registry, include_manual=False)
    retrieved = retrieve_operation_candidates(
        goal,
        catalog=catalog,
        domains=allowed_domains,
        binding_kinds={"agent_tool"},
        limit=max(1, int(limit or 20)),
    )
    ordered_names = [entry.name for entry in retrieved]
    # Every planner can discover the current atomic catalog. Discovery is a
    # read-only control operation, not permission to execute another domain.
    fallback_ids = (
        (
            [
                *([] if _goal_has_order_identifier(goal) else [_order_scope_read_step(goal)]),
                "orders.product_public_identities",
            ]
            if cross_domain_web and clean_domain == "orders"
            else _orders_template_step_ids(goal)
        )
        if clean_domain == "orders"
        else _domain_template_step_ids(clean_domain, goal)
    )
    fallback_operation_ids: list[str] = []
    for step_id in fallback_ids:
        operation_id = _LEGACY_STEP_DIRECT_OPERATION.get(step_id, step_id)
        if operation_id in registry and operation_id not in fallback_operation_ids:
            fallback_operation_ids.append(operation_id)
    # Template-derived hints may bound retrieval, but they never execute or
    # become a plan by themselves. Reserve room for a missing hinted operation
    # without disturbing the semantic rank of candidates already retrieved.
    for operation_id in fallback_operation_ids:
        if operation_id in ordered_names:
            continue
        present_hint_indexes = [
            ordered_names.index(candidate)
            for candidate in fallback_operation_ids
            if candidate in ordered_names
        ]
        insert_at = (
            max(present_hint_indexes) + 1
            if present_hint_indexes
            else min(len(ordered_names), len(fallback_operation_ids) - 1)
        )
        ordered_names.insert(insert_at, operation_id)
    if len(allowed_domains.intersection(_CROSS_BUSINESS_READ_SIGNALS)) > 1:
        # Reserve a few candidates from every explicitly requested business
        # area. These are catalog hints only; the model still authors the plan.
        for requested_domain in sorted(allowed_domains.intersection(_CROSS_BUSINESS_READ_SIGNALS)):
            if requested_domain == clean_domain:
                continue
            hints = (
                _orders_template_step_ids(goal)
                if requested_domain == "orders"
                else _domain_template_step_ids(requested_domain, goal)
            )
            hints = [
                step_id for step_id in hints
                if _task_step_kind(requested_domain, step_id) == "read"
            ] or [
                step_id for step_id in TASK_DOMAIN_STEP_CATALOGS[requested_domain]
                if _task_step_kind(requested_domain, step_id) == "read"
            ]
            for operation_id in hints[:2]:
                operation_id = _LEGACY_STEP_DIRECT_OPERATION.get(operation_id, operation_id)
                if operation_id in registry:
                    if operation_id in ordered_names:
                        ordered_names.remove(operation_id)
                    ordered_names.insert(min(len(ordered_names), 6), operation_id)
    if cross_domain_web:
        cross_domain_priority = [
            *(
                []
                if clean_domain != "orders" or _goal_has_order_identifier(goal)
                else [_LEGACY_STEP_DIRECT_OPERATION.get(_order_scope_read_step(goal), _order_scope_read_step(goal))]
            ),
            *(["orders.product_public_identities"] if clean_domain == "orders" else []),
            "web.search",
            "web.open",
            "web.document.read",
            "web.find",
            "web.follow",
            "web.compare_sources",
            "web.research_report",
            "web.research_report_xlsx.prepare",
        ]
        ordered_names = [
            *[
                operation_id
                for operation_id in cross_domain_priority
                if operation_id in registry
            ],
            *[
                operation_id
                for operation_id in ordered_names
                if operation_id not in cross_domain_priority
            ],
        ]
    allowed_operation_ids = {
        name for name, tool in registry.items()
        if (
            _compact_text(registry[name].domain).casefold() in allowed_domains
            or name in {"operations.discover", "agent.delegate"}
        )
        and (
            clean_domain == "general"
            or _compact_text(registry[name].domain).casefold() == clean_domain
            or (
                _compact_text(registry[name].domain).casefold() in {"general", "workflows", "reports", "analysis"}
                and bool(registry[name].read_only)
                and not bool(registry[name].destructive)
            )
            or _compact_text(registry[name].domain).casefold() == "web"
            or (
                bool(registry[name].read_only)
                and not bool(registry[name].destructive)
                and not bool(registry[name].requires_approval)
                and registry[name].action_type == "read"
            )
        )
    }
    closed = close_operation_prerequisites(
        [name for name in ordered_names if name != "operations.discover" and name in allowed_operation_ids],
        catalog=catalog, limit=max(1, int(limit or 20)),
        mandatory_operation_ids=tuple(name for name in ("operations.discover", "agent.delegate", "artifacts.read")
                                      if name in allowed_operation_ids
                                      and (name == "operations.discover" or int(limit or 20) >= 12)),
        allowed_operation_ids=allowed_operation_ids,
    )
    return {entry.name: registry[entry.name] for entry in closed if entry.name in registry}


def _direct_operation_allowed_for_goal(
    operation_id: str,
    tool: Any,
    goal: str,
    *,
    authorization_context: dict[str, Any] | None = None,
) -> bool:
    if source_operation_problems(operation_id, authorization_context):
        return False
    if not bool(tool.requires_approval or tool.action_type != "read"):
        return True
    typed_authorization = dict(authorization_context or {})
    typed_mode = _compact_text(typed_authorization.get("mode")).casefold()
    typed_intent = _compact_text(typed_authorization.get("intent_kind")).casefold()
    if typed_mode in {"act", "correct"} and typed_intent in {
        "action",
        "correction",
    }:
        # The model has already selected one exact operation from the retrieved
        # canonical catalog.  Re-parsing the raw follow-up with legacy keyword
        # guards here would create a second business-intent authority and reject
        # valid corrections such as "2736 değil, 2610 olarak düzelt" merely
        # because the noun "etiket" was not repeated.  Schema, scope, policy,
        # approval and the semantic verifier remain authoritative downstream.
        return True
    if operation_id == "orders.item_sales_report_xlsx.prepare":
        return _goal_has_report_export_intent(goal)
    if operation_id == "web.research_report_xlsx.prepare":
        return _goal_has_report_export_intent(goal)
    legacy_step = _DIRECT_OPERATION_LEGACY_STEP.get(operation_id)
    return bool(legacy_step and _step_allowed_for_goal(legacy_step, goal))


def _direct_operation_domain_allowed(
    active_domain: str,
    tool: Any,
    goal: str,
    *,
    read_domains: set[str] | None = None,
) -> bool:
    clean_active = _compact_text(active_domain).casefold()
    tool_domain = _compact_text(getattr(tool, "domain", "")).casefold()
    if clean_active == "general" or tool_domain in {"general", "workflows", "reports", "analysis", "files", "artifacts"}:
        # Shared agent configuration belongs to every parent conversation.
        # Preparation still requires typed action authority and the exact
        # semantic review; approval and child read-only policy are separate.
        return bool(
            getattr(tool, "read_only", False)
            and not getattr(tool, "destructive", False)
        )
    if _compact_text(getattr(tool, "name", "")) in {"operations.discover", "agent.delegate"}:
        return bool(
            getattr(tool, "read_only", False)
            and not getattr(tool, "destructive", False)
            and not getattr(tool, "requires_approval", False)
            and getattr(tool, "action_type", "") == "read"
        )
    if tool_domain == clean_active:
        return True
    if tool_domain in (read_domains or set()):
        return bool(
            getattr(tool, "read_only", False)
            and not getattr(tool, "destructive", False)
            and not getattr(tool, "requires_approval", False)
            and getattr(tool, "action_type", "") == "read"
        )
    if (
        tool_domain != "web"
        or not _goal_has_web_research_intent(goal)
        or not bool(getattr(tool, "read_only", False))
        or bool(getattr(tool, "destructive", False))
    ):
        return False
    if not bool(getattr(tool, "requires_approval", False)):
        return True
    return bool(
        _compact_text(getattr(tool, "name", ""))
        == "web.research_report_xlsx.prepare"
        and _goal_has_report_export_intent(goal)
    )




def _validate_direct_plan_specs(
    domain: str,
    specs: list[dict[str, Any]],
    goal: str,
    *,
    allowed_operations: dict[str, Any],
    max_steps: int,
    satisfied_dependency_ids: set[str] | None = None,
    satisfied_source_operations: dict[str, str] | None = None,
    forbidden_step_ids: set[str] | None = None,
    authorization_context: dict[str, Any] | None = None,
    validation_diagnostics: list[dict[str, Any]] | None = None,
    read_domains: set[str] | None = None,
) -> tuple[list[dict[str, Any]], list[str]]:
    clean_domain = _compact_text(domain).casefold()
    accepted: list[dict[str, Any]] = []
    rejected: list[str] = []
    seen_ids: set[str] = set()
    forbidden_ids = {
        _compact_text(value)
        for value in set(forbidden_step_ids or set())
        if _compact_text(value)
    }
    previous_step_id = ""
    accepted_by_id: dict[str, dict[str, Any]] = {}
    fatal_dataflow_rejection = False
    for raw in specs:
        spec = dict(raw or {})
        step_id = _compact_text(spec.get("id"))
        operation_id = _compact_text(spec.get("operation_id"))
        tool = allowed_operations.get(operation_id)
        dependencies = (
            [
                _compact_text(value)
                for value in list(spec.get("depends_on") or [])
                if _compact_text(value)
            ]
            if "depends_on" in spec
            else [previous_step_id]
            if previous_step_id
            else []
        )
        dependency_output_fields: set[str] = set()
        for dependency in dependencies:
            dependency_spec = accepted_by_id.get(dependency)
            dependency_tool = (
                allowed_operations.get(_compact_text(dependency_spec.get("operation_id")))
                if dependency_spec is not None
                else None
            )
            if dependency_tool is not None:
                dependency_output_fields.update(_tool_result_fields(dependency_tool))
        arguments = dict(spec.get("arguments") or {})
        if operation_id in {"files.list", "files.read"}:
            # This is a runtime-owned capability, never a model-selected
            # session. A placeholder permits pre-execution schema validation.
            arguments["session_id"] = "runtime_owned_file_workspace"
        argument_normalizations: list[str] = []
        projection_evidence: list[str] = []
        tool_properties = (
            dict((getattr(tool, "parameters", {}) or {}).get("properties") or {})
            if tool is not None
            else {}
        )
        query_binding = arguments.get("query")
        if (
            "order_numbers" in tool_properties
            and not _has_literal_step_argument_value(
                arguments.get("order_numbers")
            )
            and _exact_record_id_step_binding(
                query_binding,
                record_field="order_number",
            )
        ):
            # Models occasionally place a dependency-bound order id in a
            # fuzzy ``query`` slot.  This is still exact typed dataflow, so
            # canonicalize it to the record-id argument before schema and
            # semantic checks.  No record is selected by deterministic code.
            arguments["order_numbers"] = [deepcopy(query_binding)]
            arguments.pop("query", None)
            argument_normalizations.append(
                "exact_order_query_binding_to_order_numbers"
            )
        if (
            tool is not None
            and bool(getattr(tool, "read_only", False))
            and "projection" in arguments
            and "projection" not in tool_properties
        ):
            raw_projection = arguments.get("projection")
            raw_projection_values = (
                list(raw_projection)
                if isinstance(raw_projection, (list, tuple))
                else [raw_projection]
            )
            canonical_projection_values = [
                _canonical_requested_field(value)
                for value in raw_projection_values
                if _compact_text(value)
            ]
            requested_projection = {
                _canonical_requested_field(value)
                for value in list(
                    (authorization_context or {}).get("requested_fields") or []
                )
                if _canonical_requested_field(value)
            }
            if (
                canonical_projection_values
                and all(canonical_projection_values)
                and set(canonical_projection_values).issubset(
                    requested_projection
                )
            ):
                arguments.pop("projection", None)
                projection_evidence = list(
                    dict.fromkeys(canonical_projection_values)
                )
                argument_normalizations.append(
                    "read_projection_argument_to_response_evidence"
                )
        semantic_argument_problems: list[str] = []
        semantic_contract = (
            dict((authorization_context or {}).get("semantic_contract") or {})
            if isinstance(
                (authorization_context or {}).get("semantic_contract"),
                dict,
            )
            else {}
        )
        contextual_identity_source = bool(
            operation_id == "orders.product_public_identities"
            and (
                semantic_contract.get("contextual_item_identity_required") is True
                or semantic_contract.get(
                    "contextual_public_product_web_research_required"
                )
                is True
            )
        )
        trusted_contextual_order_selection = bool(
            (authorization_context or {}).get(
                "trusted_contextual_order_selection"
            )
        )
        if contextual_identity_source and not trusted_contextual_order_selection:
            semantic_argument_problems.append(
                "arguments.order_numbers:trusted_context_selection_required"
            )
        if (
            _compact_text(
                semantic_contract.get("record_scope")
            ).casefold()
            == "all_matching"
            and _has_literal_step_argument_value(
                arguments.get("order_numbers")
            )
            and not contextual_identity_source
        ):
            semantic_argument_problems.append(
                "arguments.order_numbers:population_scope_narrowing_forbidden"
            )
        contract_period = _compact_text(
            semantic_contract.get("period")
        ).casefold()
        authored_period = _compact_text(arguments.get("period")).casefold()
        if (
            contract_period
            and clean_domain != "general"
            and contract_period != "unspecified"
            and "period" in tool_properties
            and tool is not None
            and bool(getattr(tool, "read_only", False))
            and not bool(getattr(tool, "destructive", False))
            and _compact_text(getattr(tool, "action_type", "read")).casefold()
            == "read"
            and authored_period != contract_period
        ):
            # The typed contract is already a normalized projection of the
            # user's temporal words (or the explicit full-snapshot default).
            # Keeping an otherwise schema-valid provider value such as
            # ``today`` would execute a different question.  This is safe
            # argument normalization, not deterministic business planning.
            arguments["period"] = contract_period
            argument_normalizations.append(
                "read_period_argument_to_semantic_contract"
            )
        argument_problems = [
            *source_operation_problems(operation_id, authorization_context),
            *_source_bound_operation_argument_problems(
                operation_id, arguments, set(dependencies),
                source_operations={
                    **dict(satisfied_source_operations or {}),
                    **{
                        source_id: _compact_text(source_spec.get("operation_id"))
                        for source_id, source_spec in accepted_by_id.items()
                    },
                },
            ),
            *(
            _tool_argument_problems(
                tool,
                arguments,
                allow_step_bindings=True,
                allowed_source_steps=set(dependencies),
                dependency_output_fields=dependency_output_fields,
            )
            if tool is not None
            else ["arguments:tool_missing"]
            ),
            *semantic_argument_problems,
        ]
        if contextual_identity_source and trusted_contextual_order_selection:
            # The aggregate itself remains all_matching, but its filter is
            # intentionally derived from the active exact order selection.
            # The execution boundary binds that trusted selection and ignores
            # any model-authored record id, so the identity read may omit its
            # otherwise required order_numbers argument at planning time.
            argument_problems = [
                problem
                for problem in argument_problems
                if problem != "arguments.order_numbers:required"
            ]
        normalized_evidence = []
        output_fields = set((getattr(tool, "result_schema", {}) or {}).get("properties") or {})
        for evidence in list(spec.get("expected_evidence") or []):
            text = _compact_text(evidence)
            fields = [part.strip() for part in text.split(",")] if "," in text else [text]
            if (
                any(re.fullmatch(r"(?:tool_result\.)?[A-Za-z_][A-Za-z0-9_.]*(?:\[\d+\])*", field) is None for field in fields)
                or len(fields) > 1 and any(field.removeprefix("tool_result.") not in output_fields for field in fields)
            ):
                argument_problems.append("expected_evidence:exact_machine_fields_required")
                continue
            normalized_evidence.extend(field.removeprefix("tool_result.") for field in fields)
        if (
            not step_id
            or step_id in seen_ids
            or step_id in forbidden_ids
            or not operation_id
            or tool is None
            or not _direct_operation_domain_allowed(clean_domain, tool, goal, read_domains=read_domains)
            or not tool.read_only
            or tool.destructive
            or not _direct_operation_allowed_for_goal(
                operation_id,
                tool,
                goal,
                authorization_context=authorization_context,
            )
            or argument_problems
        ):
            if any("binding_" in problem for problem in argument_problems):
                fatal_dataflow_rejection = True
            if step_id and step_id not in rejected:
                rejected.append(step_id)
            if validation_diagnostics is not None:
                # Preserve the actual boundary failure for the model repair.
                # Values are deliberately omitted; field paths and schema
                # reason codes suffice to fix an invalid argument contract.
                diagnostic = {
                    "step_id": step_id,
                    "operation_id": operation_id,
                    "reason_codes": [*argument_problems, *(
                        ["step_id:required"] if not step_id else
                        ["step_id:already_executed"] if step_id in forbidden_ids else
                        ["step_id:duplicate"] if step_id in seen_ids else []
                    )] or ["step_policy_or_identity_invalid"],
                }
                if operation_id in {"reports.build_snapshot", "analysis.calculate", "analysis.table"}:
                    source_operations = {
                        **dict(satisfied_source_operations or {}),
                        **{identity: source_spec["operation_id"] for identity, source_spec in accepted_by_id.items()},
                    }
                    diagnostic["required_source_bindings"] = [
                        {"source_step_id": source_id, "operation_id": source_operations[source_id],
                         "result": {"$from_step": source_id, "path": "tool_result"}}
                        for source in list(arguments.get("sources") or []) if isinstance(source, dict)
                        for source_id in [_compact_text(source.get("source_step_id"))]
                        if source_id in source_operations and source_id in dependencies
                    ]
                if operation_id == "web.research_report":
                    diagnostic["available_web_observation_bindings"] = [
                        {"$from_step": identity, "path": "tool_result.result.web_observation"
                         if source_spec["operation_id"] == "artifacts.read" else "tool_result.web_observation"}
                        for identity, source_spec in accepted_by_id.items() if identity in dependencies
                        and source_spec["operation_id"] in {"web.open", "web.document.read", "web.follow", "artifacts.read"}
                    ]
                validation_diagnostics.append(diagnostic)
            continue
        normalized = {
            "id": step_id,
            "operation_id": operation_id,
            "operation_domain": _compact_text(tool.domain).casefold(),
            "arguments": arguments,
            "objective": (
                _compact_text(spec.get("objective"))
                or _compact_text(tool.description)
                or _compact_text(goal)
            ),
            "expected_evidence": list(
                dict.fromkeys(
                    (
                        normalized_evidence
                        + projection_evidence
                    )
                    or list(
                        dict(
                            (tool.result_schema or {}).get("properties") or {}
                        ).keys()
                    )[:8]
                )
            ),
        }
        if argument_normalizations:
            normalized["argument_normalizations"] = argument_normalizations
        normalized["depends_on"] = dependencies
        accepted.append(normalized)
        accepted_by_id[step_id] = normalized
        seen_ids.add(step_id)
        previous_step_id = step_id
        if len(accepted) >= max(1, int(max_steps or 1)):
            break

    accepted_ids = {_compact_text(spec.get("id")) for spec in accepted}
    if fatal_dataflow_rejection:
        return [], rejected
    already_satisfied = {
        _compact_text(value)
        for value in set(satisfied_dependency_ids or set())
        if _compact_text(value)
    }
    known_dependency_ids = accepted_ids | already_satisfied
    invalid_dependencies = {
        _compact_text(spec.get("id"))
        for spec in accepted
        if any(
            dependency not in known_dependency_ids
            or dependency == _compact_text(spec.get("id"))
            for dependency in list(spec.get("depends_on") or [])
        )
    }
    if invalid_dependencies:
        if validation_diagnostics is not None:
            validation_diagnostics.extend({
                "step_id": spec.get("id"), "operation_id": spec.get("operation_id"),
                "reason_codes": ["depends_on:missing_or_self_dependency"],
            } for spec in accepted if spec.get("id") in invalid_dependencies)
        rejected.extend(
            step_id
            for step_id in sorted(invalid_dependencies)
            if step_id not in rejected
        )
        return [], rejected

    completed: set[str] = set(already_satisfied)
    pending = list(accepted)
    while pending:
        ready = [
            spec
            for spec in pending
            if all(dep in completed for dep in list(spec.get("depends_on") or []))
        ]
        if not ready:
            rejected.extend(
                step_id
                for step_id in sorted(accepted_ids)
                if step_id not in rejected
            )
            return [], rejected
        for spec in ready:
            completed.add(_compact_text(spec.get("id")))
            pending.remove(spec)
    return accepted, rejected


def _step_allowed_for_goal(step_id: str, goal: str) -> bool:
    if step_id not in ORDERS_TASK_STEP_CATALOG:
        return False
    if step_id not in _WRITE_STEP_IDS:
        return True
    if step_id == "orders.fetch.prepare":
        return _goal_has_fetch_intent(goal)
    if step_id == "orders.labels.prepare":
        return _goal_has_label_intent(goal)
    if step_id == "orders.profit.export.prepare":
        return _goal_has_profit_export_intent(goal)
    text = _normalized(goal)
    tokens = tuple(ORDERS_TASK_STEP_CATALOG.get(step_id, {}).get("intent_tokens") or ())
    return any(token in text for token in tokens)


def _goal_has_label_intent(goal: str) -> bool:
    return label_create_intent_requested(_normalized(goal))


def _goal_has_label_extracted_intent(goal: str) -> bool:
    text = _normalized(goal)
    return any(token in text for token in ("fis", "fiÅŸ", "extracted", "cikarildi", "cikartildi")) and any(
        token in text for token in ("isaretle", "iÅŸaretle", "guncelle", "gÃ¼ncelle", "yap")
    )


def _goal_has_return_approval_intent(goal: str) -> bool:
    text = _normalized(goal)
    return any(token in text for token in ("iade", "return", "claim")) and any(
        token in text
        for token in (
            "onayla",
            "onaylat",
            "onaya hazirla",
            "onay icin hazirla",
            "onaylama akisina hazirla",
            "approve",
            "kabul et",
        )
    )


def _goal_has_waiting_return_count_intent(goal: str) -> bool:
    text = _normalized(goal)
    return (
        any(token in text for token in ("iade", "return", "claim"))
        and any(token in text for token in ("onay bekleyen", "aksiyon bekleyen"))
        and any(token in text for token in ("kac", "sayisi", "adet", "toplam"))
    )


def _goal_has_cargo_change_intent(goal: str) -> bool:
    text = _normalized(goal)
    if any(
        marker in text
        for marker in (
            "islem yapma",
            "islem baslatma",
            "degisiklik yapma",
            "kargo firmasini degistirme",
            "kargoyu degistirme",
            "henuz hazirlama",
            "secim yapma",
            "sadece goster",
            "yalniz goster",
            "yalnizca goster",
        )
    ):
        return False
    words = re.findall(r"[a-z0-9]+", text)
    has_cargo_subject = any(
        word.startswith(("kargo", "cargo", "firma", "provider"))
        for word in words
    )
    has_change_verb = any(
        word.startswith(("degistir", "ayarla", "guncelle"))
        or word
        in {
            "yap",
            "yapin",
            "yapalim",
            "yapmak",
            "yapmaya",
            "yapilacak",
        }
        for word in words
    )
    return has_cargo_subject and has_change_verb


def _goal_has_cargo_bulk_change_intent(goal: str) -> bool:
    text = _normalized(goal)
    return _goal_has_cargo_change_intent(goal) and any(token in text for token in ("tum", "tÃ¼m", "butun", "bÃ¼tÃ¼n", "hepsi", "hepsini", "toplu", "bulk"))


def _without_order_item_count_phrases(goal: str) -> str:
    """Remove phrases that name line cardinality, not product detail."""

    text = _normalized(goal)
    patterns = (
        # Turkish commonly uses the compound ``urun kalemi adedi``.  Strip
        # the whole compound so its leading product noun cannot survive as
        # false permission to expose product content.
        r"(?<!\w)(?:urun|product)\w*\s+"
        r"(?:kalem|item|line\s+item)\w*\s+"
        r"(?:sayi|aded|adet|count|cardinality)\w*(?!\w)",
        r"(?<!\w)(?:urun|kalem|product|item|line\s+item)\w*\s+"
        r"(?:sayi|aded|adet|count|cardinality)\w*(?!\w)",
        r"(?<!\w)kac(?:\s+adet)?\s+"
        r"(?:urun|kalem|product|item|line\s+item)\w*(?!\w)",
    )
    for pattern in patterns:
        text = re.sub(pattern, " ", text)
    return text


def _goal_has_order_detail_intent(goal: str) -> bool:
    item_count_only_text = _without_order_item_count_phrases(goal)
    return any(
        token in item_count_only_text
        for token in ("detay", "baglam", "context", "kalem", "urunleri")
    )


def _goal_has_recent_intent(goal: str) -> bool:
    text = _normalized(goal)
    return any(
        token in text
        for token in (
            "son gelen",
            "en son",
            "son siparis",
            "son 1 siparis",
            "son 2 siparis",
            "son 3 siparis",
            "son 4 siparis",
            "son 5 siparis",
            "latest order",
            "recent order",
        )
    ) or bool(re.search(r"\bson\s+(?:\d+|bir|iki|uc|dort|bes|alti|yedi|sekiz|dokuz|on)\s+siparis", text))


def _goal_has_latest_single_order_intent(goal: str) -> bool:
    """Recognize a recency-selected single Order record.

    This is a typed cardinality/sort signal, not a tool-routing shortcut.  It
    separates "the latest order's total" from population revenue and lets a
    model compose discovery (recent limit=1) with an exact detail read.
    """

    text = _normalized(goal)
    if (
        "listedeki" in text
        or re.search(
            r"(?<!\w)(?:bu|su|o|onceki|az\s+onceki)\s+liste",
            text,
        )
    ):
        # This is an ordinal/deictic reference to an already-authoritative
        # ordered selection, not permission to run a fresh recent query.
        return False
    return bool(
        re.search(
            r"(?<!\w)(?:(?:en\s+son|son\s+gelen|en\s+yeni)"
            r"(?:\s+gelen)?\s+siparis(?!ler)\w*|"
            r"son\s+siparis(?!ler)\w*|"
            r"latest\s+order(?!s)\w*)(?!\w)",
            text,
        )
    )


def _goal_has_contextual_single_order_intent(goal: str) -> bool:
    """Recognize one Order record referenced through prior typed context."""

    text = _normalized(goal)
    return bool(
        re.search(
            r"(?<!\w)(?:(?:bu|su|o|onceki|az\s+onceki)\s+"
            r"siparis(?!ler)\w*|listedeki(?:\s+\w+){0,4}\s+"
            r"siparis(?!ler)\w*)(?!\w)",
            text,
        )
    )


def _recent_orders_limit(goal: str, *, default: int = 5) -> int:
    text = _normalized(goal)
    match = re.search(r"\bson\s+(\d{1,2})\s+siparis", text)
    if match:
        return max(1, min(20, int(match.group(1))))
    word_numbers = {
        "bir": 1,
        "iki": 2,
        "uc": 3,
        "dort": 4,
        "bes": 5,
        "alti": 6,
        "yedi": 7,
        "sekiz": 8,
        "dokuz": 9,
        "on": 10,
    }
    for word, value in word_numbers.items():
        if re.search(rf"\bson\s+{word}\s+siparis", text):
            return value
    return default


def _recent_orders_prompt_from_goal(goal: str) -> str:
    return f"son gelen {_recent_orders_limit(goal)} siparisi getir"


def _order_scope_read_step(goal: str) -> str:
    return "orders.recent" if _goal_has_recent_intent(goal) else "orders.ready_to_ship"


def _goal_has_ready_context_intent(goal: str) -> bool:
    text = _normalized(goal)
    explicit_queue_phrase = any(
        token in text
        for token in (
            "kargoya hazir",
            "ready to ship",
            "readytoship",
            "hazir siparis",
            "hazir paket",
            "bekleyen siparis",
            "bekleyen kargo",
            "bekleyen paket",
            "kargolanacak siparis",
            "kargolanacak paket",
            "paketlenecek siparis",
            "paketlenecek paket",
        )
    )
    # Order queues are expressed in natural Turkish with either word order:
    # "bekleyen sipariş" and "sipariş var bekleyen" describe the same
    # entity/status relation.  This is a provider-independent semantic alias,
    # not an operation router; the model still chooses an operation and the
    # verifier checks it against the typed contract.
    order_entity_present = any(
        token in text for token in ("siparis", "order", "paket")
    )
    pending_fulfilment_present = any(
        token in text
        for token in (
            "bekleyen",
            "kargolanacak",
            "paketlenecek",
            "hazirlanacak",
        )
    )
    return bool(
        explicit_queue_phrase
        or (order_entity_present and pending_fulfilment_present)
    )


def _goal_has_contextual_item_aggregate_scope(goal: str) -> bool:
    """Return whether a selected-product request spans a sales population."""

    if _explicit_arithmetic_relation_requested(goal):
        # A request to divide/subtract/etc. previously observed product
        # aggregates is a derived calculation over typed refs, not a fresh
        # product-sales summary merely because its operands contain words
        # such as "toplam satış tutarı" and "toplam satılan adet".
        return False
    text = _normalized(goal)
    bounded_sales_period = bool(
        _explicit_semantic_period_from_goal(goal)
        and re.search(
            r"(?<!\w)(?:satil|satis|sold|sales)\w*(?!\w)",
            text,
        )
    )
    bounded_contextual_metric_repeat = bool(
        _explicit_semantic_period_from_goal(goal)
        and re.search(
            r"(?<!\w)(?:bu|o|onceki|ayni|secili)\s+"
            r"(?:urun|kalem|product|item)\w*(?!\w)",
            text,
        )
        and re.search(
            r"(?<!\w)(?:farkli\s+(?:siparis|order)|adet|aded|miktar|"
            r"brut\s+(?:tutar|satis)|gross\s+(?:amount|sales))\w*(?!\w)",
            text,
        )
        and re.search(
            r"(?<!\w)(?:tekrar|yeniden|duzelt|kastettim|yerine)(?!\w)",
            text,
        )
    )
    return bool(
        bounded_sales_period
        or bounded_contextual_metric_repeat
        or
        re.search(
            r"(?<!\w)(?:tum|butun|genel|toplam)"
            r"(?:\s+\w+){0,3}\s+"
            r"(?:siparis|satis|gecmis|donem)\w*(?!\w)",
            text,
        )
        or any(
            marker in text
            for marker in (
                "siparis gecmisi boyunca",
                "tum gecmis boyunca",
                "genel satis adedi",
                "toplam satis adedi",
                "genel satis tutari",
                "overall sales quantity",
                "overall gross sales",
            )
        )
    )


def _goal_has_contextual_item_sales_quantity_intent(goal: str) -> bool:
    """Identify a selected product promoted to an all-orders sales aggregate."""

    text = _normalized(goal)
    item_reference = bool(
        re.search(
            r"(?<!\w)(?:bu|o|onceki|ayni|secili)\s+"
            r"(?:urun|kalem|product|item)\w*(?!\w)",
            text,
        )
    )
    aggregate_scope = _goal_has_contextual_item_aggregate_scope(goal)
    sales_quantity = bool(
        re.search(
            r"(?<!\w)(?:kac|toplam)\w*.{0,32}"
            r"(?:adet|aded|miktar|quantity)\w*(?!\w)",
            text,
        )
        and re.search(
            r"(?<!\w)(?:satil|satis|sold|sales)\w*(?!\w)",
            text,
        )
    )
    repeated_quantity_metric = bool(
        aggregate_scope
        and re.search(
            r"(?<!\w)(?:adet|aded|miktar|quantity)\w*(?!\w)",
            text,
        )
        and re.search(
            r"(?<!\w)(?:tekrar|yeniden|duzelt|kastettim|yerine)(?!\w)",
            text,
        )
    )
    return bool(
        item_reference
        and aggregate_scope
        and (sales_quantity or repeated_quantity_metric)
    )


def _goal_has_contextual_item_sales_order_count_intent(goal: str) -> bool:
    """Identify the distinct-order count of the product in typed context."""

    text = _normalized(goal)
    clauses = [
        clause.strip()
        for clause in re.split(r"[.!?;]+", text)
        if clause.strip()
    ]
    contextual_product = bool(
        re.search(
            r"(?<!\w)(?:bu|o|onceki|ayni|secili)\s+"
            r"(?:urun|kalem|product|item)\w*(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:bu|o|onceki)\s+\d+\s+"
            r"(?:adet|aded|miktar)\w*(?!\w)",
            text,
        )
    )
    distinct_order_relation = any(
        bool(
            re.search(
                r"(?<!\w)(?:kac|toplam)\w*.{0,40}"
                r"(?:farkli\s+)?(?:siparis|orders?)\w*.{0,40}"
                r"(?:satil|satis|sold|sales|dagil|yer\s+al)\w*(?!\w)",
                clause,
            )
            or re.search(
                r"(?<!\w)(?:farkli\s+)?(?:siparis|orders?)\w*.{0,24}"
                r"(?:sayi|count)\w*(?!\w)",
                clause,
            )
        )
        for clause in clauses
    )
    return bool(contextual_product and distinct_order_relation)


def _goal_has_contextual_item_sales_amount_intent(goal: str) -> bool:
    """Identify a selected product promoted to an all-orders gross amount."""

    text = _normalized(goal)
    contextual_product = bool(
        re.search(
            r"(?<!\w)(?:bu|o|onceki|ayni|secili)\s+"
            r"(?:urun|kalem|product|item)\w*(?!\w)",
            text,
        )
    )
    aggregate_scope = _goal_has_contextual_item_aggregate_scope(goal)
    gross_amount = bool(
        re.search(
            r"(?<!\w)(?:brut\s+)?(?:satis\s+)?"
            r"(?:tutar|ciro|gelir|amount|revenue)\w*(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:gross|brut)\s+(?:sales|satis)\w*(?!\w)",
            text,
        )
    )
    return bool(contextual_product and aggregate_scope and gross_amount)


def _goal_has_order_item_quantity_projection(goal: str) -> bool:
    """Return whether quantity belongs to product/order-line evidence."""

    if _goal_has_contextual_item_sales_quantity_intent(goal):
        return False
    # ``urun/kalem adedi`` is the cardinality of the Order's line rows.  It
    # must not also authorize product content + per-line quantity evidence.
    # Keeping these two typed dimensions exclusive prevents an ordinary
    # recent-order list from being promoted to a full-context read.
    if _goal_has_order_item_count_projection(goal):
        return False

    text = _normalized(goal)
    item_dimension = bool(
        re.search(
            r"(?<!\w)(?:urun|kalem|icerik|icerig|product|item)\w*(?!\w)",
            text,
        )
    )
    quantity_dimension = bool(
        re.search(
            r"(?<!\w)(?:adet|aded|miktar|quantity|qty)\w*(?!\w)",
            text,
        )
    )
    return bool(item_dimension and quantity_dimension)


def _goal_has_order_item_count_projection(goal: str) -> bool:
    """Return whether an order row requests its line-item cardinality."""

    # A product-sales ranking uses phrases such as ``urununu adet, siparis
    # sayisi ... listele``.  There ``adet`` is an aggregate sales measure,
    # not the number of lines on each Order record.
    if _goal_has_item_sales_report_intent(goal):
        return False

    text = _normalized(goal)
    return _without_order_item_count_phrases(text) != text


def _goal_has_count_projection(goal: str) -> bool:
    text = _normalized(goal)
    # ``adet`` may mean either record-population cardinality or the quantity
    # of an order line.  Keep those dimensions distinct unless the user also
    # states an explicit population-count relation.
    if _goal_has_order_item_quantity_projection(goal):
        population_count = bool(
            re.search(
                r"(?<!\w)(?:kac(?:\s+adet)?\s+"
                r"(?:siparis|orders?|iade|returns?|claims?|kayit)\w*|"
                r"toplam\s+(?:kac\s+)?(?:siparis|orders?|iade|returns?|claims?|kayit)\w*|"
                r"(?:siparis|orders?|iade|returns?|claims?|kayit)\w*\s+"
                r"(?:sayi\w*|aded\w*|adet\w*))(?!\w)",
                text,
            )
        )
        if not population_count:
            return False
    if _goal_has_order_item_count_projection(goal):
        population_count = bool(
            re.search(
                r"(?<!\w)(?:kac(?:\s+adet)?\s+"
                r"(?:siparis|orders?|iade|returns?|claims?|kayit)\w*|"
                r"toplam\s+(?:kac\s+)?(?:siparis|orders?|iade|returns?|claims?|kayit)\w*|"
                r"(?:siparis|orders?|iade|returns?|claims?|kayit)\w*\s+"
                r"(?:sayi\w*|aded\w*|adet\w*))(?!\w)",
                text,
            )
        )
        if not population_count:
            return False
    if any(
        token in text
        for token in (
            "kac",
            "sayisi",
            "sayiyi",
            "adedi",
            "adet",
            "toplam kac",
            "count",
        )
    ):
        return True
    if re.search(
        r"(?<!\w)sayi(?:si|yi|lari(?:ni)?|sini)?(?!\w)",
        text,
    ):
        return True
    return bool(
        re.search(
            r"(?<!\w)(?:toplam\s+(?:siparis|order|iade|return|claim|kayit)\w*|"
            r"(?:tum\s+)?(?:siparis|order|iade|return|claim|kayit)\w*\s+"
            r"toplam(?:i|ini|lari|larini)|"
            r"(?:siparis|order|iade|return|claim|kayit)\w*\s+"
            r"(?:sayi\w*|aded\w*|adet\w*))(?!\w)",
            text,
        )
    )


def _goal_has_total_order_count_requirement(goal: str) -> bool:
    text = _normalized(goal)
    if not re.search(r"(?<!\w)(?:siparis|orders?)\w*(?!\w)", text):
        return False
    total_pattern = re.compile(
        r"(?<!\w)(?:toplam\s+(?:kac\s+)?(?:siparis|orders?)\w*|"
        r"(?:siparis|orders?)\w*\s+toplam(?:i|ini)?)(?!\w)"
    )
    scoped_prefix_pattern = re.compile(
        r"(?:terminal\s+(?:olmayan|disi)|final\s+(?:olmayan|disi)|"
        r"non\s*final|tamamlanmamis|sonlanmamis|kapanmamis)\s*$"
    )
    for match in total_pattern.finditer(text):
        prefix = text[max(0, match.start() - 96):match.start()]
        if scoped_prefix_pattern.search(prefix):
            continue
        return True
    return False


def _goal_has_total_order_revenue_requirement(goal: str) -> bool:
    """Return whether the user explicitly asks for population revenue.

    Product-sales reports also contain a per-product ``gross_amount`` column.
    That row metric must not silently become the order population's total
    revenue.  Only an explicit revenue noun, or ``total`` attached to a
    generic amount noun, authorizes the aggregate Orders revenue metric.
    """

    text = _normalized(goal)
    if (
        _goal_has_order_identifier(goal)
        or _contextual_reference_requested(goal)
        or _goal_has_latest_single_order_intent(goal)
    ):
        return False
    return bool(
        re.search(
            r"(?<!\w)(?:ciro|gelir|revenue)\w*(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)toplam\s+(?:(?:brut|gross|satis)\w*\s+){0,2}"
            r"(?:tutar|amount)\w*(?!\w)",
            text,
        )
    )


_COMBINED_UNDELIVERED_RETURNED_STATUS_PATTERN = (
    r"(?:undelivered[\s_-]*and[\s_-]*returned|"
    r"teslim\s+edilemeyen\s+ve\s+iade(?!\s+don(?:en|mus))|"
    r"iade\s+donen|iade\s+donmus)\w*"
)


def _explicit_order_status_scopes_from_goal(goal: str) -> tuple[str, ...]:
    """Return every explicitly targeted order lifecycle status in user order."""

    text = _normalized(goal)
    patterns = (
        (
            "undelivered_and_returned",
            (
                rf"(?<!\w){_COMBINED_UNDELIVERED_RETURNED_STATUS_PATTERN}(?!\w)",
            ),
        ),
        (
            "undelivered",
            (
                r"(?<!\w)(?:teslim\s+edilemeyen|teslim\s+edilememis|undelivered)\w*(?!\w)",
            ),
        ),
        (
            "delivered",
            (
            r"(?<!\w)(?:teslim\s+edilen|teslim\s+edilmis|delivered)\w*(?!\w)",
            ),
        ),
        (
            "cancelled",
            (
                r"(?<!\w)(?:iptal(?:\s+edilen|\s+olmus)?|cancelled|canceled)\w*(?!\w)",
            ),
        ),
        (
            "shipped",
            (
                r"(?<!\w)(?:kargoya\s+verilen|kargoda(?:ki)?|shipped)\w*(?!\w)",
            ),
        ),
    )
    matched = [
        scope
        for scope, scope_patterns in patterns
        if any(re.search(pattern, text) for pattern in scope_patterns)
    ]
    # ``UnDeliveredAndReturned`` is one exact marketplace lifecycle code, not
    # an implicit union with plain ``UnDelivered``.  The broad plain-status
    # regex also matches its prefix, so remove that false second member unless
    # the remaining user text independently names the plain bucket.  Phrases
    # such as "teslim edilemeyenlerle iade donenleri" still retain both.
    if "undelivered_and_returned" in matched and "undelivered" in matched:
        text_without_combined = re.sub(
            _COMBINED_UNDELIVERED_RETURNED_STATUS_PATTERN,
            " ",
            text,
            flags=re.IGNORECASE,
        )
        standalone_plain_status = bool(
            re.search(
                r"(?<!\w)(?:teslim\s+edilemeyen|teslim\s+edilememis|undelivered)\w*(?!\w)",
                text_without_combined,
            )
        )
        if not standalone_plain_status:
            matched = [scope for scope in matched if scope != "undelivered"]
    # Some marketplaces expose two distinct non-delivery lifecycle buckets:
    # plain UnDelivered and UnDeliveredAndReturned.  When the user explicitly
    # refers to "the two/both non-delivery groups", preserve that grouped
    # status role instead of forcing them to repeat the internal status names.
    if re.search(
        r"(?<!\w)(?:iki|her\s+iki)\s+"
        r"(?:teslim\s+edilememe|teslim\s+edilemeyen|non[-\s]?delivery)\w*\s+"
        r"(?:gru(?:p|b)|durum|kova)\w*(?!\w)",
        text,
    ):
        matched.extend(("undelivered_and_returned", "undelivered"))
    return tuple(dict.fromkeys(matched))


def _explicit_order_status_scope_from_goal(goal: str) -> str:
    """Return one explicitly targeted lifecycle status, never a distribution."""

    matched = _explicit_order_status_scopes_from_goal(goal)
    return matched[0] if len(matched) == 1 else ""


def _goal_has_order_status_ratio_projection(goal: str) -> bool:
    """Identify a focused status/population ratio as a typed numeric role."""

    if not _explicit_order_status_scopes_from_goal(goal):
        return False
    return _explicit_percentage_relation_requested(goal)


def _explicit_percentage_relation_prohibited(goal: str) -> bool:
    """Return whether percentage output is explicitly negated."""

    text = _normalized(goal)
    return bool(
        re.search(
            r"(?<!\w)(?:yuzde|percentage|percent)\w*.{0,24}"
            r"(?:cevirme|donusturme|hesaplama|gosterme|verme)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:yuzde|percentage|percent)\w*.{0,16}"
            r"(?:degil|istemi\w*|olmasin|without)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:do\s+not|don't|dont|without)\b.{0,24}"
            r"(?:percentage|percent)(?!\w)",
            text,
        )
    )


def _explicit_percentage_relation_requested(goal: str) -> bool:
    """Return whether the user explicitly requested a percentage/rate result.

    This is a response-scope permission boundary only. It never chooses an
    operand, operation or percentage formula for the model.
    """

    if _explicit_percentage_relation_prohibited(goal):
        return False
    text = _normalized(goal)
    if "%" in _compact_text(goal) or re.search(
        r"(?<!\w)(?:yuzde|percentage|percent)\w*(?!\w)",
        text,
    ):
        return True
    ratio_word = bool(
        re.search(
            r"(?<!\w)(?:oran|payi|payini|rate|ratio)\w*(?!\w)",
            text,
        )
    )
    if not ratio_word:
        return False
    # An explicit quotient request ("A'yi B'ye bol, orani ver") names a
    # dimensionless scalar.  ``oran`` alone does not authorize an implicit
    # x100 conversion; the user must say yüzde/% for that projection.
    explicit_division = bool(
        re.search(
            r"(?<!\w)(?:bol|bolum|divide|quotient)\w*(?!\w)",
            text,
        )
    )
    return not explicit_division


def _explicit_comparison_relation_requested(
    goal: str, *, comparison_policy: str | None = None
) -> bool:
    """Recognize an explicit numeric consistency/comparison relation.

    This is a typed permission boundary, not an operation selector. A generic
    request to "check the total" remains a read; a relation is present only
    when the user names an aggregate/quantity and also asks whether it equals,
    matches or is consistent with another visible/prior value.
    """

    # New turn contracts carry the model's response permission independently
    # of its formulas. Never reinterpret a typed prohibition from a keyword
    # that also occurs in the prohibition itself. The lexical path remains
    # only for callers decoding contracts produced before this field existed.
    if comparison_policy is not None:
        if comparison_policy not in {"not_requested", "required", "prohibited"}:
            raise ValueError("comparison_policy is not a canonical enum")
        return comparison_policy == "required"
    text = _normalized(goal)
    aggregate_subject = bool(
        re.search(
            r"(?<!\w)(?:toplam\w*|sum\w*|adet\w*|sayi\w*|"
            r"ciro\w*|gelir\w*|oran\w*|yuzde\w*)(?!\w)",
            text,
        )
    )
    comparison_predicate = bool(
        re.search(
            r"(?<!\w)(?:tutarli\w*|tutarsiz\w*|esit\w*|denk\w*|"
            r"uyus\w*|karsilastir\w*|yuvarlama\w*|"
            r"veri\s+hatasi\w*|match\w*|consistent\w*)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:topla\w*|sum\w*).{0,96}"
            r"\d+(?:[.,]\d+)?'?(?:dan|den|tan|ten)\s+fark\w*(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:fark|sapma)\w*\s+(?:var|yok)\w*(?!\w)",
            text,
        )
    )
    explicit_counterpart = bool(
        re.search(r"(?<!\w)\d+(?:[.,]\d+)?(?!\w)", text)
        or re.search(
            r"(?<!\w)(?:az\s+once|onceki|yukaridaki|bu\s+toplam|"
            r"diger\s+toplam|previous|prior)(?!\w)",
            text,
        )
    )
    collection_sum = bool(
        re.search(
            r"(?<!\w)(?:adet|sayi|durum|kalem|satir|kategori)\w*"
            r"\s+toplam\w*(?!\w)",
            text,
        )
        or re.search(r"(?<!\w)sum\s+of\s+\w+", text)
    )
    return bool(
        aggregate_subject
        and comparison_predicate
        and (explicit_counterpart or collection_sum)
    )


def _explicit_difference_projection_requested(goal: str) -> bool:
    """Return whether the visible size of a comparison gap was requested."""

    text = _normalized(goal)
    return bool(
        re.search(
            r"(?<!\w)(?:fark(?:i|ini|lari|larini)?|sapma\w*|difference\w*|delta\w*|gap\w*)(?!\w)",
            text,
        )
        and (
            re.search(r"(?<!\w)\d+(?:[.,]\d+)?(?!\w)", text)
            or re.search(
                r"(?<!\w)(?:onceki|az\s+onceki|yukaridaki|prior|previous)(?!\w)",
                text,
            )
        )
    )


def _explicit_arithmetic_relation_requested(goal: str) -> bool:
    """Recognize a requested operand relation without selecting an operation."""

    text = _normalized(goal)
    subtract_verb_requested = bool(
        re.search(r"(?<!\w)cikar\w*(?!\w)", text)
        and (
            len(
                re.findall(
                    r"(?<!\w)\d+(?:[.,]\d+)?(?!\w)",
                    text,
                )
            )
            >= 2
            or len(_explicit_order_status_scopes_from_goal(goal)) >= 2
            or re.search(
                r"(?<!\w)(?:sayi|adet|tutar|ciro|gelir|toplam)\w*"
                r"(?:dan|den|tan|ten)(?!\w).{0,96}"
                r"(?<!\w)cikar\w*(?!\w)",
                text,
            )
        )
    )
    return bool(
        re.search(
            r"(?<!\w)(?:fark(?:i|ini|lari|larini)?|"
            r"oran\w*|yuzde\w*|percentage\w*|ratio\w*|"
            r"average\w*|ortalama\w*|divide\w*|division\w*|subtract\w*|"
            r"multiply\w*|minimum\w*|maximum\w*|min\w*|max\w*|"
            r"bol(?:erek|un|um|me|sun)?|carp\w*|topla)(?!\w)",
            text,
        )
        or subtract_verb_requested
        or _explicit_comparison_relation_requested(goal)
        or bool(re.search(r"(?<!\w)(?:/|×|\*|\+|-)(?!\w)", text))
    )


def _goal_has_ready_order_count_requirement(goal: str) -> bool:
    return bool(
        _goal_has_ready_context_intent(goal)
        and _goal_has_count_projection(goal)
    )


def _goal_has_order_status_distribution_requirement(goal: str) -> bool:
    text = _normalized(goal)
    if _goal_has_order_identifier(goal):
        return False
    if not re.search(r"(?<!\w)(?:siparis|orders?)\w*(?!\w)", text):
        return False
    if any(
        marker in text
        for marker in (
            "durum dagilim",
            "status distribution",
            "statü dagilim",
            "statu dagilim",
        )
    ):
        return True
    if re.search(
        r"(?<!\w)durum\w*.{0,40}(?:adet|sayi|count)\w*"
        r".{0,40}(?:dagit|dagilim|listele|goster)\w*(?!\w)",
        text,
    ) or re.search(
        r"(?<!\w)(?:dagit|dagilim)\w*.{0,40}durum\w*(?!\w)",
        text,
    ):
        return True
    return bool(
        any(
            marker in text
            for marker in (
                "genel",
                "genel olarak",
                "genel durum",
                "ozet",
                "toplu durum",
            )
        )
        and any(
            marker in text
            for marker in (
                "durum",
                "status",
                "ne halde",
                "nasil gidiyor",
            )
        )
    )


def _goal_has_cancellation_reason_distribution_requirement(goal: str) -> bool:
    """Recognize cancellation-reason evidence as distinct from status distribution."""

    text = _normalized(goal)
    return bool(
        re.search(r"(?<!\w)(?:iptal|cancel)\w*(?!\w)", text)
        and re.search(
            r"(?<!\w)(?:neden|sebep|gerekce|reason)\w*(?!\w)",
            text,
        )
    )


_ORDER_AGGREGATE_ANALYSIS_FIELDS = frozenset(
    {
        "count",
        "status",
        "amount",
        "item_sales_rows",
        "item_sales_quantity",
        "item_sales_order_count",
        "item_sales_amount",
        "risk",
    }
)
_ORDER_RECORD_PROJECTION_FIELDS = frozenset(
    {
        "order_number",
        "date",
        "customer_name",
        "address",
        "phone",
        "email",
        "tracking_number",
        "package_id",
        "item",
        "item_count",
        "sku",
        "barcode",
        "quantity",
        "cargo",
        "returns",
    }
)


def _is_order_aggregate_analysis_contract(
    *,
    entity: str,
    metric: str,
    requested_fields: list[str],
    limit: int | None = None,
    exact_record_intent: bool = False,
) -> bool:
    """Classify population analysis from typed shape, not one prompt phrase."""

    if entity != "order" or limit is not None or exact_record_intent:
        return False
    fields = {
        _compact_text(value).casefold()
        for value in list(requested_fields or [])
        if _compact_text(value)
    }
    item_sales_aggregate = bool(
        fields.intersection(
            {
                "item_sales_rows",
                "item_sales_quantity",
                "item_sales_order_count",
                "item_sales_amount",
            }
        )
    )
    if metric in {"list", "detail"} and not item_sales_aggregate:
        return False
    dimensions = fields.intersection(_ORDER_AGGREGATE_ANALYSIS_FIELDS)
    return bool(
        metric == "summary"
        or len(dimensions) >= 2
        or item_sales_aggregate
        or "risk" in dimensions
        or metric == "ratio"
    )


def _model_risk_summary_fields(payload: dict[str, Any]) -> list[str]:
    """Keep the model's risk aggregate separate from overall order metrics."""
    population = payload.get("metric_population")
    if population not in {None, "all_orders", "fulfillment_risks"}:
        raise ValueError("invalid_metric_population")
    if population == "all_orders":
        return []
    fields = list(dict.fromkeys(
        _canonical_requested_field(value)
        for value in list(payload.get("requested_fields") or [])
        if _canonical_requested_field(value)
    ))
    direct = {_canonical_requested_field(value)
              for value in list(payload.get("direct_output_fields") or [])}
    risk_population = payload.get("metric_population") == "fulfillment_risks"
    if risk_population:
        # The model declares the population. Generic column names in that
        # population are supplied by the canonical risk evidence object.
        allowed = {"risk", "count", "status", "reason", "scope", "store"}
        if not fields or not set(fields) <= allowed or not direct <= allowed:
            raise ValueError("risk_population_projection_conflict")
        fields = ["risk", *[f for f in fields if f in {"scope", "store"}]]
        direct = set(fields)
    if (
        payload.get("domain") == "orders"
        and payload.get("intent_kind") == "data_read"
        and payload.get("entity") == "order"
        and (payload.get("metric") == "summary" or risk_population)
        and (payload.get("request_shape") == "focused_analysis" or risk_population)
        and "risk" in fields
        and set(fields) <= {"risk", "scope", "store"}
        and direct <= set(fields)
        and not payload.get("derived_calculation")
        and not payload.get("derived_calculations")
        and not payload.get("grouped_projection")
    ):
        return fields
    return []


def _order_metric_requirements_from_goal(
    goal: str,
    *,
    entity: str,
    metric: str,
    status_scope: str,
    requested_fields: list[str],
) -> tuple[str, ...]:
    if entity != "order":
        return ()
    fields = {
        _compact_text(value).casefold()
        for value in list(requested_fields or [])
        if _compact_text(value)
    }
    record_specific_goal = bool(
        _goal_has_order_identifier(goal)
        or _goal_has_latest_single_order_intent(goal)
        or _goal_has_contextual_single_order_intent(goal)
    )
    aggregate_analysis = _is_order_aggregate_analysis_contract(
        entity=entity,
        metric=metric,
        requested_fields=requested_fields,
        exact_record_intent=record_specific_goal,
    )
    requirements: list[str] = []
    nonfinal_requested = nonfinal_orders_requested(goal)
    cancellation_reason_requested = bool(
        status_scope == "cancelled"
        and (
            "reason" in fields
            or _goal_has_cancellation_reason_distribution_requirement(goal)
        )
    )
    if status_scope == "cancelled":
        if "count" in fields or metric in {"count", "summary"}:
            requirements.append(ORDER_CANCELLED_COUNT_METRIC)
        if cancellation_reason_requested:
            requirements.append(
                ORDER_CANCELLATION_REASON_DISTRIBUTION_METRIC
            )
        if requirements:
            return normalize_order_metric_requirements(requirements)
    if status_scope == "nonfinal":
        if "count" in fields or metric in {"count", "summary"}:
            requirements.append(ORDER_NONFINAL_COUNT_METRIC)
        if "status" in fields or metric in {"status", "summary"}:
            requirements.append(
                ORDER_NONFINAL_STATUS_DISTRIBUTION_METRIC
            )
        return normalize_order_metric_requirements(requirements)
    if nonfinal_requested:
        if "count" in fields or metric in {"count", "summary"}:
            requirements.append(ORDER_NONFINAL_COUNT_METRIC)
        if (
            "status" in fields
            and _goal_has_order_status_distribution_requirement(goal)
        ):
            requirements.append(
                ORDER_NONFINAL_STATUS_DISTRIBUTION_METRIC
            )
    contextual_item_order_count = bool(
        "item_sales_order_count" in fields or metric == "item_order_count"
    )
    contextual_item_amount = bool(
        "item_sales_amount" in fields or metric == "item_gross_amount"
    )
    if not contextual_item_order_count and not contextual_item_amount and (
        _goal_has_total_order_count_requirement(goal) or (
            aggregate_analysis
            and "count" in fields
            and status_scope != "ready_to_ship"
        )
    ):
        requirements.append(ORDER_TOTAL_COUNT_METRIC)
    if _goal_has_ready_order_count_requirement(goal):
        requirements.append(ORDER_READY_TO_SHIP_COUNT_METRIC)
    if (
        "status" in fields
        and (
            aggregate_analysis
            or _goal_has_order_status_distribution_requirement(goal)
        )
    ):
        requirements.append(ORDER_STATUS_DISTRIBUTION_METRIC)
    if (
        "amount" in fields
        and (
            aggregate_analysis
            or metric in {"amount", "summary"}
            or _goal_has_total_order_revenue_requirement(goal)
        )
        and not record_specific_goal
        and not contextual_item_amount
    ):
        requirements.append(ORDER_REVENUE_TOTAL_METRIC)
    if "item_sales_rows" in fields:
        requirements.append(
            ORDER_ITEM_SALES_REPORT_METRIC
            if _goal_has_item_sales_report_intent(goal)
            else ORDER_ITEM_SALES_SUMMARY_METRIC
        )
    if "item_sales_quantity" in fields:
        requirements.append(ORDER_ITEM_SALES_SUMMARY_METRIC)
    if "item_sales_order_count" in fields:
        requirements.append(ORDER_ITEM_SALES_SUMMARY_METRIC)
    if "item_sales_amount" in fields:
        requirements.append(ORDER_ITEM_SALES_SUMMARY_METRIC)
    if aggregate_analysis and "risk" in fields:
        requirements.append(ORDER_FULFILLMENT_RISK_COUNT_METRIC)
    if not requirements:
        if metric == "count":
            requirements.append(
                ORDER_READY_TO_SHIP_COUNT_METRIC
                if status_scope == "ready_to_ship"
                else ORDER_TOTAL_COUNT_METRIC
            )
        elif metric == "summary":
            requirements.extend(
                (
                    ORDER_TOTAL_COUNT_METRIC,
                    ORDER_STATUS_DISTRIBUTION_METRIC,
                )
            )
    return normalize_order_metric_requirements(requirements)


def _goal_has_operation_overview_intent(goal: str) -> bool:
    text = _normalized(goal)
    has_order_domain = any(token in text for token in ("siparis", "order"))
    if not has_order_domain:
        return False
    # This legacy overview intent owns only a vague "toparla / task" request or
    # an explicit "siparis operasyonu" phrase. Merely asking for an
    # "operasyon riski" alongside status, revenue or count is a typed
    # multi-signal goal; treating that adjective as the fixed overview template
    # silently discards a correct model-authored atomic plan.
    return bool(
        any(token in text for token in ("toparla", "gorev", "task"))
        or "siparis operasyon" in text
        or "order operation" in text
    )


def _full_context_prompt_from_goal(goal: str) -> str:
    text = _compact_text(goal)
    cleaned = re.sub(
        r"(?i)\b(?:kargoya\s+hazir|ready\s+to\s+ship|readytoship|hazir)\s+(?:siparisleri|siparisler|siparisi|paketleri|paketler|orders?)?\s*(?:bul|getir|goster|listele|soyle)?\s*(?:,|\bve\b)?\s*",
        " ",
        text,
    )
    cleaned = re.sub(
        r"(?i)\b(?:siparisleri|siparisler|paketleri|paketler)\s+(?:bul|getir|goster|listele|soyle)\s*(?:,|\bve\b)?\s*",
        " ",
        cleaned,
    )
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" ,.;:")
    if not cleaned:
        return "listedeki siparis detayini ve kalemlerini getir"
    normalized = _normalized(cleaned)
    if not _goal_has_order_detail_intent(cleaned):
        cleaned = f"{cleaned} siparis detayini ve kalemlerini getir"
    elif "siparis" not in normalized and "order" not in normalized:
        cleaned = f"{cleaned} siparis"
    return cleaned


def _goal_has_fetch_intent(goal: str) -> bool:
    return orders_fetch_intent_requested(_normalized(goal))


def _goal_has_stale_return_intent(goal: str) -> bool:
    text = _normalized(goal)
    stale_signal = any(
        token in text
        for token in (
            "webde yok",
            "pazaryerinde yok",
            "gorunmuyor",
            "gozukmuyor",
            "stale",
            "bayat",
            "reconcile",
            "uyusm",
        )
    )
    return bool(
        stale_signal
        and re.search(r"(?<!\w)(?:iade\w*|returns?|claims?)(?!\w)", text)
    )


def _goal_has_stale_return_cleanup_intent(goal: str) -> bool:
    text = _normalized(goal)
    return _goal_has_stale_return_intent(goal) and any(
        token in text for token in ("temizle", "kaldir", "sil", "gizle", "pasifle", "isaretle", "duzelt", "cleanup")
    )


def _goal_has_stale_return_restore_intent(goal: str) -> bool:
    text = _normalized(goal)
    return any(token in text for token in ("stale", "bayat", "eski kayit")) and any(
        token in text for token in ("geri al", "aktif et", "restore", "geri getir", "canlandir")
    )


def _goal_has_profit_export_intent(goal: str) -> bool:
    text = _normalized(goal)
    return any(token in text for token in ("kar", "profit")) and any(token in text for token in ("excel", "xlsx", "rapor", "aktar", "export"))


def _goal_prohibits_report_export(goal: str) -> bool:
    """Return whether the user explicitly forbids creating an artifact.

    Report analysis and artifact creation are separate operations. A request
    such as "burada listele, dosya olusturma" must still use the canonical
    report snapshot, but it must not be reclassified as an export action merely
    because the sentence contains both ``liste`` and ``dosya``.
    """

    text = _normalized(goal)
    if any(
        marker in text
        for marker in (
            "do not create a file",
            "dont create a file",
            "do not export",
            "dont export",
            "without creating a file",
            "without exporting",
            "no file",
            "excel istemiyorum",
            "xlsx istemiyorum",
            "dosya istemiyorum",
        )
    ):
        return True
    return bool(
        re.search(
            r"(?<!\w)(?:dosya|excel|xlsx|rapor)\s+"
            r"(?:olusturma|uretme|yazma|kaydetme|aktarma|indirme)(?!\w)"
            r"(?=\s*(?:$|[,.!?;:]|(?:sadece|yalnizca|burada|ekranda|ama|fakat)\b))",
            text,
        )
        or re.search(
            r"(?<!\w)(?:export|disa\s+aktar)\s+(?:etme|yapma)(?!\w)",
            text,
        )
    )


def _goal_has_report_export_intent(goal: str) -> bool:
    text = _normalized(goal)
    if _goal_prohibits_report_export(goal):
        return False
    return any(token in text for token in ("excel", "xlsx")) or (
        any(token in text for token in ("rapor", "liste"))
        and any(token in text for token in ("dosya", "aktar", "export", "indir"))
    )


def _hypothetical_action_question_requested(goal: str) -> bool:
    """Detect explanation questions that mention an action without requesting it."""

    text = _normalized(goal)
    return bool(
        re.search(
            r"\b(?:desem|istesem|isteseydim|isteseydin|yapsam|yapsaydim|"
            r"yapsaydin|olsaydi|farz et|varsayalim)\b",
            text,
        )
        or any(
            token in text
            for token in (
                "ne yapardin",
                "nasil yapardin",
                "nasil ilerlerdin",
                "if i asked",
                "if the user asked",
                "what would you do",
                "how would you",
            )
        )
    )


def _explicit_local_business_read_prohibited(message: str) -> bool:
    """Return whether the local durable source itself is explicitly forbidden."""

    text = _normalized(message)
    return bool(
        re.search(
            r"(?<!\w)(?:yerel|lokal|local)?\s*"
            r"(?:kayit\w*|snapshot\w*|veri\s*taban\w*|veritaban\w*|database\w*|db\w*|cache\w*|onbellek\w*)"
            r".{0,24}(?:okuma|bakma|kullanma|sorgulama|do\s+not\s+read|do\s+not\s+query)(?!\w)",
            text,
        )
    )


def _explicit_local_business_read_requested(message: str) -> bool:
    """Return whether the user asks to read a durable local business source.

    Source choice and operation permission are independent axes.  In
    particular, forbidding an external marketplace refresh must not also
    forbid a read-only operation over the application's local snapshot.  Keep
    this vocabulary at the language boundary so every Orders intent benefits
    from the same rule instead of accumulating prompt-specific corrections.
    """

    text = _normalized(message)
    read_intent_requested = bool(
        re.search(
            r"(?<!\w)(?:bak\w*|oku\w*|getir\w*|goster\w*|soyle\w*|"
            r"kac|toplam|say\w*|liste\w*|ozet\w*|analiz\w*|dagit\w*|ver|"
            r"cikar\w*|show\w*|get\w*|read\w*|tell\w*|count\w*|list\w*|"
            r"summari[sz]e\w*|analy[sz]e\w*)(?!\w)",
            text,
        )
        or "?" in str(message or "")
    )
    local_source_requested = bool(
        re.search(
            r"(?<!\w)(?:mevcut\s+)?(?:yerel|lokal|local)\s+"
            r"(?:kayit\w*|snapshot\w*|veri\w*|db\w*|cache\w*|onbellek\w*)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:veri\s*taban|veritaban|database|onbellek|cache)\w*(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:elindeki|eldeki|programdaki|sistemdeki)\s+"
            r"(?:siparis|order|iade|return|claim|kayit|veri)\w*(?!\w)",
            text,
        )
        or (
            orders_external_refresh_prohibited(message)
            and any(
                token in text
                for token in ("siparis", "order", "iade", "return", "claim")
            )
            and read_intent_requested
        )
    )
    if not local_source_requested:
        return False

    if _explicit_local_business_read_prohibited(message):
        return False

    return read_intent_requested


def _existing_observations_only_requested(message: str) -> bool:
    """Recognize an explicit no-new-operation permission boundary."""

    text = _normalized(message)
    # A conversational reference can establish the permission boundary even
    # when the user does not repeat the literal words "tool" or "query". Keep
    # this narrower than a generic local-snapshot request: only an exclusive
    # reference to already visible/verified evidence forbids every new
    # operation.
    same_evidence_calculation = bool(
        re.search(
            r"(?<!\w)(?:ayni|bu|onceki|az\s+onceki|yukaridaki|same|prior|previous)\b"
            r".{0,24}(?:veri|sayi|sonuc|cevap|kanit|observation|value|result|data)\w*"
            r".{0,96}(?:hesapla\w*|bul\w*|topla\w*|bol\w*|cikar\w*|carp\w*|"
            r"karsilastir\w*|calculate\w*|sum\w*|divide\w*|subtract\w*|"
            r"multiply\w*|compare\w*)(?!\w)",
            text,
        )
    )
    prior_evidence_only = bool(
        same_evidence_calculation
        or re.search(
            r"(?<!\w)(?:yalniz|yalnizca|sadece|only)\b.{0,48}"
            r"(?:konusmadaki|onceki|az\s+onceki|yukaridaki|mevcut|prior|previous)\b"
            r".{0,48}(?:dogrulanmis\s+)?"
            r"(?:sayi|sonuc|cevap|kanit|observation|oran|yuzde|veri|value|result)\w*"
            r".{0,32}(?:kullan\w*|hesapla\w*|acikla\w*|use\w*|calculate\w*|explain\w*)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:konusmadaki|onceki|az\s+onceki|yukaridaki|prior|previous)\b"
            r".{0,48}(?:dogrulanmis\s+)?(?:kanit|observation|sonuc|sayi|oran|yuzde|value|result)\w*"
            r".{0,24}(?:disina\s+cikma|haricinde\s+kullanma|only)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:ayni|bu|o|onceki|az\s+onceki|yukaridaki|same|prior|previous)\b"
            r".{0,32}(?:veri|sayi|sonuc|cevap|kanit|observation|value|result|data)\w*"
            r".{0,24}(?:tekrar|yeniden|again)\s*"
            r"(?:okuma|sorgulama|cekme|toplama|read|query|fetch)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:veri|sayi|sonuc|cevap|kanit|observation|value|result|data)\w*"
            r".{0,48}(?:tekrar|yeniden|again)\s*"
            r"(?:okuma|sorgulama|cekme|toplama|read|query|fetch)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:do\s+not|don't)\s+(?:re-?)?"
            r"(?:read|query|fetch)\b.{0,32}(?:same|prior|previous)\s+data(?!\w)",
            text,
        )
    )
    if prior_evidence_only:
        return True
    if _explicit_local_business_read_requested(message):
        # Blocking an external API refresh does not block a read-only local DB
        # operation that the same sentence explicitly requests.  The source
        # and operation policy are independent typed axes.
        return False
    if _explicit_local_business_read_prohibited(message):
        return True
    direct_markers = (
        "tool calistirma",
        "tool kullanma",
        "arac calistirma",
        "arac kullanma",
        "sorgu calistirma",
        "sorgu acma",
        "yeni sorgu acmadan",
        "yeniden sorgulama",
        "tekrar sorgulama",
        "veri cekme",
        "yeniden veri cekme",
        "tekrar veri cekme",
        "yeni veri okuma",
        "yeniden veri okuma",
        "tekrar veri okuma",
        "yeni veri islemi calistirma",
        "yeni islem calistirma",
        "yeni bir islem yapma",
        "islem yapma",
        "without running a tool",
        "without using a tool",
        "without a new query",
        "without querying again",
        "without fetching data",
        "do not run a tool",
        "do not query",
        "do not fetch",
    )
    if any(marker in text for marker in direct_markers):
        return True
    return bool(
        re.search(
            r"(?<!\w)(?:yeni|tekrar|yeniden)?\s*"
            r"(?:veri|tool|arac|sorgu|islem)\w*.{0,32}"
            r"(?:calistirma|cagirma|kullanma|cekme|sorgulama|yapma|acma)(?:dan|den)?(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:yeni|tekrar|yeniden)\s+(?:bir\s+)?"
            r"(?:veri|tool|arac|sorgu|islem)\w*\s+"
            r"(?:yok|olmasin)(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:calistirmadan|cagirmadan|kullanmadan|cekmeden|"
            r"sorgulamadan|yapmadan).{0,32}"
            r"(?:acikla|anlat|soyle|cevapla)(?!\w)",
            text,
        )
    )


def _goal_has_item_sales_report_intent(goal: str) -> bool:
    text = _normalized(goal)
    return (
        any(token in text for token in ("en cok satan", "cok satan", "top selling"))
        and any(token in text for token in ("urun", "kalem", "product", "item"))
    )


_ORDER_IDENTIFIER_TOKEN_PATTERN = re.compile(
    (
        r"\bORD[-_][A-Z0-9][A-Z0-9_-]*\b|"
        # A decimal/grouped monetary value is not an order id merely because
        # its integer part happens to contain six or more digits.  Keep the
        # numeric token isolated from decimal/group separators at both edges.
        r"(?<![\w.,])\d{6,}(?![\w.,])"
    ),
    flags=re.IGNORECASE,
)


def _goal_has_explicit_order_identity_context(goal: str) -> bool:
    text = _normalized(goal)
    return bool(
        re.search(
            r"(?<!\w)(?:siparis|order)\w*.{0,28}"
            r"(?:no|numara|number|id)\w*(?!\w)",
            text,
        )
        or re.search(
            r"(?<!\w)(?:no|numara|number|id)\w*.{0,28}"
            r"(?:siparis|order)\w*(?!\w)",
            text,
        )
        or re.search(
            r"(?<![\w.,])\d{6,}(?![\w.,]).{0,18}"
            r"(?:numarali\s+)?(?:siparis|order)\w*(?!\w)",
            text,
        )
    )


def _goal_assigns_numeric_non_identifier_role(goal: str) -> bool:
    """Return whether unprefixed numbers are explicitly used as a metric/time.

    This is a language-boundary distinction rather than a business heuristic:
    the same long number can denote a record id, a currency amount, a ratio or
    a timestamp.  An explicit order-number phrase wins; otherwise clear numeric
    role words prevent an aggregate value from silently becoming record scope.
    """

    text = _normalized(goal)
    return bool(
        re.search(r"[%₺$€]", _compact_text(goal))
        or any(
            marker in text
            for marker in (
                "ciro",
                "tutar",
                "para birimi",
                "rakam",
                "gelir",
                "kazanc",
                "fiyat",
                "bedel",
                "oran",
                "yuzde",
                "adet",
                "miktar",
                "timestamp",
                "startdate",
                "enddate",
                "milisaniye",
                "tarih",
            )
        )
        or bool(
            re.search(
                r"(?<!\w)(?:try|tl|usd|eur|gbp)(?!\w)",
                text,
            )
        )
    )


def _goal_has_order_identifier(goal: str) -> bool:
    text = _compact_text(goal)
    matches = list(_ORDER_IDENTIFIER_TOKEN_PATTERN.finditer(text))
    if not matches:
        return False
    if any(re.search(r"[A-Za-z]", match.group(0)) for match in matches):
        return True
    if _goal_has_explicit_order_identity_context(goal):
        return True
    return not _goal_assigns_numeric_non_identifier_role(goal)


def _order_identifiers_from_goal(goal: str) -> list[str]:
    text = _compact_text(goal)
    identifiers: list[str] = []
    explicit_identity = _goal_has_explicit_order_identity_context(goal)
    non_identifier_role = _goal_assigns_numeric_non_identifier_role(goal)
    for token_match in _ORDER_IDENTIFIER_TOKEN_PATTERN.finditer(text):
        match = token_match.group(0)
        is_prefixed = bool(re.search(r"[A-Za-z]", match))
        if not is_prefixed and non_identifier_role and not explicit_identity:
            continue
        value = match.upper().replace("_", "-") if is_prefixed else match
        if value not in identifiers:
            identifiers.append(value)
    return identifiers


def _normalize_orders_plan_step_ids(
    accepted: list[str],
    rejected: list[str],
    goal: str,
    max_steps: int,
) -> tuple[list[str], list[str]]:
    limit = max(1, int(max_steps or 8))
    normalized = list(accepted)
    normalized_rejected = list(rejected)

    if _goal_has_stale_return_restore_intent(goal) or _goal_has_stale_return_intent(goal):
        if _goal_has_stale_return_restore_intent(goal):
            stale_step = "returns.stale.restore.prepare"
        else:
            stale_step = "returns.stale.mark.prepare" if _goal_has_stale_return_cleanup_intent(goal) else "returns.stale.reconcile"
        stale_steps = {stale_step}
        dropped = [step_id for step_id in normalized if step_id not in stale_steps]
        normalized = [step_id for step_id in normalized if step_id in stale_steps]
        normalized_rejected.extend(dropped)
        if stale_step not in normalized:
            normalized.append(stale_step)

    if _goal_has_operation_overview_intent(goal):
        overview_steps = {"orders.ready_to_ship", "orders.fulfillment_risk", "returns.waiting.list"}
        dropped = [step_id for step_id in normalized if step_id not in overview_steps]
        normalized = [step_id for step_id in normalized if step_id in overview_steps]
        normalized_rejected.extend(dropped)
        for step_id in ("orders.ready_to_ship", "orders.fulfillment_risk", "returns.waiting.list"):
            if step_id not in normalized:
                normalized.append(step_id)
        ordered_overview_steps = [
            step_id
            for step_id in ("orders.ready_to_ship", "orders.fulfillment_risk", "returns.waiting.list")
            if step_id in normalized
        ]
        normalized = ordered_overview_steps + [step_id for step_id in normalized if step_id not in ordered_overview_steps]

    if _goal_has_order_detail_intent(goal):
        detail_steps = {"orders.full_context"}
        if _goal_has_ready_context_intent(goal) and not _goal_has_order_identifier(goal):
            detail_steps.add("orders.ready_to_ship")
        dropped = [step_id for step_id in normalized if step_id not in detail_steps]
        normalized = [step_id for step_id in normalized if step_id in detail_steps]
        normalized_rejected.extend(dropped)
        if "orders.full_context" not in normalized:
            normalized.append("orders.full_context")
        if "orders.ready_to_ship" in detail_steps and "orders.ready_to_ship" not in normalized:
            detail_index = normalized.index("orders.full_context")
            normalized.insert(detail_index, "orders.ready_to_ship")
        ordered_detail_steps = [
            step_id
            for step_id in ("orders.ready_to_ship", "orders.full_context")
            if step_id in normalized
        ]
        normalized = ordered_detail_steps + [step_id for step_id in normalized if step_id not in ordered_detail_steps]

    if _goal_has_label_intent(goal) or _goal_has_label_extracted_intent(goal):
        scope_step = None if _goal_has_order_identifier(goal) else _order_scope_read_step(goal)
        label_steps: set[str] = set()
        if scope_step:
            label_steps.add(scope_step)
        if _goal_has_label_intent(goal):
            label_steps.add("orders.labels.prepare")
        if _goal_has_label_extracted_intent(goal):
            label_steps.add("orders.labels.extracted.prepare")
        dropped = [step_id for step_id in normalized if step_id not in label_steps]
        normalized = [step_id for step_id in normalized if step_id in label_steps]
        normalized_rejected.extend(dropped)
        if _goal_has_label_intent(goal) and "orders.labels.prepare" not in normalized:
            normalized.append("orders.labels.prepare")
        if _goal_has_label_extracted_intent(goal) and "orders.labels.extracted.prepare" not in normalized:
            normalized.append("orders.labels.extracted.prepare")
        if scope_step and scope_step not in normalized:
            first_write_indexes = [
                normalized.index(step_id)
                for step_id in ("orders.labels.prepare", "orders.labels.extracted.prepare")
                if step_id in normalized
            ]
            insert_at = min(first_write_indexes) if first_write_indexes else 0
            normalized.insert(insert_at, scope_step)
        ordered_label_candidates = [
            step_id
            for step_id in (scope_step, "orders.labels.prepare", "orders.labels.extracted.prepare")
            if step_id
        ]
        ordered_label_steps = [
            step_id
            for step_id in ordered_label_candidates
            if step_id in normalized
        ]
        normalized = ordered_label_steps + [step_id for step_id in normalized if step_id not in ordered_label_steps]

    if _goal_has_return_approval_intent(goal):
        approval_steps = {"returns.waiting.list", "returns.approve.prepare"}
        dropped = [step_id for step_id in normalized if step_id not in approval_steps]
        normalized = [step_id for step_id in normalized if step_id in approval_steps]
        normalized_rejected.extend(dropped)
        if "returns.approve.prepare" not in normalized:
            normalized.append("returns.approve.prepare")
        if "returns.waiting.list" not in normalized:
            approve_index = normalized.index("returns.approve.prepare")
            normalized.insert(approve_index, "returns.waiting.list")
        waiting_index = normalized.index("returns.waiting.list")
        approve_index = normalized.index("returns.approve.prepare")
        if waiting_index > approve_index:
            normalized.pop(waiting_index)
            approve_index = normalized.index("returns.approve.prepare")
            normalized.insert(approve_index, "returns.waiting.list")

    if _goal_has_cargo_change_intent(goal):
        scope_step = None if _goal_has_order_identifier(goal) else _order_scope_read_step(goal)
        explicit_cargo_steps = [
            step_id
            for step_id in (
                "orders.cargo.change.prepare",
                "orders.cargo.bulk_change.prepare",
            )
            if step_id in normalized
        ]
        # A schema-valid model plan already owns the single-vs-bulk business
        # choice. Raw keyword helpers may retrieve candidates or support the
        # legacy no-plan path, but they must not replace one explicit canonical
        # operation with its sibling (for example when "12 kaydin tamaminda"
        # does not contain the old "tum/hepsi" tokens). Argument binding and
        # semantic verification remain responsible for target cardinality.
        wanted_cargo_step = (
            explicit_cargo_steps[0]
            if len(explicit_cargo_steps) == 1
            else "orders.cargo.bulk_change.prepare"
            if _goal_has_cargo_bulk_change_intent(goal)
            else "orders.cargo.change.prepare"
        )
        other_cargo_step = "orders.cargo.change.prepare" if wanted_cargo_step == "orders.cargo.bulk_change.prepare" else "orders.cargo.bulk_change.prepare"
        cargo_steps = {wanted_cargo_step}
        if scope_step:
            cargo_steps.add(scope_step)
        dropped = [step_id for step_id in normalized if step_id not in cargo_steps]
        if other_cargo_step in normalized:
            dropped.append(other_cargo_step)
        normalized = [step_id for step_id in normalized if step_id in cargo_steps]
        normalized_rejected.extend(dropped)
        if wanted_cargo_step not in normalized:
            normalized.append(wanted_cargo_step)
        if scope_step and scope_step not in normalized:
            change_index = normalized.index(wanted_cargo_step)
            normalized.insert(change_index, scope_step)
        if scope_step:
            ready_index = normalized.index(scope_step)
            change_index = normalized.index(wanted_cargo_step)
            if ready_index > change_index:
                normalized.pop(ready_index)
                change_index = normalized.index(wanted_cargo_step)
                normalized.insert(change_index, scope_step)

    if _goal_has_profit_export_intent(goal):
        profit_steps = {"orders.profit.export.prepare"}
        scope_step = _order_scope_read_step(goal)
        if not _goal_has_order_identifier(goal):
            profit_steps.add(scope_step)
        dropped = [step_id for step_id in normalized if step_id not in profit_steps]
        normalized = [step_id for step_id in normalized if step_id in profit_steps]
        normalized_rejected.extend(dropped)
        if "orders.profit.export.prepare" not in normalized:
            normalized.append("orders.profit.export.prepare")
        if not _goal_has_order_identifier(goal) and scope_step not in normalized:
            export_index = normalized.index("orders.profit.export.prepare")
            normalized.insert(export_index, scope_step)
        ordered_profit_steps = [
            step_id
            for step_id in (scope_step, "orders.profit.export.prepare")
            if step_id in normalized
        ]
        normalized = ordered_profit_steps + [step_id for step_id in normalized if step_id not in ordered_profit_steps]

    if _goal_has_fetch_intent(goal):
        fetch_steps = {"orders.fetch.prepare"}
        dropped = [step_id for step_id in normalized if step_id not in fetch_steps]
        normalized = [step_id for step_id in normalized if step_id in fetch_steps]
        normalized_rejected.extend(dropped)
        if "orders.fetch.prepare" not in normalized:
            normalized.append("orders.fetch.prepare")

    deduped: list[str] = []
    for step_id in normalized:
        if step_id not in deduped:
            deduped.append(step_id)
        if len(deduped) >= limit:
            break
    deduped_rejected: list[str] = []
    for step_id in normalized_rejected:
        if step_id not in deduped and step_id not in deduped_rejected:
            deduped_rejected.append(step_id)
    return deduped, deduped_rejected


def _validate_orders_plan_step_ids(step_ids: list[str], goal: str, max_steps: int) -> tuple[list[str], list[str]]:
    accepted: list[str] = []
    rejected: list[str] = []
    for step_id in step_ids:
        clean = _compact_text(step_id)
        if not clean or clean in accepted:
            continue
        if _step_allowed_for_goal(clean, goal):
            accepted.append(clean)
        else:
            rejected.append(clean)
        if len(accepted) >= max(1, int(max_steps or 8)):
            break
    return _normalize_orders_plan_step_ids(accepted, rejected, goal, max_steps)


def _canonical_step_id_for_operation(operation_id: str) -> str:
    clean_operation = _compact_text(operation_id)
    if not clean_operation:
        return ""
    direct = _DIRECT_OPERATION_LEGACY_STEP.get(clean_operation)
    if direct:
        return direct
    return next(
        (
            step_id
            for step_id, candidate_operation in _LEGACY_STEP_DIRECT_OPERATION.items()
            if candidate_operation == clean_operation
        ),
        "",
    )


def _compile_orders_direct_plan_specs(
    specs: list[dict[str, Any]],
    goal: str,
    *,
    allowed_operations: dict[str, Any],
    max_steps: int,
    typed_context: list[dict[str, Any]] | None = None,
    semantic_contract: dict[str, Any] | None = None,
) -> tuple[list[str], list[dict[str, Any]], dict[str, Any]]:
    """Normalize a model-authored graph without inventing missing business steps."""

    provider_specs = [dict(spec) for spec in specs if isinstance(spec, dict)]
    typed_contract = dict(semantic_contract or {})
    typed_metric_requirements = normalize_order_metric_requirements(
        typed_contract.get("metric_requirements") or []
    )
    semantic_by_provider_id: dict[str, str] = {}
    provider_id_by_semantic: dict[str, str] = {}
    provider_order: list[str] = []
    semantic_order: list[str] = []
    scoped_read_semantic_ids: set[str] = set()
    first_arguments_by_semantic: dict[str, dict[str, Any]] = {}
    for spec in provider_specs:
        provider_id = _compact_text(spec.get("id"))
        if not provider_id:
            continue
        operation_id = _compact_text(spec.get("operation_id"))
        semantic_id = (
            _canonical_step_id_for_operation(operation_id)
            or operation_id
            or provider_id
        )
        operation_tool = allowed_operations.get(operation_id)
        operation_domain = _compact_text(
            getattr(operation_tool, "domain", "")
        ).casefold()
        if (
            operation_domain
            and semantic_id in provider_id_by_semantic
            and (
                operation_domain != "orders"
                or (
                    bool(getattr(operation_tool, "read_only", False))
                    and not bool(getattr(operation_tool, "destructive", False))
                    and _compact_text(getattr(operation_tool, "action_type", "read")) == "read"
                    and dict(spec.get("arguments") or {}) != first_arguments_by_semantic.get(semantic_id)
                )
            )
        ):
            # The same read can address different periods or populations.
            # Preserve the model's distinct scope and downstream bindings.
            semantic_id = f"{semantic_id}::{provider_id}"
            if operation_domain == "orders":
                scoped_read_semantic_ids.add(semantic_id)
        semantic_by_provider_id[provider_id] = semantic_id
        provider_id_by_semantic.setdefault(semantic_id, provider_id)
        first_arguments_by_semantic.setdefault(semantic_id, dict(spec.get("arguments") or {}))
        provider_order.append(provider_id)
        semantic_order.append(semantic_id)

    cross_domain_semantic_ids = {
        semantic_by_provider_id.get(_compact_text(spec.get("id")), "")
        for spec in provider_specs
        if (
            allowed_operations.get(_compact_text(spec.get("operation_id"))) is not None
            and _compact_text(
                getattr(
                    allowed_operations.get(_compact_text(spec.get("operation_id"))),
                    "domain",
                    "",
                )
            ).casefold()
            != "orders"
        )
    }
    orders_semantic_order = [
        semantic_id
        for semantic_id in semantic_order
        if semantic_id not in cross_domain_semantic_ids
    ]
    shared_configuration_proposal = not orders_semantic_order and any(
        getattr(allowed_operations.get(_compact_text(spec.get("operation_id"))), "domain", "") == "workflows"
        and getattr(allowed_operations.get(_compact_text(spec.get("operation_id"))), "requires_approval", False)
        and getattr(allowed_operations.get(_compact_text(spec.get("operation_id"))), "action_type", "") == "prepare_write"
        for spec in provider_specs
    )
    if shared_configuration_proposal:
        # The validated graph prepares agent configuration. Quoted future
        # business instructions are part of that proposal, not missing Orders
        # operations to execute now. Exact semantic review still precedes it.
        normalized_orders_semantic_ids = []
        semantic_rejected = []
        semantic_authority = "shared_configuration_model_plan"
    elif typed_metric_requirements or order_status_codes(typed_contract):
        # A typed metric contract is the semantic authority for population and
        # aggregate reads.  Legacy raw-goal helpers such as the old
        # "kalem/urunleri => orders.full_context" rewrite must not replace a
        # schema-valid model-authored aggregate graph.  Coverage and scope are
        # enforced below by operation contracts and metric provenance.
        normalized_orders_semantic_ids = list(
            dict.fromkeys(orders_semantic_order)
        )[: max(1, int(max_steps or 1))]
        semantic_rejected: list[str] = []
        semantic_authority = (
            "typed_exact_status_contract"
            if order_status_codes(typed_contract)
            else "typed_metric_contract"
        )
    else:
        normalized_orders_semantic_ids, semantic_rejected = (
            _normalize_orders_plan_step_ids(
                orders_semantic_order,
                [],
                goal,
                max_steps,
            )
        )
        semantic_authority = "legacy_goal_policy"
    normalized_semantic_ids: list[str] = []
    for semantic_id in semantic_order:
        if (
            semantic_id in cross_domain_semantic_ids
            or semantic_id in scoped_read_semantic_ids
            or semantic_id in normalized_orders_semantic_ids
        ) and semantic_id not in normalized_semantic_ids:
            normalized_semantic_ids.append(semantic_id)
    for semantic_id in normalized_orders_semantic_ids:
        if semantic_id not in normalized_semantic_ids:
            normalized_semantic_ids.append(semantic_id)
    normalized_semantic_ids = normalized_semantic_ids[: max(1, int(max_steps or 1))]
    provider_specs_by_id = {
        _compact_text(spec.get("id")): dict(spec)
        for spec in provider_specs
        if _compact_text(spec.get("id"))
    }
    # A model-authored action may depend on a more specific canonical read
    # than the legacy keyword normalizer would choose (for example a filtered,
    # sorted ``orders.query`` whose first row feeds a prepare operation).
    # Preserve only the transitive declared dependency closure of operations
    # that survived semantic policy.  This keeps model composition authority
    # without retaining unrelated reads or inventing deterministic steps.
    retained_provider_ids = {
        provider_id
        for provider_id in provider_order
        if semantic_by_provider_id.get(provider_id) in normalized_semantic_ids
    }
    dependency_frontier = list(retained_provider_ids)
    preserved_dependency_ids: set[str] = set()
    while dependency_frontier:
        current_provider_id = dependency_frontier.pop()
        current_spec = provider_specs_by_id.get(current_provider_id) or {}
        for dependency_id in list(current_spec.get("depends_on") or []):
            clean_dependency_id = _compact_text(dependency_id)
            if (
                not clean_dependency_id
                or clean_dependency_id not in provider_specs_by_id
                or clean_dependency_id in retained_provider_ids
            ):
                continue
            retained_provider_ids.add(clean_dependency_id)
            preserved_dependency_ids.add(clean_dependency_id)
            dependency_frontier.append(clean_dependency_id)
    if preserved_dependency_ids:
        retained_semantics = set(normalized_semantic_ids)
        retained_semantics.update(
            semantic_by_provider_id.get(provider_id, "")
            for provider_id in preserved_dependency_ids
        )
        normalized_semantic_ids = list(
            dict.fromkeys(
                [
                    semantic_by_provider_id.get(provider_id, "")
                    for provider_id in provider_order
                    if semantic_by_provider_id.get(provider_id, "")
                    in retained_semantics
                ]
                + [
                    semantic_id
                    for semantic_id in normalized_semantic_ids
                    if semantic_id
                ]
            )
        )[: max(1, int(max_steps or 1))]
    explicit_order_targets = any(
        bool(
            [
                value
                for value in list((spec.get("arguments") or {}).get("order_numbers") or [])
                if _compact_text(value)
            ]
        )
        and (
            _canonical_step_id_for_operation(spec.get("operation_id"))
            or _compact_text(spec.get("id"))
        )
        in {
            "orders.labels.prepare",
            "orders.labels.extracted.prepare",
            "orders.cargo.change.prepare",
            "orders.cargo.bulk_change.prepare",
        }
        for spec in provider_specs
    )
    typed_order_context_available = any(
        _compact_text(row.get("kind")) == "order_selection"
        and bool(
            list(row.get("order_numbers") or [])
            or list(row.get("record_refs") or [])
        )
        for row in list(typed_context or [])
        if isinstance(row, dict)
    )
    if explicit_order_targets or typed_order_context_available:
        normalized_semantic_ids = [
            semantic_id
            for semantic_id in normalized_semantic_ids
            if not (
                semantic_id in {"orders.ready_to_ship", "orders.recent"}
                and semantic_id not in semantic_order
            )
        ]
    inserted = [
        semantic_id
        for semantic_id in normalized_semantic_ids
        if semantic_id not in provider_id_by_semantic
    ]
    dropped = [
        provider_id
        for provider_id in provider_order
        if semantic_by_provider_id.get(provider_id) not in normalized_semantic_ids
    ]
    by_provider_id = {
        _compact_text(spec.get("id")): dict(spec)
        for spec in provider_specs
        if _compact_text(spec.get("id"))
    }

    # Missing semantic steps are verifier evidence for a model repair. They are
    # deliberately not materialized here: doing so would make deterministic
    # code the business planner. Dropping an explicitly disallowed/irrelevant
    # model step remains a policy operation and does not invent new work.
    executable_semantic_ids = [
        semantic_id
        for semantic_id in normalized_semantic_ids
        if semantic_id in provider_id_by_semantic
    ]
    compiled: list[dict[str, Any]] = []
    for semantic_id in executable_semantic_ids:
        provider_id = provider_id_by_semantic.get(semantic_id, "")
        spec = dict(by_provider_id.get(provider_id) or {})
        if spec:
            compiled.append(spec)

    normalized_ids = [_compact_text(spec.get("id")) for spec in compiled]
    known_ids = set(normalized_ids)
    scope_provider_id = next(
        (
            _compact_text(spec.get("id"))
            for spec in compiled
            if (
                _canonical_step_id_for_operation(spec.get("operation_id"))
                or _compact_text(spec.get("id"))
            )
            in {"orders.ready_to_ship", "orders.recent"}
        ),
        "",
    )
    previous_write_id = ""
    target_write_steps = {
        "orders.labels.prepare",
        "orders.labels.extracted.prepare",
        "orders.cargo.change.prepare",
        "orders.cargo.bulk_change.prepare",
    }
    for spec in compiled:
        step_id = _compact_text(spec.get("id"))
        semantic_id = (
            _canonical_step_id_for_operation(spec.get("operation_id")) or step_id
        )
        dependencies = [
            value
            for value in list(spec.get("depends_on") or [])
            if value in known_ids and value != step_id
        ]
        arguments = dict(spec.get("arguments") or {})
        if semantic_id in target_write_steps and scope_provider_id:
            has_explicit_target_or_query = bool(
                _compact_text(arguments.get("query"))
                or [
                    value
                    for value in list(arguments.get("order_numbers") or [])
                    if _compact_text(value)
                ]
            )
            if not has_explicit_target_or_query and scope_provider_id not in dependencies:
                dependencies.append(scope_provider_id)
            if "order_numbers" not in arguments and semantic_id in inserted:
                arguments["order_numbers"] = {
                    "$from_step": scope_provider_id,
                    "path": "tool_result.order_numbers",
                }
        if semantic_id in _WRITE_STEP_IDS:
            if previous_write_id and previous_write_id not in dependencies:
                dependencies.append(previous_write_id)
            previous_write_id = step_id
        spec["depends_on"] = list(dict.fromkeys(dependencies))
        spec["arguments"] = arguments

    changed = bool(inserted or dropped or semantic_rejected)
    return normalized_ids, compiled, {
        "direct_plan_compiled": True,
        "semantic_authority": semantic_authority,
        "semantic_coverage_normalized": changed,
        "semantic_step_ids": dict(semantic_by_provider_id),
        "semantic_inserted_step_ids": [],
        "semantic_missing_step_ids": inserted,
        "semantic_dropped_step_ids": list(
            dict.fromkeys(
                [
                    *dropped,
                    *[
                        semantic_id
                        for semantic_id in semantic_rejected
                        if semantic_id not in normalized_semantic_ids
                    ],
                ]
            )
        ),
        "semantic_dependency_preserved_step_ids": [
            provider_id
            for provider_id in provider_order
            if provider_id in preserved_dependency_ids
        ],
        "deterministic_business_steps_inserted": False,
    }


def _tool_result_field_names(tool: Any) -> list[str]:
    schema = (
        tool.result_schema
        if isinstance(getattr(tool, "result_schema", None), dict)
        else {}
    )
    properties = (
        schema.get("properties")
        if isinstance(schema.get("properties"), dict)
        else {}
    )
    return sorted(
        _compact_text(name)
        for name in properties
        if _compact_text(name)
    )


def _atomic_plan_argument_contract() -> str:
    """Keep operation choice and its input/output schema one model decision."""
    return (
        "OperationContract: Her operation'in argumanlari ve sonuc alanlari kendine aittir. "
        "arguments_json nesnesini sectigin exact operation'in arguments_schema/args "
        "alanindan kur; katalog semasinda olmayan arguman ekleme. "
        "operation_id degistiriyorsan eski arguman nesnesini kopyalama; yeni semaya "
        "gore yeniden kur ve expected_evidence'i yeni sonuclara gore yeniden belirle. "
        "Runtime bilinmeyen argumanlari sessizce silmez.\n"
        "expected_evidence: output_schema'daki exact machine alanlarini ayri string olarak yaz; prose, virgul listesi veya yeni alan uydurma.\n"
        "Katalog sinirlidir; gereken operation/sema gorunmuyorsa operations.discover ile ara. "
        "Semasi bilinmeyen sonraki operation'i ayni plana uydurma: yalniz kesif adimini kur, "
        "gozlem sonrasi gercek semayla replan yap. Artifact producer ciktisini exact $from_step ile bagla, literal snapshot uydurma.\n"
        "artifacts.read yalniz observation_artifact_refs'teki granted ID'yi okur. result original observation'dir; "
        "historical_snapshot/fresh_read=false tarihsel kanittir, guncel kaynak sorgusu veya islem onayi degildir.\n"
        "SourceBindingContract: analysis.calculate, analysis.table ve reports.build_snapshot sources[] icin "
        "operation_id dependency step'in gercek operation_id'sidir; artifacts.read kullandiysan origin.operation_id degil artifacts.read yaz. "
        "sources[].result her zaman {\"$from_step\":\"source_step_id\",\"path\":\"tool_result\"} ile TUM sonucu baglar; "
        "tool_result.result ile historical wrapper/receipt'i atma. Historical payload alanlari icin operand/column path'inde result. kullan.\n"
        "WebObservationBindingContract: web.research_report.web_observations[] literal/model-yazimi observation kabul etmez; "
        "web.open/web.document.read/web.follow step'inin tool_result.web_observation alanina typed binding kullan. "
        "Granted artifacts.read sonrasi path=tool_result.result.web_observation; depends_on zorunlu. "
        "web.research_report_xlsx.prepare.report_snapshot yalniz web.research_report.tool_result.report_snapshot'a baglanir.\n"
        "agent.delegate sonrasi artifact_id icin typed nesne kullan: "
        "{\"$from_step\":\"child_step\",\"path\":\"tool_result.artifact_refs[0].artifact_id\"}; "
        "depends_on:[\"child_step\"]. $from_step:... string'i veya uydurma obs_... kimligi gecersizdir. "
        "Mevcut child receipt'ini kullan; kimlik baglama hatasinda yeni alt gorev acma.\n"
    )


def _tool_source_contract(tool: Any) -> str:
    requirements = getattr(tool, "input_source_requirements", ())
    serialized = [requirement.to_dict() for requirement in requirements] if isinstance(requirements, (tuple, list)) else []
    return (
        f"; output_schema={json.dumps(tool.result_schema or {}, ensure_ascii=False, sort_keys=True)}"
        f"; input_source_requirements={json.dumps(serialized, ensure_ascii=False, sort_keys=True)}"
    )


def _orders_plan_prompt(
    goal: str,
    max_steps: int,
    *,
    operation_candidates: dict[str, Any] | None = None,
    typed_context: list[dict[str, Any]] | None = None,
    semantic_contract: dict[str, Any] | None = None,
    compact_contract: bool = False,
) -> str:
    candidates = operation_candidates or _planner_operation_candidates(
        "orders",
        goal,
    )
    typed_contract = dict(semantic_contract or {})
    read_evidence_contract = business_read_plan_constraints(typed_contract)
    metric_requirements = normalize_order_metric_requirements(
        typed_contract.get("metric_requirements") or []
    )
    required_metric_evidence = {
        metric_id: [
            {
                "operation_id": operation_id,
                "evidence_keys": list(
                    order_metric_evidence_keys(metric_id, operation_id)
                ),
            }
            for operation_id in order_metric_operation_ids(metric_id)
            if operation_id in candidates
        ]
        for metric_id in metric_requirements
    }

    catalog_lines = []
    for operation_id, tool in candidates.items():
        operation_kind = (
            "write_prepare"
            if bool(tool.requires_approval or tool.action_type != "read")
            else "read"
        )
        catalog_lines.append(
            f"- {operation_id}: {operation_kind}; "
            f"description={_compact_text(tool.description)}; "
            f"arguments_schema={json.dumps(tool.parameters or {}, ensure_ascii=False, sort_keys=True)}; "
            f"result_fields={json.dumps(_tool_result_field_names(tool), ensure_ascii=False)}"
            f"{_tool_source_contract(tool)}"
        )
    if compact_contract:
        def compact_arguments(tool: Any) -> dict[str, Any]:
            schema = tool.parameters if isinstance(tool.parameters, dict) else {}
            properties = schema.get("properties") if isinstance(schema.get("properties"), dict) else {}
            return {
                "properties": {
                    _compact_text(name): {
                        key: value
                        for key, value in dict(spec or {}).items()
                        if key in {"type", "enum"}
                    }
                    for name, spec in properties.items()
                    if _compact_text(name) and isinstance(spec, dict)
                },
                "required": list(schema.get("required") or []),
            }

        compact_catalog = [
            f"- {operation_id}; kind="
            f"{'write_prepare' if bool(tool.requires_approval or tool.action_type != 'read') else 'read'}; "
            f"description={_compact_text(tool.description)[:1000]}; "
            f"args={json.dumps(compact_arguments(tool), ensure_ascii=False, separators=(',', ':'))}; "
            f"outputs={json.dumps(_tool_result_field_names(tool), ensure_ascii=False, separators=(',', ':'))}"
            f"{_tool_source_contract(tool)}"
            for operation_id, tool in candidates.items()
        ]
        return (
            "Orders atomic GoalPlan. Yalniz katalogdaki operation_id kullan. "
            "Kullanicinin acik tum niyetlerini minimal adimlarla kapsa; ekstra read ekleme. "
            "Bir operation birden fazla gerekli output alanini zaten donduruyorsa ayni "
            "kanit icin ikinci read ekleme. "
            f"{_atomic_plan_argument_contract()}"
            "ReadEvidenceContract, verifier'in ayni typed sozlesmeden turettigi kanit siniridir. "
            "Istenen kaniti operation_alternatives icinden sec; gerekli onkosullari model planlar. "
            "exact_status_filter varsa kod kumesini belirtilen filters argumaninda aynen koru; "
            "birlesik is kuyrugu ayni kanit degildir. "
            "Typed baglam exact order_numbers veriyorsa deictic read ve write_prepare "
            "hedefinde o immutable secimi koru. "
            "SemanticContract record_selector.kind=latest ve record_scope=active_selection ise "
            "once orders.recent ile order_numbers uret; record detail gerekiyorsa "
            "orders.full_context order_numbers argumanini bu output'a bagla. Tek query/list "
            "adimi item/detail kaniti yerine gecmez. "
            "contextual_item_identity_required=true ise once orders.product_public_identities, "
            "sonra product_identities dependency bagli orders.item_sales_summary kullan. "
            "contextual_public_product_web_research_required=true ise aktif exact siparisi "
            "orders.product_public_identities ile privacy-safe urun kimligine cevir; web.search "
            "query ve public_product_fields argumanlarini bu step'in primary_public_query ve "
            "primary_public_product_fields outputlarina bagla; ardindan web.open URL'sini "
            "web.search primary_url outputuna, query_summary ve public_product_fields "
            "argumanlarini da ayni search step'inin exact outputlarina bagla. Kullanici "
            "cumlesini search query yapma, statik veya uydurma URL yazma. "
            "Write_prepare execute etmez, onay paketi hazirlar. "
            "Cevap yalniz JSON: "
            '{"steps":[{"id":"s1","operation_id":"...","arguments_json":"{}",'
            '"depends_on":[],"objective":"...","expected_evidence":[]}]}\n'
            f"Goal={_compact_text(goal)}\n"
            f"SemanticContract={json.dumps(typed_contract, ensure_ascii=False, separators=(',', ':'))}\n"
            f"ReadEvidenceContract={json.dumps(read_evidence_contract, ensure_ascii=False, separators=(',', ':'))}\n"
            f"RequiredMetricEvidence={json.dumps(required_metric_evidence, ensure_ascii=False, separators=(',', ':'))}\n"
            f"Context={json.dumps(list(typed_context or []), ensure_ascii=False, separators=(',', ':'))}\n"
            "Catalog:\n"
            + "\n".join(compact_catalog)
        )
    return (
        "Orders domain agent task plani olustur. Sadece asagidaki operation_id degerlerinden sec.\n"
        "Minimal plan sec: kullanici hedefinde acikca istenmeyen yakin alanlari, sonraki olasi isleri veya ekstra denetimleri ekleme.\n"
        "Result fields katalogda acikca verilir. Secilmis bir operation birden fazla gerekli "
        "kaniti zaten donduruyorsa ayni field veya scope icin ikinci read operation ekleme.\n"
        "Her step icin benzersiz id, exact operation_id, semaya uyan typed arguments, depends_on ve expected_evidence ver. "
        "Typed arguments'i arguments_json alaninda tek bir gecerli JSON object string'i olarak kodla.\n"
        f"{_atomic_plan_argument_contract()}"
        "Bir step onceki step'in sonucunu kullanacaksa depends_on'a kaynak step id'sini yaz ve argumani "
        "{\"$from_step\":\"kaynak_step\",\"path\":\"tool_result.alan\"} olarak bagla; required alan adi kaynak result alaniyla ayniysa runtime otomatik de baglar.\n"
        "Etiket, kargo veya iade gibi kayit-hedefli write_prepare icin hedef kimlikleri kullanici acikca vermediyse once exact "
        "order_numbers/claim_ids donduren read operation sec, prepare'i ona bagla; yalniz count sonucu mutation hedefi olamaz.\n"
        "ReadEvidenceContract, verifier'in ayni typed sozlesmeden turettigi kanit siniridir. "
        "Istenen kaniti operation_alternatives icinden sec; gerekli onkosullari model planlar. "
        "exact_status_filter varsa kod kumesini belirtilen filters argumaninda aynen koru; "
        "birlesik is kuyrugu ayni kanit degildir.\n"
        "Aktif typed baglam exact order_numbers ve kullanici deictic bir referans tasiyorsa "
        "ayni immutable secimi istenen alanlari donduren read operation'a bagla.\n"
        "SemanticContract record_selector.kind=latest ve record_scope=active_selection ise kayit kimligi "
        "henuz bilinmiyor demektir. Once orders.recent operation'ini selector limit/sort ile calistir; "
        "record detail projection'i icin sonra orders.full_context order_numbers argumanini discovery "
        "step'inin tool_result.order_numbers ciktisina typed dependency ile bagla. orders.query/recent "
        "satiri tek basina item/detail kaniti sayilmaz.\n"
        "SemanticContract contextual_item_identity_required=true ise aktif exact siparis icin once "
        "orders.product_public_identities calistir; orders.item_sales_summary product_identities argumanini "
        "bu step'in tool_result.product_identities ciktisina typed dependency ile bagla. Summary'yi "
        "order_numbers ile daraltma; hedef secili urunun tum matching siparislerdeki satisidir.\n"
        "SemanticContract contextual_public_product_web_research_required=true ise aktif exact "
        "siparis icin once orders.product_public_identities calistir. web.search query argumanini "
        "identity step'inin tool_result.primary_public_query, public_product_fields argumanini "
        "tool_result.primary_public_product_fields ciktisina typed dependency ile bagla. Sonra "
        "web.open URL'sini search step'inin tool_result.primary_url ciktisina; query_summary "
        "ve public_product_fields argumanlarini da ayni search step'inin "
        "tool_result.query_summary ve tool_result.public_product_fields ciktilarina bagla. "
        "Kullanici cumlesini search query olarak gonderme; statik, tahmini veya uydurma URL kullanma.\n"
        "Write_prepare operation'larini sadece kullanici hedefinde acik niyet varsa sec; bunlar yalniz onay paketi hazirlar, execute etmez.\n"
        "Tek niyetli hedeflerde yalnizca o niyetin zorunlu atomic operation adimlarini dondur.\n"
        f"En fazla {max(1, int(max_steps or 8))} step dondur.\n"
        "SemanticContract icindeki her metric_requirements kimligi plandaki operation'larin "
        "authoritative result kanitiyla kapsanmalidir; urun satiri gross_amount degeri toplam "
        "ciro kaniti degildir. record_scope=all_matching ise eski active selection ile order_numbers daraltmasi yapma.\n"
        "Cevap sadece JSON olsun: "
        "{\"steps\":[{\"id\":\"step_1\",\"operation_id\":\"...\","
        "\"arguments_json\":\"{}\",\"depends_on\":[],\"objective\":\"...\","
        "\"expected_evidence\":[]}],\"reason\":\"...\"}\n"
        f"Hedef: {_compact_text(goal)}\n"
        f"Typed semantic contract: {json.dumps(typed_contract, ensure_ascii=False, sort_keys=True)}\n"
        f"ReadEvidenceContract={json.dumps(read_evidence_contract, ensure_ascii=False, sort_keys=True)}\n"
        f"Zorunlu metric kanit sozlesmesi: {json.dumps(required_metric_evidence, ensure_ascii=False, sort_keys=True)}\n"
        f"Aktif typed baglam: {json.dumps(list(typed_context or []), ensure_ascii=False, sort_keys=True)}\n"
        "Atomic operation katalogu:\n"
        + "\n".join(catalog_lines)
    )


def _orders_plan_repair_prompt(
    goal: str,
    max_steps: int,
    *,
    operation_candidates: dict[str, Any],
    typed_context: list[dict[str, Any]] | None,
    semantic_contract: dict[str, Any] | None,
    rejected_plan: list[dict[str, Any]],
    reason_codes: list[str],
    compile_evidence: dict[str, Any] | None,
    compact_contract: bool,
) -> str:
    """Ask the model—not a deterministic template—to repair its business plan."""

    raw_evidence = dict(compile_evidence or {})
    read_evidence = {
        key: raw_evidence[key]
        for key in ("expected_typed_read_operations", "compiled_operation_ids", "step_validation_errors")
        if key in raw_evidence
    }
    minimality_evidence = {
        key: raw_evidence.get(key)
        for key in (
            "minimal_metric_cover_operation_ids",
            "redundant_metric_operation_ids",
            "metric_requirement_coverage_by_operation",
        )
        if raw_evidence.get(key)
    }
    minimality_contract = ""
    if minimality_evidence:
        minimality_contract = (
            "Minimality verifier evidence (rejected model plan ve canonical result "
            "schema'larindan hesaplandi; hicbir step calistirilmadi): "
            f"{json.dumps(minimality_evidence, ensure_ascii=False, sort_keys=True)}\n"
            "Repaired plan, verifier witness'ini izliyorsa "
            "minimal_metric_cover_operation_ids icindeki exact operation setini kullan; "
            "redundant_metric_operation_ids icindeki operation'lari ekleme. Baska bir "
            "katalog kombinasyonu sececeksen ayni metric ve projection kanitini daha az "
            "olmayan minimal step sayisiyla eksiksiz kapsadigini planinda goster.\n"
        )
    return (
        "Orders model plan semantic repair. Onceki plan calistirilmadi. "
        "Kullanici hedefini bastan degerlendir ve katalogdan eksiksiz, minimal, "
        "typed atomic plan kur. Deterministik katman senin yerine business step "
        "eklemeyecek veya hedefi degistirmeyecek. Cevap yalniz plan JSON'u olsun.\n"
        "Bir rejection code required_operation_missing:<operation_id> iceriyorsa "
        "repaired steps icinde o exact operation_id kullanici hedefini karsilayan "
        "typed arguments ile model tarafindan acikca yazilmalidir.\n"
        "Bir rejection code redundant_projection_read_operation:<operation_id> "
        "iceriyorsa o exact operation rejected planda baska bir read tarafindan zaten "
        "tam kapsanmistir; repaired steps'e yeniden koyma. Kalan operation seti butun "
        "metric_requirements ve gorunur projection'i tek kez, minimal olarak kapsamali.\n"
        "contextual_web_open_dependency_missing kodu varsa her web.open URL baginin "
        "geldigi ayni web.search step'ine depends_on ile baglanmasi; query_summary ve "
        "public_product_fields argumanlarinin da o step'in tool_result.query_summary "
        "ve tool_result.public_product_fields ciktilarina typed dependency ile "
        "baglanmasi zorunludur.\n"
        f"Rejection reason codes: {json.dumps(reason_codes, ensure_ascii=False)}\n"
        f"Rejected model plan: {json.dumps(rejected_plan, ensure_ascii=False, sort_keys=True)}\n"
        f"Read verifier evidence: {json.dumps(read_evidence, ensure_ascii=False, sort_keys=True)}\n"
        + minimality_contract
        + _orders_plan_prompt(
            goal,
            max_steps,
            operation_candidates=operation_candidates,
            typed_context=typed_context,
            semantic_contract=semantic_contract,
            compact_contract=compact_contract,
        )
    )


def _orders_plan_json_repair_prompt(
    goal: str,
    max_steps: int,
    *,
    operation_candidates: dict[str, Any],
    typed_context: list[dict[str, Any]] | None,
    semantic_contract: dict[str, Any] | None,
    rejected_response: str,
    error: Exception,
    compact_contract: bool,
) -> str:
    """Ask the same model once to repair malformed GoalPlan JSON only."""

    rejected = _compact_text(rejected_response)[:3_000]
    return (
        "Orders domain agent task plan JSON repair. Onceki cevap parse edilemedi, "
        "calistirilmadi ve hicbir business tool secilmedi. Ayni hedefi, ayni typed "
        "baglami ve ayni atomic operation katalogunu koru; yalniz tek gecerli plan "
        "JSON nesnesi dondur. Yeni hedef, operation veya kayit kimligi uydurma. "
        "Bu tek bounded JSON repair denemesidir.\n"
        f"Validation error: {_compact_text(error)}\n"
        f"Rejected response: {json.dumps(rejected, ensure_ascii=False)}\n"
        + _orders_plan_prompt(
            goal,
            max_steps,
            operation_candidates=operation_candidates,
            typed_context=typed_context,
            semantic_contract=semantic_contract,
            compact_contract=compact_contract,
        )
    )


def _orders_candidate_retrieval_goal(
    goal: str,
    turn_interpretation: dict[str, Any] | None,
    typed_context: list[dict[str, Any]] | None = None,
) -> tuple[str, str]:
    """Enrich retrieval only; never author or select a business operation."""

    interpretation = dict(turn_interpretation or {})
    parts = [_compact_text(goal)]
    semantic_contract = dict(interpretation.get("semantic_contract") or {})
    semantic_tokens = [
        _compact_text(semantic_contract.get(key))
        for key in (
            "entity",
            "metric",
            "status_scope",
            "record_scope",
            "period",
            "freshness",
        )
    ]
    semantic_tokens.extend(
        _compact_text(value)
        for value in list(semantic_contract.get("projection") or [])
    )
    semantic_tokens.extend(
        _compact_text(value)
        for value in list(semantic_contract.get("metric_requirements") or [])
    )
    if any(semantic_tokens):
        parts.append(" ".join(value for value in semantic_tokens if value))
    correction_target = dict(interpretation.get("correction_target") or {})
    correction_objective = _compact_text(correction_target.get("objective"))
    if correction_objective:
        parts.append(correction_objective)
    active_target_tokens: list[str] = []
    for context in list(typed_context or []):
        if not isinstance(context, dict):
            continue
        if _compact_text(context.get("kind")).casefold() != "pending_action":
            continue
        active_target_tokens.extend(
            value
            for value in (
                _compact_text(context.get("action_type")),
                _compact_text(context.get("source_tool")),
            )
            if value
        )
    if active_target_tokens:
        parts.append(" ".join(dict.fromkeys(active_target_tokens)))
    enriched = "\n".join(value for value in parts if value)
    return (
        enriched or _compact_text(goal),
        (
            "typed_semantic_and_active_target_context"
            if len([value for value in parts if value]) > 1
            else "user_goal"
        ),
    )


def _redundant_orders_projection_read_operations(
    compiled_specs: list[dict[str, Any]],
    *,
    semantic_contract: dict[str, Any],
    requested_fields: list[str],
    operation_candidates: dict[str, Any],
) -> dict[str, Any]:
    """Find extra read steps that only duplicate already-covered projections.

    This does not choose a replacement operation or rewrite the model plan. It
    rejects a model-authored plan only when every requested field is understood,
    all typed metric requirements are already covered, and a non-metric read
    contributes no projection evidence that the metric operations do not
    already return. The model then receives the reason-coded plan for bounded
    repair.
    """

    empty_analysis = {
        "redundant_operations": (),
        "minimal_metric_cover_operation_ids": (),
        "redundant_metric_operation_ids": (),
        "metric_requirement_coverage_by_operation": {},
    }
    metric_requirements = normalize_order_metric_requirements(
        semantic_contract.get("metric_requirements") or []
    )
    direct_projection = semantic_contract.get("direct_projection")
    projection_source = (
        list(direct_projection)
        if isinstance(direct_projection, list) and direct_projection
        else list(requested_fields or [])
    )
    normalized_fields = {
        _compact_text(value).casefold()
        for value in projection_source
        if _compact_text(value)
        and _compact_text(value).casefold() != "calculation"
    }
    understood_fields = {"count", "status", "store", "scope"}
    if (
        not metric_requirements
        or not normalized_fields
        or not normalized_fields.issubset(understood_fields)
    ):
        return empty_analysis

    required_projection_keys = set(
        order_projection_evidence_keys(normalized_fields)
    )
    operation_by_step: dict[str, str] = {}
    dependency_sources: set[str] = set()
    for spec in compiled_specs:
        if not isinstance(spec, dict):
            continue
        step_id = _compact_text(spec.get("id"))
        operation_id = _compact_text(spec.get("operation_id"))
        if step_id and operation_id:
            operation_by_step[step_id] = operation_id
        dependency_sources.update(
            _compact_text(value)
            for value in list(spec.get("depends_on") or [])
            if _compact_text(value)
        )

    metric_specs: list[dict[str, Any]] = []
    for position, spec in enumerate(compiled_specs):
        if not isinstance(spec, dict):
            continue
        step_id = _compact_text(spec.get("id"))
        operation_id = _compact_text(spec.get("operation_id"))
        tool = operation_candidates.get(operation_id)
        coverage = {
            metric_id
            for metric_id in metric_requirements
            if order_metric_evidence_keys(metric_id, operation_id)
        }
        if (
            not step_id
            or not operation_id
            or not coverage
            or step_id in dependency_sources
            or list(spec.get("depends_on") or [])
            or tool is None
            or bool(tool.requires_approval)
            or _compact_text(tool.action_type).casefold() != "read"
        ):
            continue
        metric_specs.append(
            {
                "position": position,
                "operation_id": operation_id,
                "coverage": coverage,
                "projection_keys": set(_tool_result_field_names(tool)),
                "result_surface_size": len(_tool_result_field_names(tool)),
                "scope_signature": json.dumps(
                    dict(spec.get("arguments") or {}),
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                    default=str,
                ),
            }
        )

    metric_operation_ids = {
        str(row.get("operation_id") or "") for row in metric_specs
    }
    minimal_metric_cover_operation_ids: tuple[str, ...] = ()
    redundant_metric_operations: list[str] = []
    unique_metric_specs = []
    seen_metric_operations: set[str] = set()
    for row in metric_specs:
        operation_id = str(row.get("operation_id") or "")
        if operation_id and operation_id not in seen_metric_operations:
            seen_metric_operations.add(operation_id)
            unique_metric_specs.append(row)
    if (
        len(unique_metric_specs) >= 2
        and len(
            {
                str(row.get("scope_signature") or "")
                for row in unique_metric_specs
            }
        )
        == 1
    ):
        best_subset: tuple[dict[str, Any], ...] | None = None
        best_score: tuple[Any, ...] | None = None
        required_metrics = set(metric_requirements)
        for subset_size in range(1, len(unique_metric_specs) + 1):
            for subset in combinations(unique_metric_specs, subset_size):
                covered_metrics = set().union(
                    *(set(row.get("coverage") or set()) for row in subset)
                )
                covered_projection = set().union(
                    *(
                        set(row.get("projection_keys") or set())
                        for row in subset
                    )
                )
                if not required_metrics.issubset(covered_metrics):
                    continue
                if not required_projection_keys.issubset(covered_projection):
                    continue
                score = (
                    subset_size,
                    sum(int(row.get("result_surface_size") or 0) for row in subset),
                    tuple(int(row.get("position") or 0) for row in subset),
                )
                if best_score is None or score < best_score:
                    best_score = score
                    best_subset = subset
            if best_subset is not None:
                break
        if best_subset is not None and len(best_subset) < len(unique_metric_specs):
            minimal_metric_cover_operation_ids = tuple(
                str(row.get("operation_id") or "") for row in best_subset
            )
            minimal_operation_ids = set(minimal_metric_cover_operation_ids)
            redundant_metric_operations = [
                str(row.get("operation_id") or "")
                for row in unique_metric_specs
                if str(row.get("operation_id") or "")
                not in minimal_operation_ids
            ]
            metric_operation_ids = minimal_operation_ids
    metric_projection_fields = {
        field
        for operation_id in metric_operation_ids
        for field in _tool_result_field_names(
            operation_candidates.get(operation_id)
        )
    }
    if not required_projection_keys.issubset(metric_projection_fields):
        return empty_analysis

    redundant: list[str] = list(redundant_metric_operations)
    for spec in compiled_specs:
        if not isinstance(spec, dict):
            continue
        step_id = _compact_text(spec.get("id"))
        operation_id = _compact_text(spec.get("operation_id"))
        tool = operation_candidates.get(operation_id)
        if (
            not step_id
            or not operation_id
            or operation_id in metric_operation_ids
            or step_id in dependency_sources
            or list(spec.get("depends_on") or [])
            or tool is None
            or bool(tool.requires_approval)
            or _compact_text(tool.action_type).casefold() != "read"
        ):
            continue
        contributed_projection = required_projection_keys.intersection(
            _tool_result_field_names(tool)
        )
        if (
            contributed_projection
            and contributed_projection.issubset(metric_projection_fields)
            and operation_id not in redundant
        ):
            redundant.append(operation_id)
    return {
        "redundant_operations": tuple(redundant),
        "minimal_metric_cover_operation_ids": minimal_metric_cover_operation_ids,
        "redundant_metric_operation_ids": tuple(redundant_metric_operations),
        "metric_requirement_coverage_by_operation": {
            str(row.get("operation_id") or ""): sorted(
                str(value) for value in set(row.get("coverage") or set())
            )
            for row in unique_metric_specs
            if str(row.get("operation_id") or "")
        },
    }


_PLAN_EVIDENCE_PROJECTION_ALIASES = {
    "address": "address",
    "cargo": "cargo",
    "cargo_provider": "cargo",
    "claim_id": "claim_id",
    "claim_ids": "claim_id",
    "customer": "customer_name",
    "customer_name": "customer_name",
    "date": "date",
    "email": "email",
    "item": "item",
    "items": "item",
    "item_count": "item_count",
    "line_item_count": "item_count",
    "product": "item",
    "product_name": "item",
    "sku": "sku",
    "stock_code": "sku",
    "barcode": "barcode",
    "gtin": "barcode",
    "order_date": "date",
    "order_number": "order_number",
    "order_numbers": "order_number",
    "package_id": "package_id",
    "phone": "phone",
    "status": "status",
    "total_price": "amount",
    "tracking": "tracking_number",
    "tracking_number": "tracking_number",
}

_PLAN_PROJECTION_COHERENCE_FIELDS = frozenset(
    {
        "address",
        "amount",
        "cargo",
        "claim_id",
        "customer_name",
        "date",
        "email",
        "item",
        "item_count",
        "sku",
        "barcode",
        "order_number",
        "package_id",
        "phone",
        "status",
        "tracking_number",
    }
)

# These fields can be legitimate internal tool evidence while remaining
# forbidden in the visible answer. A disagreement about them therefore needs
# an explicit model decision. Order identifiers use the separate typed
# identifier_display contract because every record plan needs them internally.
_PRIVACY_GATED_PROJECTION_FIELDS = frozenset(
    {
        "address",
        "claim_id",
        "customer_name",
        "email",
        "package_id",
        "phone",
        "tracking_number",
    }
)


def _projection_contract_repair_response_schema(
    mismatches: list[str],
) -> dict[str, Any]:
    """Build a minimal, closed schema with one required decision per field.

    A keyed object is materially easier for text-guarded models than asking
    them to echo canonical field names inside an array.  It also lets schema
    validation prove that every privacy-gated disagreement was classified.
    """

    fields = list(dict.fromkeys(mismatches))
    return {
        "type": "object",
        "properties": {
            "decisions": {
                "type": "object",
                "properties": {
                    field_name: {
                        "type": "string",
                        "enum": ["visible_requested", "internal_only"],
                    }
                    for field_name in fields
                },
                "required": fields,
                "additionalProperties": False,
            },
            "reason": {"type": "string"},
        },
        "required": ["decisions", "reason"],
        "additionalProperties": False,
    }


def _model_plan_expected_projection_fields(
    plan_meta: dict[str, Any] | None,
) -> set[str]:
    """Map model-authored evidence names to visible projection field roles.

    ``expected_evidence`` is not automatically projection authority: a plan may
    need private data internally without permission to show it.  The mapped set
    only detects a contradiction that must be resolved by a bounded model
    decision before execution.
    """

    fields: set[str] = set()
    for spec in list((plan_meta or {}).get("step_specs") or []):
        if not isinstance(spec, dict):
            continue
        for value in list(spec.get("expected_evidence") or []):
            key = _normalized(value).replace(" ", "_")
            field_name = _PLAN_EVIDENCE_PROJECTION_ALIASES.get(key, "")
            if field_name in _PLAN_PROJECTION_COHERENCE_FIELDS:
                fields.add(field_name)
    return fields


def _projection_contract_repair_prompt(
    goal: str,
    *,
    interpretation: dict[str, Any],
    plan_meta: dict[str, Any],
    fields: list[str],
) -> str:
    safe_steps = [
        {
            "operation_id": _compact_text(spec.get("operation_id")),
            "objective": _compact_text(spec.get("objective")),
            "expected_evidence": [
                _compact_text(value)
                for value in list(spec.get("expected_evidence") or [])
                if _compact_text(value)
            ],
        }
        for spec in list(plan_meta.get("step_specs") or [])
        if isinstance(spec, dict)
    ]
    current_fields = [
        _canonical_requested_field(value)
        for value in list(interpretation.get("requested_fields") or [])
        if _canonical_requested_field(value)
    ]
    return "\n".join(
        [
            "OrderScout projection contract reconciler.",
            "Kullanicinin orijinal hedefi ile ayni modelin typed turn contract'i ve atomic plani arasindaki alan uyusmazligini coz.",
            "Her privacy-gated alan icin tam bir karar ver: kullanici final cevapta bu alani acikca istediyse visible_requested; alan yalniz tool'un ic calismasi/filtre/kimlik baglaminda gerekliyse internal_only.",
            "Plan expected_evidence tek basina gorunur alan yetkisi degildir. Ozellikle siparis numarasi, musteri, adres, telefon, e-posta, takip, paket ve diger kimlik alanlarini kullanici istemediyse internal_only yap. Kullanici siparis numarasini gostermeme, gizleme veya sira numarasi kullanma talimati verdiyse order_number mutlaka internal_only olmali.",
            "Yeni business hedef, tool, kayit kimligi veya alan uydurma. Yalniz verilen privacy-gated alanlar icin birer karar dondur.",
            "decisions bir JSON object olmali; anahtarlari asagidaki alanlarla birebir ayni olmali ve her anahtar mutlaka bulunmali.",
            "Cevap sadece schema'ya uyan JSON olsun.",
            f"Orijinal kullanici hedefi: {_compact_text(goal)}",
            "Mevcut typed requested_fields: "
            + json.dumps(current_fields, ensure_ascii=False),
            "Typed semantic contract: "
            + json.dumps(
                dict(interpretation.get("semantic_contract") or {}),
                ensure_ascii=False,
                sort_keys=True,
            ),
            "Model-authored atomic plan: "
            + json.dumps(safe_steps, ensure_ascii=False, sort_keys=True),
            "Karar verilmesi zorunlu privacy-gated alanlar: "
            + json.dumps(fields, ensure_ascii=False),
        ]
    )


def _reconcile_orders_projection_contract(
    goal: str,
    *,
    interpretation: dict[str, Any],
    plan_meta: dict[str, Any],
    planner_client: ChatClient | None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Validate model-authored privacy projection before tool execution.

    The deterministic layer only identifies privacy-gated typed fields from
    the model-authored interpretation and plan.  It never promotes a field
    from user prose.  A bounded model reconciliation must classify every field
    as visible or internal; otherwise the read plan fails closed.
    """

    repaired_interpretation = deepcopy(dict(interpretation or {}))
    repaired_meta = deepcopy(dict(plan_meta or {}))
    source = _compact_text(repaired_meta.get("source"))
    if (
        planner_client is None
        or source not in {"llm_direct", "llm_direct_repaired"}
        or repaired_meta.get("planner_invoked") is not True
    ):
        return repaired_interpretation, repaired_meta

    current_fields = {
        _canonical_requested_field(value)
        for value in list(repaired_interpretation.get("requested_fields") or [])
        if _canonical_requested_field(value)
    }
    expected_fields = _model_plan_expected_projection_fields(repaired_meta)
    expected_privacy_fields = expected_fields.intersection(
        _PRIVACY_GATED_PROJECTION_FIELDS
    )
    current_privacy_fields = current_fields.intersection(
        _PRIVACY_GATED_PROJECTION_FIELDS
    )
    explicitly_visible_privacy_fields = (
        set(_explicit_repeat_projection_fields(goal))
        .difference(_explicitly_prohibited_projection_fields(goal))
        .intersection(_PRIVACY_GATED_PROJECTION_FIELDS)
    )
    locked_visible_fields = current_privacy_fields.intersection(
        explicitly_visible_privacy_fields
    )
    review_fields = sorted(
        expected_privacy_fields.union(current_privacy_fields).difference(
            locked_visible_fields
        )
    )
    if not review_fields:
        repaired_meta["projection_contract_coherent"] = True
        repaired_meta["projection_contract_repair_invoked"] = False
        repaired_meta["projection_contract_review_fields"] = []
        repaired_meta["projection_contract_locked_visible_fields"] = sorted(
            locked_visible_fields
        )
        return repaired_interpretation, repaired_meta

    repaired_meta.update(
        {
            "projection_contract_coherent": False,
            "projection_contract_repair_invoked": True,
            "projection_contract_review_fields": list(review_fields),
            "projection_contract_mismatches": list(review_fields),
            "projection_contract_locked_visible_fields": sorted(
                locked_visible_fields
            ),
            "projection_contract_original_requested_fields": sorted(
                current_fields
            ),
        }
    )
    try:
        payload = _extract_json_payload(
            invoke_provider_planner(
                planner_client,
                _projection_contract_repair_prompt(
                    goal,
                    interpretation=repaired_interpretation,
                    plan_meta=repaired_meta,
                    fields=review_fields,
                ),
                response_schema=_projection_contract_repair_response_schema(
                    review_fields
                ),
                prefer_guarded_json=True,
            )
        )
        decisions: dict[str, dict[str, str]] = {}
        raw_decisions = payload.get("decisions")
        for raw_field, raw_disposition in (
            dict(raw_decisions).items()
            if isinstance(raw_decisions, dict)
            else []
        ):
            field_name = _canonical_requested_field(raw_field)
            disposition = _compact_text(raw_disposition).casefold()
            if (
                field_name not in review_fields
                or disposition not in {"visible_requested", "internal_only"}
                or field_name in decisions
            ):
                continue
            decisions[field_name] = {
                "field": field_name,
                "disposition": disposition,
                "reason": _compact_text(payload.get("reason")),
            }
        unresolved = [
            field_name for field_name in review_fields if field_name not in decisions
        ]
        repaired_meta["projection_contract_decisions"] = [
            decisions[field_name]
            for field_name in review_fields
            if field_name in decisions
        ]
        repaired_meta["projection_contract_unresolved_fields"] = list(unresolved)
        if unresolved:
            repaired_meta.update(
                {
                    "projection_contract_repair_failed": True,
                    "requires_clarification": True,
                    "clarification": (
                        "Model, kullaniciya gosterilecek alanlarla atomic planin "
                        "ic kanit alanlari arasindaki farki guvenli bicimde "
                        "cozemedi. Hicbir API, DB, dosya veya yazici islemi yapilmadi."
                    ),
                }
            )
            return repaired_interpretation, repaired_meta

        additions = [
            field_name
            for field_name in review_fields
            if (
                decisions[field_name]["disposition"] == "visible_requested"
                and field_name not in current_fields
            )
        ]
        removals = [
            field_name
            for field_name in review_fields
            if (
                decisions[field_name]["disposition"] == "internal_only"
                and field_name in current_fields
            )
        ]
        requested_fields = list(
            dict.fromkeys(
                [
                    _canonical_requested_field(value)
                    for value in list(
                        repaired_interpretation.get("requested_fields") or []
                    )
                    if (
                        _canonical_requested_field(value)
                        and _canonical_requested_field(value) not in removals
                    )
                ]
                + additions
            )
        )
        repaired_interpretation["requested_fields"] = requested_fields
        semantic_contract = dict(
            repaired_interpretation.get("semantic_contract") or {}
        )
        semantic_contract["projection"] = list(requested_fields)
        repaired_interpretation["semantic_contract"] = semantic_contract
        repaired_interpretation["semantic_corrections"] = list(
            dict.fromkeys(
                [
                    *list(
                        repaired_interpretation.get("semantic_corrections")
                        or []
                    ),
                    *[
                        f"model_reconciled_{field_name}_projection_added"
                        for field_name in additions
                    ],
                    *[
                        f"model_reconciled_{field_name}_projection_removed"
                        for field_name in removals
                    ],
                ]
            )
        )
        authorization = dict(
            repaired_meta.get("model_plan_authorization") or {}
        )
        authorization["requested_fields"] = list(requested_fields)
        authorization["semantic_contract"] = dict(semantic_contract)
        authorization["projection_contract_reconciled"] = True
        repaired_meta["model_plan_authorization"] = authorization
        repaired_meta["projection_contract_fields_added"] = list(additions)
        repaired_meta["projection_contract_fields_removed"] = list(removals)
        repaired_meta["projection_contract_coherent"] = True
        return repaired_interpretation, repaired_meta
    except Exception:
        provider_failure = _planner_provider_unavailable_details(planner_client)
        if provider_failure:
            repaired_meta.update(
                {
                    "source": "model_plan_provider_unavailable",
                    "provider_unavailable": True,
                    "provider_failure": dict(provider_failure),
                    "provider_notice": _provider_unavailable_answer(
                        provider_failure
                    ),
                    "projection_contract_repair_failed": True,
                }
            )
            return repaired_interpretation, repaired_meta
        repaired_meta.update(
            {
                "projection_contract_repair_failed": True,
                "requires_clarification": True,
                "clarification": (
                    "Model, kullaniciya gosterilecek alanlarla atomic planin "
                    "ic kanit alanlari arasindaki farki guvenli bicimde "
                    "cozemedi. Hicbir API, DB, dosya veya yazici islemi yapilmadi."
                ),
            }
        )
        return repaired_interpretation, repaired_meta


def _orders_task_plan(
    goal: str,
    *,
    planner_client: ChatClient | None,
    max_steps: int,
    typed_context: list[dict[str, Any]] | None = None,
    turn_interpretation: dict[str, Any] | None = None,
) -> tuple[list[str], dict[str, Any]]:
    limit = max(1, int(max_steps or 8))
    fallback = _orders_template_step_ids(goal)[:limit]
    interpretation = dict(turn_interpretation or {})
    read_domains = _explicit_business_read_domains("orders", goal, interpretation)
    authorization_context = {
        "source_policy": source_policy(interpretation),
        "mode": _compact_text(interpretation.get("mode")).casefold(),
        "intent_kind": _compact_text(interpretation.get("intent_kind")).casefold(),
        "requested_fields": [
            _compact_text(value).casefold()
            for value in list(interpretation.get("requested_fields") or [])
            if _compact_text(value)
        ],
        "semantic_contract": dict(
            interpretation.get("semantic_contract") or {}
        ),
        "correction_target_present": bool(
            isinstance(interpretation.get("correction_target"), dict)
            and dict(interpretation.get("correction_target") or {})
        ),
        "trusted_contextual_order_selection": any(
            isinstance(row, dict)
            and _compact_text(row.get("kind")) == "order_selection"
            and bool(
                list(row.get("order_numbers") or [])
                or list(row.get("record_refs") or [])
            )
            for row in list(typed_context or [])
        ),
        "source": (
            _compact_text(interpretation.get("decision_path"))
            or "typed_turn_interpretation"
        ),
    }
    retrieval_goal, retrieval_goal_source = _orders_candidate_retrieval_goal(
        goal,
        interpretation,
        typed_context,
    )
    meta: dict[str, Any] = {
        "source": "template",
        "step_ids": list(fallback),
        "rejected_step_ids": [],
        "fallback_step_ids": list(fallback),
        "model_plan_authorization": dict(authorization_context),
        "candidate_retrieval_goal_source": retrieval_goal_source,
    }
    if planner_client is None:
        return fallback, meta
    meta["planner_invoked"] = True
    try:
        planner_resource = getattr(planner_client, "resource_plan", {})
        tight_local_context = bool(
            isinstance(planner_resource, dict)
            and (
                _compact_text(planner_resource.get("provider_code")).casefold()
                == "local"
                or _compact_text(getattr(planner_client, "runtime_name", "")).casefold().startswith("llama_cpp")
            )
            and int(planner_resource.get("num_ctx") or 0) <= 2_048
        )
        operation_candidates = _planner_operation_candidates(
            "orders",
            retrieval_goal,
            limit=(4 if tight_local_context else max(12, limit * 3)),
            read_domains=read_domains,
        )
        required_metric_candidate_ids = [
            operation_id
            for metric_id in normalize_order_metric_requirements(
                (
                    authorization_context.get("semantic_contract") or {}
                ).get("metric_requirements")
                or []
            )
            for operation_id in order_metric_operation_ids(metric_id)
        ]
        required_read_candidate_ids = business_read_plan_constraints(
            authorization_context.get("semantic_contract"),
            requested_fields=authorization_context.get("requested_fields") or [],
        ).get("operation_alternatives", [])
        if required_metric_candidate_ids or required_read_candidate_ids:
            from AI.processors.tools import available_tools

            registry = available_tools()
            for operation_id in dict.fromkeys([*required_metric_candidate_ids, *required_read_candidate_ids]):
                tool = registry.get(operation_id)
                if (
                    tool is not None
                    and _compact_text(tool.domain).casefold() == "orders"
                    and operation_id not in operation_candidates
                ):
                    operation_candidates[operation_id] = tool
            meta["required_metric_candidate_ids"] = list(
                dict.fromkeys(required_metric_candidate_ids)
            )
            meta["required_read_candidate_ids"] = list(required_read_candidate_ids)
        raw_plan_response = invoke_provider_planner(
            planner_client,
            _orders_plan_prompt(
                goal,
                limit,
                operation_candidates=operation_candidates,
                typed_context=typed_context,
                semantic_contract=dict(
                    authorization_context.get("semantic_contract") or {}
                ),
                compact_contract=tight_local_context,
            ),
            response_schema=_TASK_PLAN_RESPONSE_SCHEMA,
        )
        initial_payload_shape: Any = "unparsed"
        try:
            payload = _extract_json_payload(raw_plan_response)
            initial_payload_shape = _json_contract_shape(payload)
        except Exception as initial_json_error:
            record_provider_structured_contract_validation_failure(
                planner_client,
                _compact_text(initial_json_error),
            )
            if not _compact_text(raw_plan_response):
                raise
            meta["planner_json_repair"] = {
                "invoked": True,
                "attempt_count": 1,
                "initial_error": _compact_text(initial_json_error),
                "initial_response_sha256": hashlib.sha256(
                    str(raw_plan_response).encode("utf-8")
                ).hexdigest(),
                "initial_response_length": len(str(raw_plan_response)),
                "applied": False,
            }
            repaired_plan_response = invoke_provider_planner(
                planner_client,
                _orders_plan_json_repair_prompt(
                    goal,
                    limit,
                    operation_candidates=operation_candidates,
                    typed_context=typed_context,
                    semantic_contract=dict(
                        authorization_context.get("semantic_contract") or {}
                    ),
                    rejected_response=raw_plan_response,
                    error=initial_json_error,
                    compact_contract=tight_local_context,
                ),
                response_schema=_TASK_PLAN_RESPONSE_SCHEMA,
                prefer_guarded_json=True,
            )
            payload = _extract_json_payload(repaired_plan_response)
            meta["planner_json_repair"]["applied"] = True
        raw_specs = _planner_step_specs(payload)
        meta["planner_response_observability"] = {
            "initial_response_sha256": hashlib.sha256(
                str(raw_plan_response).encode("utf-8")
            ).hexdigest(),
            "initial_response_length": len(str(raw_plan_response)),
            "initial_payload_shape": initial_payload_shape,
            "normalized_step_count": len(raw_specs),
            "normalized_operation_ids": [
                _compact_text(spec.get("operation_id"))
                for spec in raw_specs
                if _compact_text(spec.get("operation_id"))
            ],
        }

        def validate_model_specs(
            candidate_specs: list[dict[str, Any]],
        ) -> tuple[list[str], list[dict[str, Any]], list[str], dict[str, Any]]:
            step_diagnostics: list[dict[str, Any]] = []
            accepted_specs, rejected = _validate_direct_plan_specs(
                "orders",
                candidate_specs,
                goal,
                allowed_operations=operation_candidates,
                max_steps=limit,
                authorization_context=authorization_context,
                validation_diagnostics=step_diagnostics,
                read_domains=read_domains,
            )
            if not accepted_specs:
                return [], [], [
                    *list(rejected),
                    "no_valid_atomic_operation",
                ], {"step_validation_errors": step_diagnostics}
            if all(
                spec.get("operation_id") == "operations.discover"
                for spec in accepted_specs
            ):
                return (
                    [spec["id"] for spec in accepted_specs],
                    accepted_specs,
                    list(rejected),
                    {
                        "direct_plan_compiled": True,
                        "discovery_only_plan": True,
                        "compiled_operation_ids": ["operations.discover"],
                        "deterministic_business_steps_inserted": False,
                        "step_validation_errors": step_diagnostics,
                    },
                )
            accepted_ids, compiled_specs, compile_meta = (
                _compile_orders_direct_plan_specs(
                    accepted_specs,
                    goal,
                    allowed_operations=operation_candidates,
                    max_steps=limit,
                    typed_context=typed_context,
                    semantic_contract=dict(
                        authorization_context.get("semantic_contract") or {}
                    ),
                )
            )
            compile_meta["policy_rejected_step_ids"] = list(rejected)
            compile_meta["step_validation_errors"] = step_diagnostics
            reason_codes: list[str] = []
            missing_metric_requirements = missing_order_metric_requirements(
                (
                    authorization_context.get("semantic_contract") or {}
                ).get("metric_requirements")
                or [],
                [
                    spec.get("operation_id")
                    for spec in compiled_specs
                    if isinstance(spec, dict)
                ],
            )
            compile_meta["missing_metric_requirements"] = list(
                missing_metric_requirements
            )
            reason_codes.extend(
                f"typed_read_metric_requirement_missing:{metric_id}"
                for metric_id in missing_metric_requirements
            )
            compiled_operation_ids = {
                _compact_text(spec.get("operation_id"))
                for spec in compiled_specs
                if isinstance(spec, dict)
                and _compact_text(spec.get("operation_id"))
            }
            reason_codes.extend(
                _missing_business_read_domains(compiled_specs, read_domains)
            )
            typed_contract = dict(
                authorization_context.get("semantic_contract") or {}
            )
            if typed_contract.get("contextual_item_identity_required") is True:
                specs_by_id = {
                    _compact_text(spec.get("id")): dict(spec)
                    for spec in compiled_specs
                    if isinstance(spec, dict) and _compact_text(spec.get("id"))
                }
                identity_step_ids = {
                    step_id
                    for step_id, spec in specs_by_id.items()
                    if _compact_text(spec.get("operation_id"))
                    == "orders.product_public_identities"
                }
                summary_specs = [
                    spec
                    for spec in compiled_specs
                    if isinstance(spec, dict)
                    and _compact_text(spec.get("operation_id"))
                    == "orders.item_sales_summary"
                ]
                bound_summary_found = False
                for spec in summary_specs:
                    arguments = dict(spec.get("arguments") or {})
                    binding = arguments.get("product_identities")
                    if not isinstance(binding, dict):
                        continue
                    source_step = _compact_text(binding.get("$from_step"))
                    binding_path = _compact_text(binding.get("path"))
                    dependencies = {
                        _compact_text(value)
                        for value in list(spec.get("depends_on") or [])
                        if _compact_text(value)
                    }
                    if (
                        source_step in identity_step_ids
                        and source_step in dependencies
                        and binding_path
                        == "tool_result.product_identities"
                        and not list(arguments.get("order_numbers") or [])
                    ):
                        bound_summary_found = True
                        break
                compile_meta["contextual_item_identity_step_ids"] = sorted(
                    identity_step_ids
                )
                compile_meta["contextual_item_sales_bound"] = (
                    bound_summary_found
                )
                if not identity_step_ids:
                    reason_codes.append(
                        "contextual_item_identity_operation_missing"
                    )
                if not bound_summary_found:
                    reason_codes.append(
                        "contextual_item_sales_dependency_missing"
                    )
            if (
                typed_contract.get(
                    "contextual_public_product_web_research_required"
                )
                is True
            ):
                specs_by_id = {
                    _compact_text(spec.get("id")): dict(spec)
                    for spec in compiled_specs
                    if isinstance(spec, dict) and _compact_text(spec.get("id"))
                }
                identity_step_ids = {
                    step_id
                    for step_id, spec in specs_by_id.items()
                    if _compact_text(spec.get("operation_id"))
                    == "orders.product_public_identities"
                }
                bound_search_step_ids: set[str] = set()
                for step_id, spec in specs_by_id.items():
                    if _compact_text(spec.get("operation_id")) != "web.search":
                        continue
                    arguments = dict(spec.get("arguments") or {})
                    query_binding = arguments.get("query")
                    fields_binding = arguments.get("public_product_fields")
                    if not isinstance(query_binding, dict) or not isinstance(
                        fields_binding,
                        dict,
                    ):
                        continue
                    query_source = _compact_text(
                        query_binding.get("$from_step")
                    )
                    fields_source = _compact_text(
                        fields_binding.get("$from_step")
                    )
                    dependencies = {
                        _compact_text(value)
                        for value in list(spec.get("depends_on") or [])
                        if _compact_text(value)
                    }
                    if (
                        query_source in identity_step_ids
                        and fields_source == query_source
                        and query_source in dependencies
                        and _compact_text(query_binding.get("path"))
                        == "tool_result.primary_public_query"
                        and _compact_text(fields_binding.get("path"))
                        == "tool_result.primary_public_product_fields"
                    ):
                        bound_search_step_ids.add(step_id)
                bound_open_found = False
                open_binding_evidence: list[dict[str, Any]] = []
                for spec in specs_by_id.values():
                    if _compact_text(spec.get("operation_id")) != "web.open":
                        continue
                    arguments = dict(spec.get("arguments") or {})
                    url_binding = arguments.get("url")
                    if not isinstance(url_binding, dict):
                        continue
                    source_step = _compact_text(
                        url_binding.get("$from_step")
                    )
                    query_summary_binding = arguments.get("query_summary")
                    fields_binding = arguments.get("public_product_fields")
                    query_summary_source = _compact_text(
                        query_summary_binding.get("$from_step")
                    ) if isinstance(query_summary_binding, dict) else ""
                    fields_source = _compact_text(
                        fields_binding.get("$from_step")
                    ) if isinstance(fields_binding, dict) else ""
                    dependencies = {
                        _compact_text(value)
                        for value in list(spec.get("depends_on") or [])
                        if _compact_text(value)
                    }
                    url_path = _compact_text(url_binding.get("path"))
                    provenance_bound = bool(
                        isinstance(query_summary_binding, dict)
                        and isinstance(fields_binding, dict)
                        and query_summary_source == source_step
                        and fields_source == source_step
                        and _compact_text(query_summary_binding.get("path"))
                        == "tool_result.query_summary"
                        and _compact_text(fields_binding.get("path"))
                        == "tool_result.public_product_fields"
                    )
                    binding_valid = bool(
                        source_step in bound_search_step_ids
                        and source_step in dependencies
                        and url_path in {
                            "tool_result.primary_url",
                            "tool_result.secondary_url",
                        }
                        and provenance_bound
                    )
                    open_binding_evidence.append(
                        {
                            "step_id": _compact_text(spec.get("id")),
                            "source_step_id": source_step,
                            "url_path": url_path,
                            "query_summary_path": _compact_text(
                                query_summary_binding.get("path")
                            ) if isinstance(query_summary_binding, dict) else "",
                            "public_product_fields_path": _compact_text(
                                fields_binding.get("path")
                            ) if isinstance(fields_binding, dict) else "",
                            "provenance_bound": provenance_bound,
                            "valid": binding_valid,
                        }
                    )
                    if binding_valid:
                        bound_open_found = True
                compile_meta["contextual_web_identity_step_ids"] = sorted(
                    identity_step_ids
                )
                compile_meta["contextual_web_bound_search_step_ids"] = sorted(
                    bound_search_step_ids
                )
                compile_meta["contextual_web_open_bound"] = bound_open_found
                compile_meta["contextual_web_open_binding_evidence"] = (
                    open_binding_evidence
                )
                unexpected_order_operations = sorted(
                    operation_id
                    for operation_id in compiled_operation_ids
                    if operation_id.startswith("orders.")
                    and operation_id
                    != "orders.product_public_identities"
                )
                compile_meta["contextual_web_unexpected_order_operations"] = (
                    unexpected_order_operations
                )
                if not identity_step_ids:
                    reason_codes.append(
                        "contextual_web_identity_operation_missing"
                    )
                if not bound_search_step_ids:
                    reason_codes.append(
                        "contextual_web_search_dependency_missing"
                    )
                if not bound_open_found:
                    reason_codes.append(
                        "contextual_web_open_dependency_missing"
                    )
                reason_codes.extend(
                    "contextual_web_unrequested_order_operation:"
                    f"{operation_id}"
                    for operation_id in unexpected_order_operations
                )
            expected_read_operations = expected_order_read_operations(
                typed_contract,
                requested_fields=list(
                    authorization_context.get("requested_fields") or []
                ),
            )
            compile_meta["expected_typed_read_operations"] = sorted(
                expected_read_operations
            )
            compile_meta["compiled_operation_ids"] = sorted(
                compiled_operation_ids
            )
            for spec in compiled_specs:
                reason_codes.extend(
                    validate_business_read_arguments(
                        typed_contract,
                        _compact_text(spec.get("operation_id")),
                        dict(spec.get("arguments") or {}),
                    )
                )
                if (
                    _compact_text(spec.get("operation_id"))
                    == "orders.fetch.prepare"
                ):
                    reason_codes.extend(
                        validate_orders_fetch_arguments(
                            typed_contract,
                            dict(spec.get("arguments") or {}),
                        )
                    )
            normalized_metric_requirements = normalize_order_metric_requirements(
                (
                    authorization_context.get("semantic_contract") or {}
                ).get("metric_requirements")
                or []
            )
            typed_record_shape = bool(
                _compact_text(typed_contract.get("metric")).casefold()
                in {"list", "detail"}
                or _compact_text(typed_contract.get("request_shape")).casefold()
                in {"record_list", "record_detail"}
                or _compact_text(typed_contract.get("record_scope")).casefold()
                in {"exact_ids", "active_selection"}
            )
            if (
                (not normalized_metric_requirements or typed_record_shape)
                and
                expected_read_operations
                and compiled_operation_ids
                and not compiled_operation_ids.intersection(
                    expected_read_operations
                )
            ):
                # Projection/record shape remains authoritative even when the
                # same contract also carries scalar metric requirements.  A
                # count operation may satisfy ``ready_to_ship_count`` but it
                # cannot impersonate an exhaustive list request whose typed
                # operation boundary is query/ready_to_ship.
                reason_codes.append(
                    "typed_read_contract_operation_mismatch:"
                    + ",".join(sorted(compiled_operation_ids))
                )
            redundancy_analysis = (
                _redundant_orders_projection_read_operations(
                    compiled_specs,
                    semantic_contract=dict(
                        authorization_context.get("semantic_contract") or {}
                    ),
                    requested_fields=list(
                        authorization_context.get("requested_fields") or []
                    ),
                    operation_candidates=operation_candidates,
                )
            )
            redundant_projection_reads = tuple(
                redundancy_analysis.get("redundant_operations") or ()
            )
            compile_meta["redundant_projection_read_operations"] = list(
                redundant_projection_reads
            )
            compile_meta["minimal_metric_cover_operation_ids"] = list(
                redundancy_analysis.get("minimal_metric_cover_operation_ids") or []
            )
            compile_meta["redundant_metric_operation_ids"] = list(
                redundancy_analysis.get("redundant_metric_operation_ids") or []
            )
            compile_meta["metric_requirement_coverage_by_operation"] = dict(
                redundancy_analysis.get(
                    "metric_requirement_coverage_by_operation"
                )
                or {}
            )
            reason_codes.extend(
                f"redundant_projection_read_operation:{operation_id}"
                for operation_id in redundant_projection_reads
            )
            if list(compile_meta.get("semantic_missing_step_ids") or []):
                reason_codes.extend(
                    "required_operation_missing:"
                    + _LEGACY_STEP_DIRECT_OPERATION.get(
                        _compact_text(step_id),
                        _compact_text(step_id),
                    )
                    for step_id in list(
                        compile_meta.get("semantic_missing_step_ids") or []
                    )
                    if _compact_text(step_id)
                )
                reason_codes.extend(
                    [
                        *list(rejected),
                        "deterministic_business_plan_rewrite_required",
                    ]
                )
            if reason_codes:
                return [], [], list(dict.fromkeys(reason_codes)), compile_meta
            return accepted_ids, compiled_specs, [], compile_meta

        def recover_unique_typed_read(
            *,
            initial_reasons: list[str],
            repair_reasons: list[str],
            repair_compile_meta: dict[str, Any],
        ) -> tuple[list[str], list[dict[str, Any]], dict[str, Any]] | None:
            """Lower one unambiguous typed read after bounded model repair.

            Both model plans have already been rejected at this point.  This
            recovery is deliberately narrower than another planner attempt:
            the typed contract must authorize exactly one canonical read
            operation, both failures must be operation-shape mismatches only,
            and any active-selection read must have a trusted immutable
            selection to bind at the execution boundary.
            """

            mismatch_prefix = "typed_read_contract_operation_mismatch:"
            if (
                authorization_context.get("mode") != "inspect"
                or authorization_context.get("intent_kind") != "data_read"
                or not initial_reasons
                or not repair_reasons
                or any(
                    not _compact_text(reason).startswith(mismatch_prefix)
                    for reason in [*initial_reasons, *repair_reasons]
                )
            ):
                return None
            typed_contract = dict(
                authorization_context.get("semantic_contract") or {}
            )
            expected_operations = {
                _compact_text(value)
                for value in list(
                    repair_compile_meta.get("expected_typed_read_operations")
                    or expected_order_read_operations(
                        typed_contract,
                        requested_fields=list(
                            authorization_context.get("requested_fields") or []
                        ),
                    )
                )
                if _compact_text(value)
            }
            if len(expected_operations) != 1:
                return None
            operation_id = next(iter(expected_operations))
            tool = operation_candidates.get(operation_id)
            if (
                tool is None
                or not bool(getattr(tool, "read_only", False))
                or bool(getattr(tool, "destructive", False))
                or bool(getattr(tool, "requires_approval", False))
                or _compact_text(getattr(tool, "action_type", "read")).casefold()
                != "read"
            ):
                return None
            record_scope = _compact_text(
                typed_contract.get("record_scope")
            ).casefold()
            if (
                record_scope == "active_selection"
                and not bool(
                    authorization_context.get(
                        "trusted_contextual_order_selection"
                    )
                )
            ):
                return None
            # Exact-id reads without a trusted typed selection still depend on
            # model-authored identifiers.  Do not synthesize those targets.
            if record_scope == "exact_ids":
                return None

            arguments: dict[str, Any] = {}
            parameter_schema = (
                tool.parameters
                if isinstance(getattr(tool, "parameters", None), dict)
                else {}
            )
            parameter_properties = (
                parameter_schema.get("properties")
                if isinstance(parameter_schema.get("properties"), dict)
                else {}
            )
            period = _compact_text(typed_contract.get("period")).casefold()
            if (
                period
                and period != "unspecified"
                and "period" in parameter_properties
            ):
                arguments["period"] = period
            step_id = (
                _canonical_step_id_for_operation(operation_id)
                or operation_id
            )
            requested_evidence = list(
                dict.fromkeys(
                    _compact_text(value)
                    for value in list(
                        authorization_context.get("requested_fields") or []
                    )
                    if _compact_text(value)
                )
            )
            candidate = {
                "id": step_id,
                "operation_id": operation_id,
                "arguments": arguments,
                "depends_on": [],
                "objective": _compact_text(goal),
                "expected_evidence": requested_evidence,
            }
            (
                recovered_ids,
                recovered_specs,
                recovered_reasons,
                recovered_compile_meta,
            ) = validate_model_specs([candidate])
            if recovered_reasons or not recovered_specs:
                return None
            return recovered_ids, recovered_specs, {
                **dict(recovered_compile_meta),
                "source": "typed_unique_read_recovery",
                "typed_unique_read_recovery": True,
                "typed_unique_read_operation": operation_id,
                "typed_unique_read_recovery_reason": (
                    "bounded_model_operation_mismatch"
                ),
                "model_plan_bypassed": False,
            }

        initial_reason_codes: list[str] = []
        initial_compile_meta: dict[str, Any] = {}
        if any(_compact_text(spec.get("operation_id")) for spec in raw_specs):
            accepted_ids, accepted_specs, initial_reason_codes, initial_compile_meta = (
                validate_model_specs(raw_specs)
            )
            meta.update(
                {
                    "source": "llm_direct" if accepted_specs else "model_plan_rejected",
                    "llm_step_ids": [
                        _compact_text(spec.get("id")) for spec in raw_specs
                    ],
                    "rejected_step_ids": list(initial_reason_codes),
                    "operation_candidate_ids": list(operation_candidates),
                    "compact_planner_contract": tight_local_context,
                }
            )
            if accepted_specs:
                meta.update(initial_compile_meta)
                meta["rejected_step_ids"] = list(
                    dict.fromkeys(
                        [
                            *list(
                                initial_compile_meta.get("policy_rejected_step_ids")
                                or []
                            ),
                            *list(
                                initial_compile_meta.get("semantic_dropped_step_ids")
                                or []
                            ),
                        ]
                    )
                )
                meta["step_ids"] = list(accepted_ids)
                meta["step_specs"] = [dict(spec) for spec in accepted_specs]
                return accepted_ids, meta
        else:
            raw_step_ids = _planner_step_ids(payload)
            legacy_specs: list[dict[str, Any]] = []
            legacy_rejected: list[str] = []
            for raw_step_id in raw_step_ids:
                step_id = _compact_text(raw_step_id)
                operation_id = _LEGACY_STEP_DIRECT_OPERATION.get(step_id, step_id)
                tool = operation_candidates.get(operation_id)
                if (
                    not step_id
                    or tool is None
                    or not _step_allowed_for_goal(step_id, goal)
                ):
                    if step_id:
                        legacy_rejected.append(step_id)
                    continue
                legacy_specs.append(
                    {
                        "id": step_id,
                        "operation_id": operation_id,
                        "arguments": {},
                        "depends_on": [],
                        "objective": _task_step_prompt("orders", step_id, goal),
                        "expected_evidence": list(
                            dict((tool.result_schema or {}).get("properties") or {}).keys()
                        )[:8],
                    }
                )
            if legacy_specs:
                accepted_ids, accepted_specs, initial_reason_codes, initial_compile_meta = (
                    validate_model_specs(legacy_specs)
                )
                if accepted_specs:
                    meta.update(initial_compile_meta)
                    meta.update(
                        {
                            "source": "llm_canonical_resolved",
                            "llm_step_ids": list(raw_step_ids),
                            "canonical_operation_resolution": True,
                            "operation_candidate_ids": list(operation_candidates),
                            "rejected_step_ids": list(
                                dict.fromkeys(
                                    [
                                        *legacy_rejected,
                                        *list(
                                            initial_compile_meta.get(
                                                "policy_rejected_step_ids"
                                            )
                                            or []
                                        ),
                                        *list(
                                            initial_compile_meta.get(
                                                "semantic_dropped_step_ids"
                                            )
                                            or []
                                        ),
                                    ]
                                )
                            ),
                            "step_ids": list(accepted_ids),
                            "step_specs": [dict(spec) for spec in accepted_specs],
                        }
                    )
                    return accepted_ids, meta
            else:
                initial_reason_codes = [
                    "exact_operation_id_required"
                    if raw_specs or raw_step_ids
                    else "no_usable_step_ids"
                ]

        meta.update(
            {
                "source": "model_plan_repair",
                "initial_model_plan": [dict(spec) for spec in raw_specs],
                "initial_plan_reason_codes": list(initial_reason_codes),
                "initial_compile_verification": dict(initial_compile_meta),
                "planner_repair_invoked": True,
            }
        )
        repair_payload = _extract_json_payload(
            invoke_provider_planner(
                planner_client,
                _orders_plan_repair_prompt(
                    goal,
                    limit,
                    operation_candidates=operation_candidates,
                    typed_context=typed_context,
                    semantic_contract=dict(
                        authorization_context.get("semantic_contract") or {}
                    ),
                    rejected_plan=raw_specs,
                    reason_codes=initial_reason_codes,
                    compile_evidence=initial_compile_meta,
                    compact_contract=tight_local_context,
                ),
                response_schema=_TASK_PLAN_RESPONSE_SCHEMA,
                prefer_guarded_json=True,
            )
        )
        repair_specs = _planner_step_specs(repair_payload)
        if any(_compact_text(spec.get("operation_id")) for spec in repair_specs):
            repaired_ids, repaired_specs, repair_reason_codes, repair_compile_meta = (
                validate_model_specs(repair_specs)
            )
            meta.update(
                {
                    "repair_model_plan": [dict(spec) for spec in repair_specs],
                    "repair_plan_reason_codes": list(repair_reason_codes),
                    "repair_compile_verification": dict(repair_compile_meta),
                }
            )
            if repaired_specs:
                meta.update(repair_compile_meta)
                meta.update(
                    {
                        "source": "llm_direct_repaired",
                        "step_ids": list(repaired_ids),
                        "step_specs": [dict(spec) for spec in repaired_specs],
                        "rejected_step_ids": list(initial_reason_codes),
                        "planner_repair_accepted": True,
                    }
                )
                return repaired_ids, meta
        else:
            meta["repair_plan_reason_codes"] = ["exact_operation_id_required"]
        recovered_read = recover_unique_typed_read(
            initial_reasons=list(initial_reason_codes),
            repair_reasons=list(meta.get("repair_plan_reason_codes") or []),
            repair_compile_meta=dict(
                meta.get("repair_compile_verification") or {}
            ),
        )
        if recovered_read is not None:
            recovered_ids, recovered_specs, recovered_meta = recovered_read
            meta.update(recovered_meta)
            meta.update(
                {
                    "step_ids": list(recovered_ids),
                    "step_specs": [
                        dict(spec) for spec in recovered_specs
                    ],
                    "rejected_step_ids": list(
                        dict.fromkeys(
                            [
                                *list(initial_reason_codes),
                                *list(
                                    meta.get("repair_plan_reason_codes") or []
                                ),
                            ]
                        )
                    ),
                    "requires_clarification": False,
                }
            )
            return recovered_ids, meta
        meta.update(
            {
                "source": "model_plan_rejected",
                "step_ids": [],
                "step_specs": [],
                "requires_clarification": True,
                "clarification": (
                    "Model isteğin için güvenli ve semantik olarak geçerli bir atomic plan "
                    "kuramadı. Hiçbir API, DB, dosya veya yazıcı işlemi yapılmadı. "
                    "Hedefi yeniden ifade ederek tekrar deneyebilirsin."
                ),
            }
        )
        return [], meta
    except Exception as exc:
        provider_failure = _planner_provider_unavailable_details(
            planner_client
        )
        if provider_failure:
            meta.update(
                {
                    "source": "model_plan_provider_unavailable",
                    "step_ids": [],
                    "step_specs": [],
                    "provider_unavailable": True,
                    "provider_failure": dict(provider_failure),
                    "provider_notice": _provider_unavailable_answer(
                        provider_failure
                    ),
                    "requires_clarification": False,
                }
            )
            return [], meta
        meta["planner_error"] = _compact_text(exc)
        meta.update(
            {
                "source": "model_plan_failed",
                "step_ids": [],
                "step_specs": [],
                "requires_clarification": True,
                "clarification": (
                    "Model güvenli bir task planı üretemedi. Hiçbir işlem yapılmadı; "
                    "provider erişimi düzeldiğinde veya hedef yeniden ifade edildiğinde "
                    "tekrar deneyebilirsin."
                ),
            }
        )
    return [], meta


def _web_report_uses_granted_observations(specs: list[dict[str, Any]], contexts: list[dict[str, Any]]) -> bool:
    """A source-bound report may reuse runtime-granted opened observations."""
    granted = {
        ref.get("artifact_id") for context in contexts if isinstance(context, dict)
        and context.get("kind") == "observation_artifact_refs"
        for ref in context.get("artifacts") or [] if isinstance(ref, dict)
        and (ref.get("origin") or {}).get("operation_id") in {"web.open", "web.document.read", "web.follow"}
    }
    historical_steps = {
        spec["id"] for spec in specs if spec.get("operation_id") == "artifacts.read"
        and isinstance((spec.get("arguments") or {}).get("artifact_id"), str)
        and spec["arguments"]["artifact_id"] in granted
    }
    return any(
        binding.get("$from_step") in historical_steps
        and binding.get("path") == "tool_result.result.web_observation"
        for spec in specs if spec.get("operation_id") == "web.research_report"
        for binding in (spec.get("arguments") or {}).get("web_observations") or []
        if _is_step_output_binding(binding)
    )


def _domain_task_plan(
    domain: str,
    goal: str,
    *,
    planner_client: ChatClient | None,
    max_steps: int,
    turn_interpretation: dict[str, Any] | None = None,
    typed_context: list[dict[str, Any]] | None = None,
) -> tuple[list[str], dict[str, Any]]:
    clean_domain = _compact_text(domain).casefold()
    catalog = TASK_DOMAIN_STEP_CATALOGS.get(clean_domain, {})
    limit = max(1, int(max_steps or 8))
    web_fallback_specs = (
        _web_template_step_specs(goal)[:limit]
        if clean_domain == "web"
        else []
    )
    fallback = (
        [_compact_text(spec.get("id")) for spec in web_fallback_specs]
        if web_fallback_specs
        else _domain_template_step_ids(clean_domain, goal)[:limit]
    )
    meta: dict[str, Any] = {
        "source": "template",
        "step_ids": list(fallback),
        "rejected_step_ids": [],
        "fallback_step_ids": list(fallback),
    }
    interpretation = dict(turn_interpretation or {})
    read_domains = _explicit_business_read_domains(clean_domain, goal, interpretation)
    if interpretation.get("intent_kind") == "data_read" and any(
        _task_step_kind(clean_domain, step_id) != "read" for step_id in fallback
    ):
        fallback = [
            step_id for step_id in fallback
            if _task_step_kind(clean_domain, step_id) == "read"
        ] or [
            step_id for step_id in catalog
            if _task_step_kind(clean_domain, step_id) == "read"
        ][:limit]
        meta["step_ids"] = list(fallback)
        meta["fallback_step_ids"] = list(fallback)
    semantic_contract = dict(interpretation.get("semantic_contract") or {})
    strict_read_contract = bool(
        clean_domain in {"general", "reports", "analysis", "files"}
        or semantic_contract.get("entity") and interpretation.get("intent_kind") == "data_read"
    )
    if interpretation:
        meta["model_plan_authorization"] = {
            "mode": interpretation.get("mode"), "domain": clean_domain,
            "requested_fields": list(interpretation.get("requested_fields") or []),
            "semantic_contract": semantic_contract,
        }
    if web_fallback_specs:
        meta["step_specs"] = [dict(spec) for spec in web_fallback_specs]
        meta["atomic_web_template"] = True
    if planner_client is None:
        if strict_read_contract:
            meta.update(source="model_plan_invalid", step_ids=[], requires_clarification=True,
                        clarification="İstenen veri kaynağına bağlı bir okuma planı doğrulanamadı; işlem tamamlanmadı.")
            return [], meta
        return fallback, meta
    operation_candidates = _planner_operation_candidates(
        clean_domain,
        goal,
        limit=max(12, limit * 3),
        read_domains=read_domains,
    )
    # A required typed capability cannot disappear because lexical retrieval
    # failed on a suffix or typo. Expose it; the model still authors the plan.
    from AI.processors.tools import available_tools
    registry = available_tools()
    for operation_id in sorted(expected_business_read_operations(semantic_contract)):
        tool = registry.get(operation_id)
        if tool is not None and tool.domain == clean_domain:
            operation_candidates.setdefault(operation_id, tool)
    catalog_lines = [
        (
            f"- {operation_id}: "
            f"{'write_prepare' if bool(tool.requires_approval or tool.action_type != 'read') else 'read'}; "
            f"description={_compact_text(tool.description)}; "
            f"arguments_schema={json.dumps(tool.parameters or {}, ensure_ascii=False, sort_keys=True)}"
            f"{_tool_source_contract(tool)}"
        )
        for operation_id, tool in operation_candidates.items()
    ]
    example_operation_id = next(
        iter(operation_candidates),
        next(iter(catalog), f"{clean_domain}.summary"),
    )
    prompt = (
        f"{clean_domain} domain agent task plani olustur. Yalnizca katalogdaki exact operation_id degerlerini kullan.\n"
        "Her step icin benzersiz id, typed arguments, depends_on, objective ve expected_evidence ver. "
        "Typed arguments'i arguments_json alaninda tek bir gecerli JSON object string'i olarak kodla.\n"
        f"{_atomic_plan_argument_contract()}"
        "Bir step dependency ciktisini kullanacaksa {\"$from_step\":\"kaynak_step\",\"path\":\"tool_result.alan\"} typed bagini kullan.\n"
        "Write_prepare operation'ini yalniz kullanici acikca bir degisiklik, kayit, silme, senkron veya disari aktarma istediyse sec; execute yine onay gerektirir.\n"
        "Salt okuma hedefinde write_prepare ekleme. Cevap sadece JSON olsun: "
        f'{{"steps":[{{"id":"step_1","operation_id":"{example_operation_id}","arguments_json":"{{}}","depends_on":[],"objective":"...","expected_evidence":[]}}]}}\n'
        f"Hedef: {_compact_text(goal)}\nTyped record contract: {json.dumps(semantic_contract, ensure_ascii=False)}\n"
        f"Typed task context: {json.dumps(typed_context or [], ensure_ascii=False, sort_keys=True)}\n"
        "Dosya araclari yalniz bu context'teki imported attachment_id degerlerini okuyabilir. "
        "files session_id runtime tarafindan trusted import workspace'ten baglanir; path veya "
        "baska session secme. Data coverage partial ise tamamini okudugunu iddia etme.\n"
        f"Izinli salt okuma domainleri: {json.dumps(sorted(read_domains))}. "
        "Birden cok domain istendiyse gerekli read araclarini birlikte sec; veri kapsamlari ve para birimlerini esit varsayma.\n"
        f"ReadEvidenceContract={json.dumps(business_read_plan_constraints(semantic_contract), ensure_ascii=False, sort_keys=True)}\n"
        "Istenen kayit kanitini ReadEvidenceContract.operation_alternatives icinden sec; "
        "baska bir entity'nin kayitlari ayni tam populasyonu kanitlamaz.\n"
        "Atomic operation katalogu:\n" + "\n".join(catalog_lines)
    )
    try:
        payload = _extract_json_payload(
            invoke_provider_planner(
                planner_client,
                prompt,
                response_schema=_TASK_PLAN_RESPONSE_SCHEMA,
            )
        )
        raw_specs = _planner_step_specs(payload)
        if any(_compact_text(spec.get("operation_id")) for spec in raw_specs):
            plan_diagnostics: list[dict[str, Any]] = []
            accepted_specs, rejected = _validate_direct_plan_specs(
                clean_domain,
                raw_specs,
                goal,
                allowed_operations=operation_candidates,
                max_steps=limit,
                read_domains=read_domains,
                authorization_context=interpretation,
                validation_diagnostics=plan_diagnostics,
            )
            discovery_only = bool(accepted_specs) and all(
                spec.get("operation_id") == "operations.discover"
                for spec in accepted_specs
            )
            population_problems = [
                code
                for spec in accepted_specs
                for code in validate_business_read_arguments(
                    semantic_contract, _compact_text(spec.get("operation_id")), dict(spec.get("arguments") or {})
                )
            ] if interpretation.get("intent_kind") == "data_read" and not discovery_only else []
            if not discovery_only:
                population_problems.extend(
                    _missing_business_read_domains(accepted_specs, read_domains)
                )
            if population_problems or rejected:
                rejected.extend(population_problems)
                repair_prompt = (
                    "Domain read plan contract repair. Onceki plan reddedildi ve calistirilmadi. "
                    "Yalniz ayni kullanici hedefi ve typed entity populasyonu icin gecerli atomik plan ver. "
                    "Bu tek duzeltme denemesidir; eski template plan kullanilamaz.\n"
                    "marketplace_account + list icin marketplaces.account_lookup kullanilabilir; summary/catalog tam hesap listesi sozlesmesini karsilamaz.\n"
                    f"Validation errors: {json.dumps(list(rejected))}\n"
                    f"Exact step diagnostics: {json.dumps(plan_diagnostics, ensure_ascii=False)}\n"
                    f"Rejected plan: {json.dumps(raw_specs, ensure_ascii=False)}\n" + prompt
                )
                meta["domain_plan_repair"] = {"invoked": True, "initial_errors": list(rejected),
                    "initial_diagnostics": plan_diagnostics, "applied": False}
                repaired_payload = _extract_json_payload(invoke_provider_planner(
                    planner_client, repair_prompt, response_schema=_TASK_PLAN_RESPONSE_SCHEMA, prefer_guarded_json=True
                ))
                repaired_specs = _planner_step_specs(repaired_payload)
                accepted_specs, repair_rejected = _validate_direct_plan_specs(
                    clean_domain, repaired_specs, goal, allowed_operations=operation_candidates, max_steps=limit,
                    read_domains=read_domains,
                    authorization_context=interpretation,
                )
                repair_problems = [
                    code for spec in accepted_specs for code in validate_business_read_arguments(
                        semantic_contract, _compact_text(spec.get("operation_id")), dict(spec.get("arguments") or {})
                    )
                ]
                repair_problems.extend(
                    _missing_business_read_domains(accepted_specs, read_domains)
                )
                if repair_rejected or repair_problems:
                    accepted_specs = []
                meta["domain_plan_repair"]["applied"] = bool(accepted_specs)
                meta["domain_plan_repair"]["repair_errors"] = list(repair_rejected) + repair_problems
            accepted_ids = [
                _compact_text(spec.get("id")) for spec in accepted_specs
            ]
            meta.update(
                {
                    "source": "llm_direct" if accepted_specs else "template",
                    "llm_step_ids": [
                        _compact_text(spec.get("id")) for spec in raw_specs
                    ],
                    "rejected_step_ids": list(rejected),
                    "operation_candidate_ids": list(operation_candidates),
                }
            )
            if accepted_specs:
                meta["discovery_only_plan"] = discovery_only
                if clean_domain == "web" and web_fallback_specs and not discovery_only:
                    model_operation_ids = [
                        _compact_text(spec.get("operation_id"))
                        for spec in accepted_specs
                    ]
                    required_operation_ids = [
                        _compact_text(spec.get("operation_id"))
                        for spec in web_fallback_specs
                    ]
                    if _web_report_uses_granted_observations(accepted_specs, typed_context or []):
                        required_operation_ids = [operation for operation in required_operation_ids
                                                  if operation not in {"web.search", "web.open"}]
                        meta["historical_opened_web_sources_reused"] = True
                    if any(model_operation_ids.count(operation_id) < required_operation_ids.count(operation_id)
                           for operation_id in set(required_operation_ids)):
                        # Search candidates are never evidence.  A syntactically
                        # valid provider plan may still omit the mandatory open,
                        # comparison, immutable report or approval-gated export
                        # steps.  The deterministic compiler owns those semantic
                        # invariants and falls back to the canonical atomic graph.
                        # Keep the model's validated public query and filters.
                        # The full user message can contain privacy constraints
                        # and other text that must never become a search query.
                        model_searches = [spec for spec in accepted_specs if spec.get('operation_id') == 'web.search']
                        if len(model_searches) == 1:
                            for template_spec in web_fallback_specs:
                                if template_spec.get('operation_id') == 'web.search':
                                    template_spec['arguments'] = deepcopy(model_searches[0]['arguments'])
                        meta.update(
                            {
                                "semantic_compiler_reconciled": True,
                                "model_operation_ids": model_operation_ids,
                                "required_operation_ids": required_operation_ids,
                                "semantic_compiler_inserted": [
                                    operation_id
                                    for operation_id in required_operation_ids
                                    if operation_id not in model_operation_ids
                                ],
                                "semantic_compiler_dropped": [
                                    operation_id
                                    for operation_id in model_operation_ids
                                    if operation_id not in required_operation_ids
                                ],
                                "step_ids": list(fallback),
                                "step_specs": [dict(spec) for spec in web_fallback_specs],
                                "atomic_web_template": True,
                            }
                        )
                        return list(fallback), meta
                meta.pop('atomic_web_template', None)
                meta["step_ids"] = list(accepted_ids)
                meta["step_specs"] = [dict(spec) for spec in accepted_specs]
                return accepted_ids, meta
            if strict_read_contract:
                raise ValueError("typed_read_plan_invalid_after_repair")
            return fallback, meta
        if strict_read_contract:
            raise ValueError("typed_read_plan_requires_atomic_operations")
        raw = _planner_step_ids(payload)
        accepted, rejected = _validate_domain_plan_step_ids(
            clean_domain,
            raw,
            goal,
            limit,
        )
        meta.update(
            {
                "source": "llm" if accepted else "template",
                "llm_step_ids": raw,
                "rejected_step_ids": rejected,
            }
        )
        if accepted:
            meta["step_ids"] = accepted
            meta.pop("step_specs", None)
            return accepted, meta
    except Exception as exc:
        meta["planner_error"] = _compact_text(exc)
        if strict_read_contract:
            meta.update(source="model_plan_invalid", step_ids=[], requires_clarification=True,
                        clarification="İstenen veri kaynağına bağlı bir okuma planı doğrulanamadı; işlem tamamlanmadı.")
            return [], meta
    return fallback, meta


def _stock_task_plan(
    goal: str,
    *,
    planner_client: ChatClient | None,
    max_steps: int,
    turn_interpretation: dict[str, Any] | None = None,
) -> tuple[list[str], dict[str, Any]]:
    return _domain_task_plan(
        "stock",
        goal,
        planner_client=planner_client,
        max_steps=max_steps,
        turn_interpretation=turn_interpretation,
    )


def _apply_task_model_capability_policy(
    domain: str,
    goal: str,
    step_ids: list[str],
    plan_meta: dict[str, Any],
    *,
    planner_client: ChatClient | None,
    max_steps: int,
) -> tuple[list[str], dict[str, Any]]:
    """Constrain model-authored write plans to the selected model profile."""

    clean_domain = _compact_text(domain).casefold()
    accepted = list(step_ids)
    meta = dict(plan_meta or {})
    step_specs = [
        dict(spec)
        for spec in list(meta.get("step_specs") or [])
        if isinstance(spec, dict)
    ]
    spec_by_id = {
        _compact_text(spec.get("id")): spec
        for spec in step_specs
        if _compact_text(spec.get("id"))
    }

    def is_write_prepare(step_id: str) -> bool:
        operation_id = _compact_text(
            (spec_by_id.get(_compact_text(step_id)) or {}).get("operation_id")
        )
        if operation_id:
            from AI.processors.tools import available_tools

            tool = available_tools().get(operation_id)
            if tool is not None:
                return bool(tool.requires_approval or tool.action_type != "read")
        return _task_step_kind(clean_domain, step_id) == "write_prepare"

    profile = runtime_capability_profile(planner_client, None)
    write_steps = [
        step_id
        for step_id in accepted
        if is_write_prepare(step_id)
    ]
    if not profile or not write_steps:
        if profile:
            meta["capability_profile"] = dict(profile)
        return accepted, meta

    prepare_gate = evaluate_model_capability_gate(
        profile,
        prepare_write=True,
        external_write=False,
        decision_source=_compact_text(meta.get("source")) or "template",
    )
    if not prepare_gate.allowed:
        accepted = [
            step_id
            for step_id in accepted
            if not is_write_prepare(step_id)
        ]
        if step_specs:
            meta["step_specs"] = [
                dict(spec)
                for spec in step_specs
                if _compact_text(spec.get("id")) in accepted
            ]
        meta.update(
            {
                "source": "model_capability_limited",
                "capability_limited": True,
                "blocked_write_step_ids": write_steps,
                "capability_guard": prepare_gate.to_dict(),
                "capability_profile": dict(profile),
                "capability_notice": prepare_gate.message,
            }
        )
        return accepted, meta

    external_plan_gate = evaluate_model_capability_gate(
        profile,
        prepare_write=True,
        external_write=True,
        decision_source=_compact_text(meta.get("source")) or "template",
    )
    if not external_plan_gate.allowed:
        limit = max(1, int(max_steps or 1))
        deterministic = (
            _orders_template_step_ids(goal)
            if clean_domain == "orders"
            else _domain_template_step_ids(clean_domain, goal)
        )[:limit]
        meta.update(
            {
                "model_plan_source": meta.get("source"),
                "model_step_ids": list(accepted),
                "source": "capability_guarded_template",
                "step_ids": list(deterministic),
                "capability_degraded": True,
                "capability_guard": external_plan_gate.to_dict(),
                "capability_profile": dict(profile),
            }
        )
        meta.pop("step_specs", None)
        return deterministic, meta

    meta["capability_profile"] = dict(profile)
    meta["capability_guard"] = external_plan_gate.to_dict()
    return accepted, meta


def _nonreplaceable_plan_step_ids(state: AgentSessionState) -> set[str]:
    """Mirror GoalPlan's immutable-node boundary before accepting a replan."""
    ids = {step.step_id for step in state.completed_steps if step.step_id}
    plan = state.active_goal_plan()
    if plan is not None:
        ids.update(step.step_id for step in plan.steps if step.step_id and (
            step.status not in {'pending', 'superseded'} or step.attempt_count
            or step.tool_names or step.observation_ids or step.result_data))
    return ids


def _completed_source_operations(state: AgentSessionState) -> dict[str, str]:
    """Identify actual observed producers; never infer them from planned roles."""
    return {
        step.step_id: step.tool_names[0]
        for step in state.completed_steps
        if step.status == "completed"
        and step.verification_status in {"observed", "verified"}
        and step.step_id and len(step.tool_names) == 1
    }


def _replan_completed_source_evidence(state: AgentSessionState) -> list[dict[str, Any]]:
    """Expose bounded structure and scope, without record cells or secrets."""
    operations = _completed_source_operations(state)
    evidence = []
    scope_keys = (
        "period", "period_label", "start_ms", "end_ms", "start_date_ms", "end_date_ms",
        "start_date", "end_date", "currency", "currencies", "quantity_unit", "data_coverage",
        "environment", "environment_by_account", "requested_api_account_ids", "company_id", "warehouse_id",
        "fresh_read", "freshness", "historical_observation", "observed_at", "source_snapshot_hash",
    )

    def describe(value: Any, path: str, rows: list[dict[str, str]], depth: int = 0) -> None:
        if len(rows) >= 128 or depth > 6:
            return
        kind = ("object" if isinstance(value, dict) else "array" if isinstance(value, list)
                else "null" if value is None else "boolean" if isinstance(value, bool)
                else "integer" if isinstance(value, int) else "number" if isinstance(value, (float, Decimal))
                else "string" if isinstance(value, str) else "unknown")
        descriptor = {"path": path, "type": kind}
        if descriptor not in rows:
            rows.append(descriptor)
        if isinstance(value, dict):
            for key, child in sorted(value.items(), key=lambda item: item[0] not in {'result', 'rows', 'data'})[:64]:
                if isinstance(key, str) and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key):
                    describe(child, f"{path}.{key}" if path else key, rows, depth + 1)
        elif isinstance(value, list):
            for child in value[:8]:
                describe(child, f"{path}[]", rows, depth + 1)

    for step in state.completed_steps:
        if step.step_id not in operations:
            continue
        result = (step.result_data or {}).get("tool_result")
        if not isinstance(result, dict):
            continue
        fields: list[dict[str, str]] = []
        describe(result, "", fields)
        scope = {key: deepcopy(result[key]) for key in scope_keys if key in result}
        evidence.append({"step_id": step.step_id, "operation_id": operations[step.step_id],
                         "verification_status": step.verification_status,
                         "binding": {"$from_step": step.step_id, "path": "tool_result"},
                         "result_paths_relative_to_binding": fields, "read_scope": scope})
    return evidence


def _domain_replan_prompt(
    state: AgentSessionState,
    failed_step: AgentTaskStep,
    *,
    max_steps: int,
    operation_candidates: dict[str, Any] | None = None,
) -> str:
    catalog_lines = []
    domain = _compact_text(state.active_domain).casefold()
    candidates = operation_candidates or _planner_operation_candidates(
        domain,
        f"{state.goal} {failed_step.result_message}",
    )
    for operation_id, tool in candidates.items():
        operation_kind = (
            "write_prepare"
            if bool(tool.requires_approval or tool.action_type != "read")
            else "read"
        )
        catalog_lines.append(
            f"- {operation_id}: {operation_kind}; "
            f"description={_compact_text(tool.description)}; "
            f"arguments_schema={json.dumps(tool.parameters or {}, ensure_ascii=False, sort_keys=True)}"
            f"{_tool_source_contract(tool)}"
        )
    completed = [
        step.step_id
        for step in state.completed_steps
        if step.status == "completed" and _compact_text(step.step_id)
    ]
    remaining = [step.step_id for step in state.remaining_steps if _compact_text(step.step_id)]
    used_ids = [step.step_id for step in state.completed_steps if _compact_text(step.step_id)]
    failed_data = dict(failed_step.result_data or {})
    failed_result = failed_data.get("tool_result")
    failed_diagnostics = {
        key: failed_data[key] for key in ("tool", "retryable", "argument_problems") if key in failed_data
    }
    if isinstance(failed_result, dict):
        failed_diagnostics.update({key: deepcopy(failed_result[key]) for key in (
            "reason_codes", "projection_diagnostic", "failed_operand", "repair_policy",
        ) if key in failed_result})
    semantic_failure = failed_data.get("semantic_verification")
    if isinstance(semantic_failure, dict):
        failed_diagnostics["semantic_reason_codes"] = list(semantic_failure.get("reason_codes") or [])
        semantic_evidence = semantic_failure.get("evidence") or {}
        if isinstance(semantic_evidence, dict) and isinstance(semantic_evidence.get("config_schema_contract"), dict):
            failed_diagnostics["config_schema_contract"] = deepcopy(semantic_evidence["config_schema_contract"])
            if isinstance(semantic_evidence.get("configuration_schema_reviews"), list):
                failed_diagnostics["configuration_schema_reviews"] = deepcopy(semantic_evidence["configuration_schema_reviews"])
    previous_rejections = [dict(row) for row in list((state.active_entities or {}).get("replans") or [])[-2:]
                           if isinstance(row, dict)]
    previous_diagnostics = [{key: row[key] for key in (
        "failed_step_id", "rejected_step_ids", "validation_diagnostics", "applied",
    ) if key in row} for row in previous_rejections]
    return (
        f"{domain or 'unknown'} domain agent gorevini bir adim basarisiz oldugu icin yeniden planla.\n"
        "Yalnizca katalogdaki exact operation_id degerlerini kullan. Tamamlanan adimlari tekrarlama.\n"
        "Her step icin benzersiz id, typed arguments, depends_on, objective ve expected_evidence ver. "
        "Typed arguments'i arguments_json alaninda tek bir gecerli JSON object string'i olarak kodla.\n"
        "Dependency ciktisi gerekiyorsa {\"$from_step\":\"kaynak_step\",\"path\":\"tool_result.alan\"} typed bagini kullan.\n"
        "Completed source step_id -> operation_id eslemesini aynen koru; adimlari yeniden numaralandirma. "
        "Her source_step_id / $from_step icin exact depends_on ekle. sources.result tam tool_result'a baglanir. "
        "reports.build_snapshot rows_path zaten baglanmis result'a gore, column.source_path secilen satira goredir; "
        "rows_path'a yeniden tool_result oneki ekleme ve gozlenmemis alan uydurma.\n"
        "Kayit-hedefli write_prepare icin exact kimlik setini ureten read dependency zorunludur; count tek basina hedef kaniti degildir.\n"
        "Kullanicinin acikca istemedigi write_prepare operation'ini ekleme. Execute yine onay gerektirir.\n"
        "Basarisiz operation'i ayni hatali argumanlarla tekrarlama. Gercek diagnostic'e gore argumanlar "
        "duzeltilebiliyorsa yeni benzersiz step id ile duzelt; tamamlanmis bir effect'i yeniden yurutme. "
        "Guvenli duzeltme veya alternatif veri/tool yolu yoksa bos steps dondur.\n"
        f"En fazla {max(1, int(max_steps or 1))} step dondur.\n"
        "Cevap sadece JSON olsun: {\"steps\":[{\"id\":\"new_unique_step_id\",\"operation_id\":\"catalog.operation\",\"arguments_json\":\"{}\",\"depends_on\":[],\"objective\":\"...\",\"expected_evidence\":[]}],\"reason\":\"...\"}\n"
        f"Hedef: {_compact_text(state.goal)}\n"
        f"Basarisiz step: {_compact_text(failed_step.step_id) or '-'}\n"
        f"Basarisiz prompt: {_compact_text(failed_step.prompt)}\n"
        f"Hata: {_compact_text(failed_step.result_message)}\n"
        f"Exact failure diagnostics: {json.dumps(failed_diagnostics, ensure_ascii=False, sort_keys=True)}\n"
        f"Forbidden completed/failed step IDs: {json.dumps(used_ids, ensure_ascii=False)}\n"
        f"Authoritative completed source evidence: {json.dumps(_replan_completed_source_evidence(state), ensure_ascii=False, sort_keys=True)}\n"
        f"Previous rejected replans: {json.dumps(previous_diagnostics, ensure_ascii=False, sort_keys=True)}\n"
        f"Tamamlanan step'ler: {json.dumps(completed, ensure_ascii=False)}\n"
        f"Onceki kalan step'ler: {json.dumps(remaining, ensure_ascii=False)}\n"
        "Atomic operation katalogu:\n"
        + "\n".join(catalog_lines)
    )


def _replan_after_failed_step(
    state: AgentSessionState,
    failed_step: AgentTaskStep,
    *,
    planner_client: ChatClient | None,
    max_replans: int,
    max_steps: int,
) -> bool:
    if max_steps <= 0:
        return False
    active_entities = state.active_entities if isinstance(state.active_entities, dict) else {}
    replans = [dict(row) for row in list(active_entities.get("replans") or []) if isinstance(row, dict)]
    reserved_child_replans = int(dict(active_entities.get("execution_budget") or {}).get("reserved_child_replans") or 0)
    if len(replans) + reserved_child_replans >= max(0, int(max_replans or 0)):
        return False

    def replace_step_binding(value: Any, old_step_id: str, new_step_id: str) -> Any:
        if isinstance(value, dict):
            return {
                key: (
                    new_step_id
                    if key == "$from_step" and _compact_text(child) == old_step_id
                    else replace_step_binding(child, old_step_id, new_step_id)
                )
                for key, child in value.items()
            }
        if isinstance(value, list):
            return [replace_step_binding(child, old_step_id, new_step_id) for child in value]
        return value

    def install_web_replacement(
        *,
        operation_id: str,
        prompt: str,
        objective: str,
        arguments: dict[str, Any],
        expected_evidence: list[str],
        reason: str,
        metadata: dict[str, Any],
        id_label: str,
    ) -> bool:
        failed_id = _compact_text(failed_step.step_id)
        existing_ids = {
            _compact_text(step.step_id)
            for step in [*state.completed_steps, *state.remaining_steps]
            if _compact_text(step.step_id)
        }
        suffix = 1
        replacement_id = f"{failed_id}_{id_label}_{suffix}"
        while replacement_id in existing_ids:
            suffix += 1
            replacement_id = f"{failed_id}_{id_label}_{suffix}"
        next_index = max(
            [step.index for step in [*state.completed_steps, *state.remaining_steps]]
            or [0]
        ) + 1
        replacement_step = AgentTaskStep(
            index=next_index,
            step_id=replacement_id,
            prompt=prompt,
            objective=objective,
            depends_on=[],
            operation_candidates=[operation_id],
            operation_domain="web",
            arguments=dict(arguments),
            expected_evidence=list(expected_evidence),
        )
        for remaining in state.remaining_steps:
            remaining.depends_on = [
                replacement_id if _compact_text(dep) == failed_id else dep
                for dep in remaining.depends_on
            ]
            remaining.arguments = dict(
                replace_step_binding(remaining.arguments, failed_id, replacement_id)
            )
            _sync_goal_plan_step(state, remaining)
        state.remaining_steps = [replacement_step, *state.remaining_steps]
        failed_step.result_data["replan_status"] = "superseded"
        failed_step.result_data["replacement_step_ids"] = [replacement_id]
        failed_step.verification_status = "superseded"
        _sync_goal_plan_step(state, failed_step)
        replan_row = {
            "failed_step_id": failed_id,
            "accepted_step_ids": [replacement_id],
            "rejected_step_ids": [],
            "reason": reason,
            "applied": True,
            "source": "deterministic_web_recovery",
            **dict(metadata),
        }
        replans.append(replan_row)
        active_entities["replans"] = replans
        state.active_entities = active_entities
        state.revise_goal_plan(
            [replacement_step],
            failed_step_id=failed_id,
            reason=reason,
        )
        state.touch()
        return True

    failed_operation = _compact_text((failed_step.operation_candidates or [""])[0])
    if failed_operation in {"web.open", "web.follow", "web.document.read"}:
        search_result: dict[str, Any] = {}
        for previous in reversed(state.completed_steps):
            previous_tool_result = (
                dict((previous.result_data or {}).get("tool_result") or {})
                if isinstance((previous.result_data or {}).get("tool_result"), dict)
                else {}
            )
            if _compact_text(previous_tool_result.get("tool")) == "web.search":
                search_result = previous_tool_result
                break
        attempted_urls: set[str] = set()
        for candidate in state.completed_steps:
            candidate_result = (
                dict((candidate.result_data or {}).get("tool_result") or {})
                if isinstance((candidate.result_data or {}).get("tool_result"), dict)
                else {}
            )
            if _compact_text(candidate_result.get("tool")) not in {
                "web.open",
                "web.follow",
                "web.document.read",
            }:
                continue
            attempted_urls.update(
                _compact_text(candidate_result.get(name))
                for name in ("url", "requested_url")
                if _compact_text(candidate_result.get(name))
            )
        attempted_urls.discard("")
        failed_tool_result = (
            dict((failed_step.result_data or {}).get("tool_result") or {})
            if isinstance((failed_step.result_data or {}).get("tool_result"), dict)
            else {}
        )
        failed_observation = (
            dict(failed_tool_result.get("web_observation") or {})
            if isinstance(failed_tool_result.get("web_observation"), dict)
            else {}
        )
        if failed_observation:
            from AI.processors.web_research import select_goal_relevant_web_link

            goal_link = select_goal_relevant_web_link(
                failed_observation,
                state.goal,
                excluded_urls=attempted_urls,
            )
            if goal_link:
                follow_url = _compact_text(goal_link.get("url"))
                return install_web_replacement(
                    operation_id="web.follow",
                    prompt=(
                        "Acilmis public observation icindeki hedef kanita yonelik exact "
                        "baglantiyi kontrollu bicimde izle"
                    ),
                    objective=(
                        "Kaynak sayfasindaki typed hedefle ilgili alt kaynagi yeni bir "
                        "WebObservation olarak ac"
                    ),
                    arguments={
                        "web_observation": failed_observation,
                        "link_url": follow_url,
                        "link_title": _compact_text(goal_link.get("title")),
                    },
                    expected_evidence=["web_observation", "observation_id", "url"],
                    reason="deterministic_goal_relevant_observation_link",
                    metadata={
                        "attempted_urls": sorted(attempted_urls),
                        "follow_url": follow_url,
                        "parent_observation_id": _compact_text(
                            failed_observation.get("observation_id")
                        ),
                        "link_selection_reason": _compact_text(goal_link.get("reason")),
                    },
                    id_label="follow",
                )
        fallback_candidate = next(
            (
                dict(row)
                for row in list(search_result.get("results") or [])
                if isinstance(row, dict)
                and _compact_text(row.get("url"))
                and _compact_text(row.get("url")) not in attempted_urls
            ),
            {},
        )
        fallback_url = _compact_text(fallback_candidate.get("url"))
        if fallback_url:
            fallback_operation = (
                "web.document.read"
                if fallback_url.casefold().endswith(".pdf")
                else "web.open"
            )
            return install_web_replacement(
                operation_id=fallback_operation,
                prompt="Siradaki acilmamis public arama adayini typed observation olarak ac",
                objective="Basarisiz web kaynagi yerine siradaki acilmamis adayi ac",
                arguments={
                    "url": fallback_url,
                    "query_summary": _compact_text(search_result.get("query_summary")),
                    "title": _compact_text(fallback_candidate.get("title")),
                    "published_at": _compact_text(fallback_candidate.get("published_date")),
                    "official": bool(fallback_candidate.get("official")),
                    "public_product_fields": list(search_result.get("public_product_fields") or []),
                },
                expected_evidence=["web_observation", "observation_id", "url"],
                reason="deterministic_next_unopened_search_candidate",
                metadata={
                    "attempted_urls": sorted(attempted_urls),
                    "fallback_url": fallback_url,
                },
                id_label="fallback",
            )

    if planner_client is None:
        return False

    completed_ids = {
        _compact_text(step.step_id)
        for step in state.completed_steps
        if step.status == "completed" and _compact_text(step.step_id)
    }
    failed_id = _compact_text(failed_step.step_id)
    domain = _compact_text(state.active_domain).casefold()
    read_domains = _active_business_read_domains(state)
    operation_candidates = _planner_operation_candidates(
        domain,
        f"{state.goal} {failed_step.result_message}",
        limit=max(12, max_steps * 3),
        read_domains=read_domains,
    )
    operation_candidates = _continuation_operation_candidates(state, operation_candidates)
    accepted_specs: list[dict[str, Any]] = []
    validation_diagnostics: list[dict[str, Any]] = []
    contract_repair: dict[str, Any] = {}
    replan_authorization = dict((state.active_entities or {}).get("turn_interpretation") or {})

    try:
        payload = _extract_json_payload(
            invoke_provider_planner(
                planner_client,
                _domain_replan_prompt(
                    state,
                    failed_step,
                    max_steps=max_steps,
                    operation_candidates=operation_candidates,
                ),
                response_schema=_TASK_PLAN_RESPONSE_SCHEMA,
            )
        )
        raw_specs = _planner_step_specs(payload)
        raw_step_ids = [
            _compact_text(spec.get("id"))
            for spec in raw_specs
            if _compact_text(spec.get("id"))
        ]
        if any(_compact_text(spec.get("operation_id")) for spec in raw_specs):
            accepted_specs, rejected = _validate_direct_plan_specs(
                domain,
                raw_specs,
                state.goal,
                allowed_operations=operation_candidates,
                max_steps=max_steps,
                satisfied_dependency_ids=completed_ids,
                satisfied_source_operations=_completed_source_operations(state),
                forbidden_step_ids={
                    _compact_text(candidate.step_id)
                    for candidate in state.completed_steps
                    if _compact_text(candidate.step_id)
                },
                read_domains=read_domains,
                validation_diagnostics=validation_diagnostics,
                authorization_context=replan_authorization,
            )
            accepted = [
                _compact_text(spec.get("id")) for spec in accepted_specs
            ]
            if not accepted_specs and rejected:
                # A rejected proposal has executed nothing. Give the model one
                # bounded schema/dataflow repair within this same replan and
                # the original provider deadline, without charging extra work
                # or granting an effect. Both attempts use the same guards.
                contract_repair = {
                    "invoked": True, "applied": False,
                    "initial_raw_step_ids": list(raw_step_ids),
                    "initial_rejected_step_ids": list(rejected),
                    "initial_validation_diagnostics": deepcopy(validation_diagnostics),
                }
                repair_prompt = (
                    "Failed-step recovery plan contract repair. Onceki replacement graph reddedildi; "
                    "hicbir yeni operation calismadi. Yalniz bir duzeltme denemesi var. "
                    "Completed/failed ID'leri yeniden kullanma; forbidden listedeki adimlar degistirilemez. "
                    "Gozlenen kaynak ID/operation eslesmelerini aynen koru, gecersiz typed argument/binding "
                    "ve dependency'leri actual diagnostics ile duzelt. Yeni step sayisi mevcut butceyi asamaz.\n"
                    f"Rejected replacement: {json.dumps(raw_specs, ensure_ascii=False)}\n"
                    f"Validation diagnostics: {json.dumps(validation_diagnostics, ensure_ascii=False)}\n"
                    + _domain_replan_prompt(state, failed_step, max_steps=max_steps,
                                            operation_candidates=operation_candidates)
                )
                payload = _extract_json_payload(invoke_provider_planner(
                    planner_client, repair_prompt, response_schema=_TASK_PLAN_RESPONSE_SCHEMA,
                    prefer_guarded_json=True,
                ))
                raw_specs = _planner_step_specs(payload)
                raw_step_ids = [_compact_text(spec.get("id")) for spec in raw_specs if _compact_text(spec.get("id"))]
                validation_diagnostics = []
                accepted_specs, rejected = _validate_direct_plan_specs(
                    domain, raw_specs, state.goal, allowed_operations=operation_candidates,
                    max_steps=max_steps, satisfied_dependency_ids=completed_ids,
                    satisfied_source_operations=_completed_source_operations(state),
                    forbidden_step_ids={candidate.step_id for candidate in state.completed_steps if candidate.step_id},
                    read_domains=read_domains, validation_diagnostics=validation_diagnostics,
                    authorization_context=replan_authorization,
                )
                accepted = [_compact_text(spec.get("id")) for spec in accepted_specs]
                contract_repair.update({"applied": bool(accepted), "repaired_raw_step_ids": list(raw_step_ids),
                                        "repaired_validation_diagnostics": deepcopy(validation_diagnostics)})
        elif domain == "orders":
            accepted, rejected = _validate_orders_plan_step_ids(
                raw_step_ids,
                state.goal,
                max_steps,
            )
        else:
            accepted, rejected = _validate_domain_plan_step_ids(
                domain,
                raw_step_ids,
                state.goal,
                max_steps,
            )
    except Exception as exc:
        replans.append(
            {
                "failed_step_id": _compact_text(failed_step.step_id),
                "accepted_step_ids": [],
                "rejected_step_ids": [],
                "planner_error": _compact_text(exc),
                "contract_repair": contract_repair,
                "applied": False,
            }
        )
        active_entities["replans"] = replans
        state.active_entities = active_entities
        state.touch()
        return False

    replacement_ids = [
        step_id
        for step_id in accepted
        if step_id not in completed_ids and step_id != failed_id
    ]
    rejected_ids = list(dict.fromkeys([*rejected, *[step_id for step_id in accepted if step_id not in replacement_ids]]))
    replan_row = {
        "failed_step_id": failed_id,
        "raw_step_ids": raw_step_ids,
        "accepted_step_ids": replacement_ids,
        "step_specs": [
            dict(spec)
            for spec in accepted_specs
            if _compact_text(spec.get("id")) in replacement_ids
        ],
        "rejected_step_ids": rejected_ids,
        "validation_diagnostics": validation_diagnostics,
        "contract_repair": contract_repair,
        "reason": _compact_text(payload.get("reason")) if isinstance(payload, dict) else "",
        "applied": bool(replacement_ids),
    }
    replans.append(replan_row)
    active_entities["replans"] = replans
    state.active_entities = active_entities
    if not replacement_ids:
        state.touch()
        return False

    next_index = max([step.index for step in [*state.completed_steps, *state.remaining_steps]] or [0]) + 1
    replacement_spec_by_id = {
        _compact_text(spec.get("id")): dict(spec)
        for spec in accepted_specs
        if _compact_text(spec.get("id")) in replacement_ids
    }
    replacement_steps: list[AgentTaskStep] = []
    for offset, step_id in enumerate(replacement_ids):
        spec = replacement_spec_by_id.get(step_id) or {}
        prompt = (
            _compact_text(spec.get("objective"))
            or _task_step_prompt(state.active_domain, step_id, state.goal)
            or _compact_text(state.goal)
        )
        operation_id = _compact_text(spec.get("operation_id"))
        replacement_steps.append(
            AgentTaskStep(
                index=next_index + offset,
                step_id=step_id,
                prompt=prompt,
                objective=prompt,
                depends_on=[
                    _compact_text(value)
                    for value in list(spec.get("depends_on") or [])
                    if _compact_text(value)
                ],
                operation_candidates=[operation_id] if operation_id else [],
                operation_domain=_compact_text(spec.get("operation_domain")).casefold(),
                arguments=dict(spec.get("arguments") or {}),
                expected_evidence=[
                    _compact_text(value)
                    for value in list(spec.get("expected_evidence") or [])
                    if _compact_text(value)
                ],
            )
        )
    state.remaining_steps = replacement_steps
    failed_step.result_data["replan_status"] = "superseded"
    failed_step.result_data["replacement_step_ids"] = list(replacement_ids)
    failed_step.verification_status = "superseded"
    _sync_goal_plan_step(state, failed_step)
    state.revise_goal_plan(
        replacement_steps,
        failed_step_id=failed_id,
        reason=_compact_text(payload.get("reason"))
        if isinstance(payload, dict)
        else "",
    )
    state.touch()
    return True


def _goal_evaluation_prompt(
    state: AgentSessionState,
    step: AgentTaskStep,
    observation: Observation,
    *,
    operation_candidates: dict[str, Any],
    max_steps: int,
) -> str:
    from AI.processors.semantic_verifier import _prepare_input_evidence
    completed: list[dict[str, Any]] = []
    for candidate in state.completed_steps:
        result_data = (
            dict(candidate.result_data or {})
            if isinstance(candidate.result_data, dict)
            else {}
        )
        tool_result = (
            dict(result_data.get("tool_result") or {})
            if isinstance(result_data.get("tool_result"), dict)
            else {}
        )
        nonempty_fields = sorted(
            _compact_text(key)
            for key, value in tool_result.items()
            if _compact_text(key)
            and _evidence_shape(value, found=True).get("present") is True
        )
        completed.append(
            {
                "id": _compact_text(candidate.step_id),
                "operation_ids": [
                    _compact_text(value)
                    for value in list(candidate.tool_names or [])
                    if _compact_text(value)
                ],
                "status": _compact_text(candidate.status),
                "verification_status": _compact_text(
                    candidate.verification_status
                ),
                "result_fields": sorted(
                    _compact_text(key)
                    for key in tool_result
                    if _compact_text(key)
                ),
                "nonempty_result_fields": nonempty_fields,
                "read_scope": {key: deepcopy(tool_result[key]) for key in (
                    "period", "period_label", "start_ms", "end_ms", "start_date", "end_date", "currency", "currencies",
                    "account_scopes", "environment_by_account", "requested_api_account_ids", "data_coverage",
                ) if key in tool_result},
            }
        )
    remaining = [
        {
            "id": candidate.step_id,
            "operation_id": (
                candidate.operation_candidates[0]
                if candidate.operation_candidates
                else ""
            ),
            "objective": candidate.objective or candidate.prompt,
            "depends_on": list(candidate.depends_on),
            "expected_evidence": list(candidate.expected_evidence),
            "arguments": _prepare_input_evidence(state, candidate),
        }
        for candidate in state.remaining_steps
    ]
    catalog_lines = []
    for operation_id, tool in operation_candidates.items():
        properties = (
            dict((tool.parameters or {}).get("properties") or {})
            if isinstance(tool.parameters, dict)
            else {}
        )
        required = [
            _compact_text(value)
            for value in list((tool.parameters or {}).get("required") or [])
            if _compact_text(value)
        ] if isinstance(tool.parameters, dict) else []
        catalog_lines.append(
            f"- {operation_id}; effect="
            f"{'write_prepare' if bool(tool.requires_approval or tool.action_type != 'read') else 'read'}; "
            f"args={','.join(properties)}; required={','.join(required)}; "
            f"description={_compact_text(tool.description)[:1000]}; "
            f"input_schema={json.dumps(tool.parameters or {}, ensure_ascii=False, sort_keys=True)}; "
            f"{_tool_source_contract(tool)}"
        )
    observation_payload = observation.to_dict()
    ref_rows = [
        dict(row)
        for row in list(observation_payload.get("record_refs") or [])
        if isinstance(row, dict)
    ]
    observed_tool = operation_candidates.get(
        _compact_text(observation_payload.get("operation_name"))
    )
    observed_effect = (
        "write_prepare"
        if observed_tool is not None
        and bool(
            getattr(observed_tool, "requires_approval", False)
            or getattr(observed_tool, "action_type", "read") != "read"
        )
        else "read"
    )
    expected_evidence_status = _expected_evidence_status(step, observation)
    compact_observation = {
        "observation_id": _compact_text(observation_payload.get("observation_id")),
        "domain": _compact_text(observation_payload.get("domain")),
        "operation_name": _compact_text(observation_payload.get("operation_name")),
        "success": bool(observation_payload.get("success")),
        "effect": observed_effect,
        "record_count": len(ref_rows),
        "record_identity_count": sum(
            1 for row in ref_rows if _compact_text(row.get("record_id"))
        ),
        "record_types": sorted(
            {
                _compact_text(row.get("record_type"))
                for row in ref_rows
                if _compact_text(row.get("record_type"))
            }
        ),
        "record_ref_fields": sorted(
            {
                _compact_text(key)
                for row in ref_rows
                for key in row
                if _compact_text(key)
            }
        ),
        "expected_evidence_status": expected_evidence_status,
        "accounts": sorted(
            {
                _compact_text(row.get("account"))
                for row in ref_rows
                if _compact_text(row.get("account"))
            }
        ),
        "environments": sorted(
            {
                _compact_text(row.get("environment"))
                for row in ref_rows
                if _compact_text(row.get("environment"))
            }
        ),
        "facts": dict(observation_payload.get("facts") or {}),
        "aggregates": dict(observation_payload.get("aggregates") or {}),
        "source": _compact_text(observation_payload.get("source")),
    }
    active_turn_interpretation = (
        dict((state.active_entities or {}).get("turn_interpretation") or {})
        if isinstance(
            (state.active_entities or {}).get("turn_interpretation"),
            dict,
        )
        else {}
    )
    active_semantic_contract = (
        dict(active_turn_interpretation.get("semantic_contract") or {})
        if isinstance(
            active_turn_interpretation.get("semantic_contract"),
            dict,
        )
        else {}
    )
    return (
        "GoalPlan observation degerlendirmesi yap. Hedefi ve typed observation'i karsilastir.\n"
        "Yalniz tek JSON nesnesi dondur; Markdown veya aciklama ekleme. "
        "Sozlesme: {\"decision\":\"continue|complete|replan|clarify\","
        "\"reason\":\"kisa gerekce\",\"clarification\":\"\",\"steps\":[]}.\n"
        "Karar: continue mevcut plani surdurur; complete yalniz kalan zorunlu adim yoksa; "
        "replan yeni atomic step graph'i verir; clarify gercekten eksik kullanici bilgisi ister.\n"
        "Kalan plan arguments alanindaki typed $from_step baglari gercek argumanlardir; "
        "bagli artifact_id'yi eksik sayma. Tamamlanan agent.delegate receipt'indeki "
        "tool_result.artifact_refs[0].artifact_id yolunu typed nesneyle bagla; "
        "literal artifact kimligi uydurma veya baglama icin yeni alt gorev acma.\n"
        "Kalan plan bos olsa bile kullanici hedefi henuz bitmediyse replan ile yeni atomic "
        "adimlar ver; continue bos planda ilerleyemez ve complete yerine sayilmaz.\n"
        "expected_evidence_status icinde observed=true olan bos liste/sifir degeri de "
        "authoritative bir okumadir; absent/null kanitla ayni sey degildir. "
        "present=true olan kanit degerleri privacy icin "
        "gizlenmis olsa bile gercekte mevcuttur; bunlari eksik sayma veya ayni kaniti "
        "yeniden almak icin replan yapma. record_identity_count kayit kimligi alanlarinin "
        "mevcut sayisidir, yalniz aggregate count degildir.\n"
        "Write_prepare yalniz hedefte acik mutation niyeti varsa secilir ve execute etmez.\n"
        "Read operation observation'i mutation sayma veya reason alaninda mutation niyeti uydurma.\n"
        "Completed observed/verified operation'lar calismistir; result_fields/nonempty_result_fields gizlenen degerlerin semasidir. "
        "Bunlari eksik sayma veya farkli metrikle ikame etme.\n"
        "Replan secersen completed/failed/skipped step id'lerini yeniden kullanma; henuz calismamis pending step id'leri ayni node icin korunabilir. "
        "exact operation_id, typed arguments, depends_on, objective ve expected_evidence ver; "
        "typed arguments'i arguments_json alaninda gecerli JSON object string'i olarak kodla.\n"
        "Replan mevcut kalan graph'in tamamini degistirir; typed semantic contract icindeki "
        "metric_requirements boyutlarinin tamamini completed operation kaniti + yeni step'lerle "
        "korumalisin. Bir urun satirinin gross_amount degeri toplam ciro kaniti degildir.\n"
        "expected_evidence yalniz output_schema'daki exact property adlaridir; sema anahtari/aciklamasi degildir. "
        "Her $from_step icin exact depends_on ekle; arguments_json operation'in kendi input semasina uymali.\n"
        "Yeni arac/schema gerekiyorsa operations.discover ile katalog kesfi yap; katalog kesfi "
        "kullanici hedefinin tamamlanma kaniti degildir. reports.build_snapshot ve analysis.calculate "
        "sources.result alanlari onceki completed read step'in tam tool_result ciktilarina exact "
        "{$from_step:step_id,path:tool_result} baglanir; literal gozlem uydurma. Ertelenmis hesap "
        "obligation'i ham okumalarla kapanmaz; gerekli operator, metrik, birim ve kaynak kapsamini "
        "saglayan analysis.calculate verified receipt gerektirir. onceki donem icin offset uydurma; "
        "istenen es sureli current/prior donemlerin start_date/end_date alanlarini acik sec.\n"
        f"Current local date/time: {datetime.now().astimezone().isoformat()}\n"
        f"Kalan toplam calisma butcesi: en fazla {max(0, int(max_steps))} yeni step.\n"
        f"Hedef: {_compact_text(state.goal)}\n"
        f"Typed semantic contract: {json.dumps(active_semantic_contract, ensure_ascii=False, sort_keys=True)}\n"
        f"Unmet goal obligations: {json.dumps(_unmet_goal_obligations(state), ensure_ascii=False)}\n"
        f"Calculation goal verification: {json.dumps((state.active_entities or {}).get('calculation_goal_verification') or {}, ensure_ascii=False)}\n"
        f"Tamamlanan step: {_compact_text(step.step_id)}\n"
        f"Reserved immutable step IDs (cannot reuse): {json.dumps(sorted(_nonreplaceable_plan_step_ids(state)))}\n"
        f"Observation: {json.dumps(compact_observation, ensure_ascii=False, sort_keys=True)}\n"
        f"Tamamlanan plan kaniti: {json.dumps(completed, ensure_ascii=False, sort_keys=True)}\n"
        f"Authoritative completed source paths: {json.dumps(_replan_completed_source_evidence(state), ensure_ascii=False, sort_keys=True)}\n"
        f"Dogrulanmis gozlem baglami: {json.dumps(_safe_existing_observation_context(state), ensure_ascii=False, sort_keys=True)}\n"
        f"Kalan plan: {json.dumps(remaining, ensure_ascii=False, sort_keys=True)}\n"
        + ("Existing source reference (DATA): " + json.dumps(existing_source_reference_context(state), ensure_ascii=False) + "\n"
           if existing_source_reference_context(state) else "")
        +
        "Atomic operation katalogu:\n"
        + "\n".join(catalog_lines)
    )


def _evidence_shape(value: Any, *, found: bool) -> dict[str, Any]:
    if not found or value is None:
        return {"present": False, "observed": False, "value_type": "missing", "count": 0}
    if isinstance(value, (list, tuple, set)):
        return {
            "present": len(value) > 0,
            "observed": True,
            "value_type": "array",
            "count": len(value),
        }
    if isinstance(value, dict):
        return {
            "present": len(value) > 0,
            "observed": True,
            "value_type": "object",
            "count": len(value),
        }
    if isinstance(value, str):
        return {
            "present": bool(value.strip()),
            "observed": bool(value.strip()),
            "value_type": "string",
            "count": 1 if value.strip() else 0,
        }
    return {"present": True, "observed": True, "value_type": type(value).__name__, "count": 1}


def _find_evidence_shape(payload: Any, evidence_name: str) -> dict[str, Any]:
    """Describe evidence presence without exposing its value to the evaluator."""
    target = _compact_text(evidence_name).split(".")[-1]
    if not target:
        return _evidence_shape(None, found=False)
    aliases = {
        "item": {"item", "items", "product_name", "product_names"},
        "quantity": {"quantity", "qty", "total_quantity", "item_quantity"},
        "amount": {
            "amount",
            "total_price",
            "total_amount",
            "gross_amount",
            "estimated_revenue",
            "line_total",
        },
        "currency": {
            "currency",
            "currency_code",
            "currencies",
        },
        "date": {
            "date",
            "order_date",
            "order_date_ms",
            "created_at",
            "created_at_ms",
        },
        "customer_name": {
            "customer_name",
            "customer",
            "buyer",
            "recipient",
        },
        "cargo": {
            "cargo",
            "cargo_provider",
            "cargo_provider_name",
        },
        "tracking_number": {
            "tracking_number",
            "cargo_tracking_number",
            "cargo_sender_number",
        },
        "store": {
            "store",
            "store_name",
        },
    }
    target_keys = aliases.get(target, {target})
    stack = [payload]
    visited = 0
    best = _evidence_shape(None, found=False)
    while stack and visited < 1024:
        current = stack.pop()
        visited += 1
        if isinstance(current, dict):
            for key, value in current.items():
                if _compact_text(key) in target_keys:
                    candidate = _evidence_shape(value, found=True)
                    if (
                        candidate.get("present") is True
                        or candidate.get("observed") is True
                        and best.get("observed") is not True
                        or int(candidate.get("count") or 0)
                        > int(best.get("count") or 0)
                    ):
                        best = candidate
                if isinstance(value, (dict, list, tuple)):
                    stack.append(value)
        elif isinstance(current, (list, tuple)):
            stack.extend(current)
    return best


def _expected_evidence_status(
    step: AgentTaskStep,
    observation: Observation,
) -> dict[str, dict[str, Any]]:
    sources = {
        "step_result": dict(step.result_data or {}),
        "observation": observation.to_dict(),
    }
    status: dict[str, dict[str, Any]] = {}
    for evidence_name in list(step.expected_evidence or []):
        name = _compact_text(evidence_name)
        if not name:
            continue
        candidates = [
            (source_name, _find_evidence_shape(payload, name))
            for source_name, payload in sources.items()
        ]
        source_name, shape = max(
            candidates,
            key=lambda item: (
                item[1].get("present") is True,
                item[1].get("observed") is True,
                int(item[1].get("count") or 0),
            ),
        )
        status[name] = {
            **shape,
            "source": source_name if shape.get("observed") is True else "",
        }
    return status


def _remaining_task_step_budget(state: AgentSessionState, fallback: int) -> int:
    budget = (state.active_entities or {}).get("execution_budget")
    if not isinstance(budget, dict):
        return max(0, int(fallback))
    return max(0, int(budget.get("max_steps") or 0) - int(budget.get("started_steps") or 0))


def _reserve_task_provider_budget(state: AgentSessionState, planner_client: ChatClient | None) -> None:
    from AI.processors.child_task_runtime import current_child_policy
    if current_child_policy() is not None or state.active_entities.get("child_delegation_policy"):
        return  # Children share the parent's deadline without extending it.
    reserve = getattr(planner_client, "reserve_task_budget", None)
    remaining = _remaining_task_step_budget(state, len(state.remaining_steps))
    if callable(reserve) and remaining > 0:
        reserve(max_steps=min(64, remaining))


def _task_replan_count(state: AgentSessionState) -> int:
    active = state.active_entities or {}
    return sum(
        bool(row.get("applied"))
        for row in list(active.get("replans") or [])
        if isinstance(row, dict)
    ) + sum(
        bool(row.get("applied")) and row.get("decision") == "replan"
        for row in list(active.get("goal_evaluations") or [])
        if isinstance(row, dict)
    ) + int(dict(active.get("execution_budget") or {}).get("reserved_child_replans") or 0)


def _comparable_read_arguments(arguments: dict[str, Any], tool: Any, semantic_contract: dict[str, Any]) -> dict[str, Any]:
    properties = dict((getattr(tool, "parameters", {}) or {}).get("properties") or {})
    effective = {name: deepcopy(schema["default"]) for name, schema in properties.items()
                 if isinstance(schema, dict) and "default" in schema}
    effective.update(arguments)
    if "period" in properties and "period" not in arguments and semantic_contract.get("period"):
        effective["period"] = semantic_contract["period"]
    return {key: value for key, value in effective.items() if value is not None and value != "" and value != [] and value != {}}


def _unmet_goal_obligations(state: AgentSessionState) -> list[str]:
    """Readiness deferral cannot erase a requested calculation from completion."""
    active = state.active_entities or {}
    interpretation = active.get("turn_interpretation") or {}
    delivery_problems = []
    artifact_delivery_requested = (
        interpretation.get("mode") in {"act", "correct"}
        and interpretation.get("operation_policy", "allow_new_operations") != "existing_observations_only"
        and "artifact" in set([*list(interpretation.get("requested_fields") or []),
                               *list(interpretation.get("direct_output_fields") or [])])
    )
    if artifact_delivery_requested:
        from AI.processors.tools import available_tools
        registry = available_tools()
        prepared_actions = []
        for step in state.completed_steps:
            if step.status != "completed" or step.verification_status not in {"observed", "verified"} or len(step.tool_names) != 1:
                continue
            tool = registry.get(step.tool_names[0])
            if tool is None or not tool.requires_approval or tool.action_type != "prepare_write":
                continue
            result = (step.result_data or {}).get("tool_result") or {}
            action = result.get("action") if isinstance(result, dict) else None
            if isinstance(action, dict) and action.get("action_id"):
                prepared_actions.append(action["action_id"])
        active["artifact_delivery_obligation"] = {"fulfilled": bool(prepared_actions),
            "prepared_action_ids": prepared_actions,
            "boundary": "A snapshot or successful read alone does not deliver an approval-required artifact."}
        if not prepared_actions:
            delivery_problems.append("requested_artifact_preparation_missing")
    contract = interpretation.get("semantic_contract") or {}
    deferred = contract.get("deferred_calculation") or {}
    if not isinstance(deferred, dict) or not deferred:
        return delivery_problems
    expected = list(deferred.get("expected_calculations") or [])
    required = max(1, int(deferred.get("required_calculation_count") or 1))
    from AI.processors.observation_analysis_evidence import verified_observation_calculations
    from AI.processors.semantic_verifier import calculation_goal_verification_fingerprint
    verified = verified_observation_calculations(state)
    semantic_receipt = active.get("calculation_goal_verification") or {}
    semantic_allowed = (
        semantic_receipt.get("allowed") is True
        and semantic_receipt.get("evidence_fingerprint") == calculation_goal_verification_fingerprint(state, verified)
    )
    accepted_hashes = set(semantic_receipt.get("accepted_evidence_hashes") or []) if semantic_allowed else set()
    matched = []
    for obligation in expected:
        for index, row in enumerate(verified):
            if (index in matched or row.get("evidence_hash") not in accepted_hashes
                    or row.get("operator") != obligation.get("operator")
                    or obligation.get("result_kind") and row.get("result_kind") != obligation.get("result_kind")):
                continue
            operand_refs = list(obligation.get("operand_refs") or [])
            receipts = list(row.get("operand_receipts") or [])
            if not receipts or operand_refs and len(operand_refs) != len(receipts):
                continue
            matches = True
            for ref, receipt in zip(operand_refs, receipts):
                metric = _DERIVED_CALCULATION_OPERAND_REQUIREMENTS.get(ref)
                keys = order_metric_evidence_keys(metric, receipt.get("operation_id")) if metric else ()
                path = _compact_text(receipt.get("path")).lstrip("/")
                field = re.split(r"[./\[]", path)[0]
                if not keys or field not in keys:
                    matches = False
                    break
            if matches:
                matched.append(index)
                break
    if not expected:
        # A new read goal can declare arithmetic without guessing exact
        # operands before data exists. Independent proof and the bound
        # semantic verdict still decide whether these are the requested
        # calculations; count alone cannot satisfy the goal.
        if semantic_allowed and deferred.get("cardinality_authority") == "provisional_initial_interpretation":
            required = max(1, int(semantic_receipt.get("requested_calculation_count") or required))
            required_kinds = list(semantic_receipt.get("requested_result_kinds") or [])
        else:
            required_kinds = list(deferred.get("required_result_kinds") or [])
        for index, candidate in enumerate(verified):
            if candidate.get("evidence_hash") not in accepted_hashes or not candidate.get("operand_receipts"):
                continue
            if required_kinds:
                if candidate.get("result_kind") not in required_kinds:
                    continue
                required_kinds.remove(candidate.get("result_kind"))
            matched.append(index)
        fulfilled = semantic_allowed and len(matched) >= required and not required_kinds
    else:
        fulfilled = semantic_allowed and len(matched) == len(expected) and len(matched) >= required
    if deferred.get("comparison_required") is True:
        def operand_pair(row):
            return [
                (receipt.get("operation_id"), receipt.get("path"), receipt.get("source_result_hash"))
                for receipt in list(row.get("operand_receipts") or [])
            ]
        verified_relation = any(
            verified[index].get("result_kind") == "boolean"
            or verified[index].get("comparison_verified") is True
            for index in matched
        )
        if not verified_relation:
            required_operators = {
                obligation.get("comparison_operator")
                for obligation in expected if obligation.get("comparison_operator")
            }
            verified_relation = bool(required_operators) and all(
                any(
                    row.get("result_kind") == "boolean" and row.get("operator") == operator
                    and row.get("evidence_hash") in accepted_hashes
                    and any(operand_pair(row) == operand_pair(verified[index]) for index in matched)
                    for row in verified
                )
                for operator in required_operators
            )
        if not expected:
            verified_relation = any(verified[index].get("comparison_verified") is True for index in matched)
            if (deferred.get("cardinality_authority") == "provisional_initial_interpretation"
                    and "boolean" not in list(semantic_receipt.get("requested_result_kinds") or [])
                    and "boolean" not in list(deferred.get("required_result_kinds") or [])):
                # A source-bound difference or ratio can be the requested
                # comparison. Its independently checked semantic receipt still
                # owns the exact goal, periods, units and accepted evidence.
                verified_relation = verified_relation or any(
                    verified[index].get("operator") in {"subtract", "divide", "percentage"}
                    and len(set(operand_pair(verified[index]))) >= 2
                    for index in matched
                )
        fulfilled = fulfilled and verified_relation and semantic_receipt.get("comparison_satisfied") is True
    active["goal_obligations"] = [{
        "kind": "source_bound_calculation", "fulfilled": fulfilled,
        "required_calculation_count": required, "verified_calculation_count": len(matched),
        "evidence_hashes": [verified[index]["evidence_hash"] for index in matched],
        "semantic_verification_allowed": semantic_allowed,
        "semantic_reason_codes": list(semantic_receipt.get("reason_codes") or []),
    }]
    state.active_entities = active
    return delivery_problems + ([] if fulfilled else ["deferred_source_bound_calculation_missing"])


def _stop_incomplete_task(state: AgentSessionState, reason: str) -> None:
    """Keep a stopped workflow distinct from a verified completed goal."""
    answer = (
        "Görev tamamlanmadı; ayrılan adım bütçesi doldu. Doğrulanmış sonuçlar korunuyor."
        if reason == "execution_budget_exhausted"
        else "Görevin tamamlandığını doğrulayamadım; güvenli devam adımı kurulamadı. "
        "Elde edilen sonuçlar korunuyor."
    )
    if reason == "no_search_results":
        answer = (
            "Web araması tamamlandı ancak açılıp doğrulanabilecek bir kaynak bulunamadı. "
            "Arama sonucu snippet'leri kanıt sayılmadığı için doğrulanmamış bir bulgu üretmedim. "
            "Araştırma hedefi tamamlanmadı."
        )
    elif reason == "deferred_source_bound_calculation_missing":
        answer = (
            "İstenen hesaplamanın kullanıcı hedefini ve kaynak kapsamını karşıladığını doğrulayamadım. "
            "Görev tamamlanmadı; elde edilen gözlemler korunuyor."
        )
    elif reason == "requested_artifact_preparation_missing":
        answer = (
            "İstenen dosya için doğrulanmış bir onay teklifi hazırlanamadı. "
            "Görev tamamlanmadı; elde edilen gözlemler korunuyor."
        )
    state.status = "failed"
    state.set_goal_plan_status("failed")
    state.active_entities["goal_progress"] = {
        "complete": False,
        "reason": _compact_text(reason),
        "answer": answer,
        "unmet_goal_obligations": _unmet_goal_obligations(state),
    }
    state.active_entities["final_answer"] = answer
    state.active_entities["response_synthesis"] = {
        "candidate_received": False,
        "candidate_accepted": False,
        "final_projection_verified": False,
        "final_source": "typed_goal_incomplete",
    }
    state.memory_summary = answer
    state.touch()


def _reevaluate_goal_after_observation(
    state: AgentSessionState,
    step: AgentTaskStep,
    observation: Observation,
    *,
    planner_client: ChatClient | None,
    max_steps: int,
    max_replans: int,
) -> dict[str, Any]:
    interpretation = (state.active_entities or {}).get("turn_interpretation") or {}
    if (observation.success
            and (observation.operation_name == "analysis.calculate"
                 or state.active_entities.get("calculation_goal_verification"))
            and (interpretation.get("semantic_contract") or {}).get("deferred_calculation")):
        from AI.processors.semantic_verifier import verify_calculation_goal_semantics

        verify_calculation_goal_semantics(state, verifier_client=planner_client)
    active_entities = state.active_entities if isinstance(state.active_entities, dict) else {}
    evaluations = [
        dict(row)
        for row in list(active_entities.get("goal_evaluations") or [])
        if isinstance(row, dict)
    ]
    expected_evidence_status = _expected_evidence_status(step, observation)
    row: dict[str, Any] = {
        "observation_id": observation.observation_id,
        "step_id": _compact_text(step.step_id),
        "operation_id": _compact_text(observation.operation_name),
        "decision": "continue",
        "applied": False,
        "model_invoked": False,
        "expected_evidence_status": expected_evidence_status,
    }
    domain = _compact_text(state.active_domain).casefold()
    if domain == "web" and not state.remaining_steps and observation.success:
        required_operations = [
            _compact_text(spec.get("operation_id"))
            for spec in _web_template_step_specs(state.goal)
            if _compact_text(spec.get("operation_id"))
        ]
        completed_operations = Counter(
            _compact_text(tool_name)
            for candidate in state.completed_steps
            if candidate.status == "completed"
            for tool_name in list(candidate.tool_names or [])
            if _compact_text(tool_name)
        )
        required_counts = Counter(required_operations)
        if required_counts and all(
            completed_operations[operation_id] >= count
            for operation_id, count in required_counts.items()
        ):
            row.update(
                {
                    "decision": "complete",
                    "applied": True,
                    "model_invoked": False,
                    "reason": "deterministic_required_web_graph_completed",
                    "required_operation_ids": required_operations,
                }
            )
            evaluations.append(row)
            active_entities["goal_evaluations"] = evaluations
            state.active_entities = active_entities
            state.touch()
            return row
    active_plan = state.active_goal_plan()
    authored_plan_sources = {
        "llm_direct",
        "llm_direct_repaired",
        "llm_canonical_resolved",
    }
    observed_operation_id = _compact_text(observation.operation_name)
    declared_operation_ids = {
        _compact_text(value)
        for value in list(step.operation_candidates or [])
        if _compact_text(value)
    }
    expected_evidence_satisfied = bool(expected_evidence_status) and all(
        candidate.get("observed") is True
        for candidate in expected_evidence_status.values()
    )
    observed_tool = None
    tool_registry: dict[str, Any] = {}
    if observed_operation_id:
        from AI.processors.tools import available_tools

        tool_registry = available_tools()
        observed_tool = tool_registry.get(observed_operation_id)
    remaining_steps_are_independent = bool(state.remaining_steps) and all(
        _compact_text(step.step_id)
        not in {
            _compact_text(value)
            for value in list(candidate.depends_on or [])
            if _compact_text(value)
        }
        for candidate in state.remaining_steps
    )
    active_turn_interpretation = (
        dict(active_entities.get("turn_interpretation") or {})
        if isinstance(active_entities.get("turn_interpretation"), dict)
        else {}
    )
    active_task_plan = (
        dict(active_entities.get("task_plan") or {})
        if isinstance(active_entities.get("task_plan"), dict)
        else {}
    )
    remaining_typed_read_chain = bool(
        state.remaining_steps
        and int(getattr(active_plan, "revision", 0) or 0) == 1
        and active_turn_interpretation.get("valid") is True
        and isinstance(
            active_turn_interpretation.get("semantic_contract"),
            dict,
        )
        and bool(active_turn_interpretation.get("semantic_contract"))
        and active_task_plan.get("direct_plan_compiled") is True
        and active_task_plan.get("projection_contract_coherent") is True
        and active_task_plan.get("deterministic_business_steps_inserted")
        is False
        and not list(active_task_plan.get("missing_metric_requirements") or [])
        and not list(active_task_plan.get("semantic_missing_step_ids") or [])
        and all(
            list(candidate.operation_candidates or [])
            and all(
                operation_id in tool_registry
                and not bool(
                    getattr(
                        tool_registry[operation_id],
                        "requires_approval",
                        False,
                    )
                    or getattr(
                        tool_registry[operation_id],
                        "action_type",
                        "read",
                    )
                    != "read"
                )
                for operation_id in {
                    _compact_text(value)
                    for value in list(
                        candidate.operation_candidates or []
                    )
                    if _compact_text(value)
                }
            )
            for candidate in state.remaining_steps
        )
    )
    terminal_typed_plan_coverage = bool(
        not state.remaining_steps
        and not active_task_plan.get("discovery_only_plan")
        and not _unmet_goal_obligations(state)
        and int(getattr(active_plan, "revision", 0) or 0) == 1
        and active_turn_interpretation.get("valid") is True
        and isinstance(
            active_turn_interpretation.get("semantic_contract"),
            dict,
        )
        and bool(active_turn_interpretation.get("semantic_contract"))
        and active_task_plan.get("direct_plan_compiled") is True
        and active_task_plan.get("projection_contract_coherent") is True
        and active_task_plan.get("deterministic_business_steps_inserted")
        is False
        and observed_operation_id
        in {
            _compact_text(value)
            for value in list(
                active_task_plan.get("compiled_operation_ids") or []
            )
            if _compact_text(value)
        }
        and not list(active_task_plan.get("missing_metric_requirements") or [])
        and not list(active_task_plan.get("semantic_missing_step_ids") or [])
    )
    terminal_model_authored_read_observation = terminal_typed_plan_coverage
    verified_model_authored_read_observation = bool(
        observation.success
        and active_plan is not None
        and _compact_text(active_plan.source) in authored_plan_sources
        and observed_operation_id in declared_operation_ids
        and expected_evidence_satisfied
        and (
            terminal_model_authored_read_observation
            or remaining_steps_are_independent
            or remaining_typed_read_chain
        )
        and observed_tool is not None
        and not bool(
            getattr(observed_tool, "requires_approval", False)
            or getattr(observed_tool, "action_type", "read") != "read"
        )
        and _compact_text(step.verification_status).casefold()
        in {"observed", "verified"}
    )
    if verified_model_authored_read_observation:
        terminal = bool(terminal_model_authored_read_observation)
        row.update(
            {
                "decision": "complete" if terminal else "continue",
                "applied": terminal,
                "model_invoked": False,
                "reason": (
                    "verified_expected_evidence_model_authored_plan_completed"
                    if terminal
                    else "verified_expected_evidence_typed_read_chain_continues"
                    if remaining_typed_read_chain
                    and not remaining_steps_are_independent
                    else "verified_expected_evidence_independent_plan_continues"
                ),
                "deterministic_progress": True,
                "plan_source": _compact_text(active_plan.source),
            }
        )
        evaluations.append(row)
        active_entities["goal_evaluations"] = evaluations
        state.active_entities = active_entities
        state.touch()
        return row
    if planner_client is None:
        row["reason"] = "planner_unavailable_existing_plan_continues"
        evaluations.append(row)
        active_entities["goal_evaluations"] = evaluations
        state.active_entities = active_entities
        state.touch()
        return row

    row["model_invoked"] = True
    read_domains = _active_business_read_domains(state)
    operation_candidates = _planner_operation_candidates(
        domain,
        f"{state.goal} {step.objective or step.prompt}",
        limit=max(12, max_steps * 3),
        read_domains=read_domains,
    )
    operation_candidates = _continuation_operation_candidates(state, operation_candidates)
    active_turn = (
        dict((state.active_entities or {}).get("turn_interpretation") or {})
        if isinstance(
            (state.active_entities or {}).get("turn_interpretation"),
            dict,
        )
        else {}
    )
    active_contract = (
        dict(active_turn.get("semantic_contract") or {})
        if isinstance(active_turn.get("semantic_contract"), dict)
        else {}
    )
    required_metric_candidate_ids = [
        operation_id
        for metric_id in normalize_order_metric_requirements(
            active_contract.get("metric_requirements") or []
        )
        for operation_id in order_metric_operation_ids(metric_id)
    ]
    if required_metric_candidate_ids:
        from AI.processors.tools import available_tools

        registry = available_tools()
        for operation_id in required_metric_candidate_ids:
            tool = registry.get(operation_id)
            if (
                tool is not None
                and _compact_text(tool.domain).casefold() == domain
                and operation_id not in operation_candidates
            ):
                operation_candidates[operation_id] = tool
    try:
        payload = _extract_json_payload(
            invoke_provider_planner(
                planner_client,
                _goal_evaluation_prompt(
                    state,
                    step,
                    observation,
                    operation_candidates=operation_candidates,
                    max_steps=max_steps,
                ),
                response_schema=_GOAL_EVALUATION_RESPONSE_SCHEMA,
            )
        )
        decision = _compact_text(
            payload.get("decision") if isinstance(payload, dict) else ""
        ).casefold()
        if decision not in {"continue", "complete", "replan", "clarify"}:
            raise ValueError("goal evaluator returned an invalid decision")
        row["decision"] = decision
        row["reason"] = _compact_text(payload.get("reason"))
        evaluated_tool = operation_candidates.get(
            _compact_text(observation.operation_name)
        )
        read_only_observation = bool(
            evaluated_tool is not None
            and not bool(
                getattr(evaluated_tool, "requires_approval", False)
                or getattr(evaluated_tool, "action_type", "read") != "read"
            )
        )
        if (
            read_only_observation
            and decision == "complete"
            and observation.success
            and not state.remaining_steps
            and any(
                marker in _normalized(row["reason"])
                for marker in (
                    "mutasyon",
                    "mutation",
                    "write intent",
                    "write_prepare",
                )
            )
        ):
            row["model_reason"] = row["reason"]
            row["reason"] = "verified_read_observation_satisfies_goal"
            row["semantic_corrections"] = [
                "read_goal_mutation_rationale_removed"
            ]
        if (
            row["decision"] == "continue"
            and observation.success
            and not state.remaining_steps
        ):
            row["reason"] = "empty_plan_has_no_authorized_next_step"
    except Exception as exc:
        row["reason"] = "goal_evaluator_failed_existing_plan_continues"
        row["evaluator_error"] = _compact_text(exc)
        evaluations.append(row)
        active_entities["goal_evaluations"] = evaluations
        state.active_entities = active_entities
        state.touch()
        return row

    if row["decision"] == "clarify":
        clarification = _compact_text(payload.get("clarification"))
        if clarification:
            state.status = "needs_clarification"
            state.set_goal_plan_status("needs_clarification")
            active_entities["clarification"] = clarification
            row["clarification"] = clarification
            row["applied"] = True
    elif row["decision"] == "complete":
        if _unmet_goal_obligations(state):
            row["decision"] = "continue"
            row["reason"] = _unmet_goal_obligations(state)[0]
            row["unmet_goal_obligations"] = _unmet_goal_obligations(state)
        elif observed_operation_id in {"operations.discover", "agent.delegate"}:
            row["decision"] = "continue"
            row["reason"] = "delegation_receipt_is_not_goal_completion" if observed_operation_id == "agent.delegate" else "operation_discovery_is_not_goal_completion"
        elif expected_evidence_status and not expected_evidence_satisfied:
            row["decision"] = "continue"
            row["reason"] = "declared_completion_evidence_missing"
        elif state.remaining_steps:
            row["decision"] = "continue"
            row["reason"] = "remaining_required_steps_prevent_early_completion"
        else:
            row["applied"] = True
    elif row["decision"] == "replan":
        applied_replans = _task_replan_count(state)
        if applied_replans >= max(0, int(max_replans or 0)):
            row["decision"] = "continue"
            row["reason"] = "observation_replan_limit_reached"
        elif max_steps <= 0:
            row["decision"] = "continue"
            row["reason"] = "execution_budget_exhausted"
        else:
            raw_specs = _planner_step_specs(payload)
            plan = state.active_goal_plan()
            completed_ids = {
                _compact_text(candidate.step_id)
                for candidate in state.completed_steps
                if candidate.status == "completed" and _compact_text(candidate.step_id)
            }
            forbidden_ids = _nonreplaceable_plan_step_ids(state)
            turn_interpretation = (
                dict((state.active_entities or {}).get("turn_interpretation") or {})
                if isinstance(
                    (state.active_entities or {}).get("turn_interpretation"),
                    dict,
                )
                else {}
            )
            replan_authorization = {
                "source_policy": state_source_policy(state),
                "mode": _compact_text(
                    turn_interpretation.get("mode")
                ).casefold(),
                "intent_kind": _compact_text(
                    turn_interpretation.get("intent_kind")
                ).casefold(),
                "requested_fields": list(
                    turn_interpretation.get("requested_fields") or []
                ),
                "semantic_contract": dict(
                    turn_interpretation.get("semantic_contract") or {}
                ),
                "correction_target_present": bool(
                    turn_interpretation.get("correction_target")
                ),
            }
            validation_diagnostics: list[dict[str, Any]] = []
            accepted_specs, rejected_ids = _validate_direct_plan_specs(
                domain,
                raw_specs,
                state.goal,
                allowed_operations=operation_candidates,
                max_steps=max_steps,
                satisfied_dependency_ids=completed_ids,
                forbidden_step_ids=forbidden_ids,
                satisfied_source_operations=_completed_source_operations(state),
                authorization_context=replan_authorization,
                read_domains=read_domains,
                validation_diagnostics=validation_diagnostics,
            )
            row['validation_diagnostics'] = validation_diagnostics
            if rejected_ids and not accepted_specs:
                repair_prompt = (
                    'GoalPlan observation replan schema repair. Previous replacement graph was rejected before execution. '
                    'Return one corrected atomic graph; this is the only schema repair attempt for this observation. '
                    'Use exact completed source IDs in depends_on and typed bindings. '
                    'Use only output field names as expected_evidence, never JSON Schema keywords or descriptions.\n'
                    f'Exact validation diagnostics: {json.dumps(validation_diagnostics, ensure_ascii=False)}\n'
                    f'Rejected graph: {json.dumps(raw_specs, ensure_ascii=False)}\n'
                    + _goal_evaluation_prompt(state, step, observation,
                        operation_candidates=operation_candidates, max_steps=max_steps)
                )
                row['schema_repair'] = {'invoked': True, 'applied': False, 'initial_rejected_step_ids': list(rejected_ids)}
                try:
                    repaired = _extract_json_payload(invoke_provider_planner(planner_client, repair_prompt,
                        response_schema=_TASK_PLAN_RESPONSE_SCHEMA))
                    repaired_diagnostics: list[dict[str, Any]] = []
                    repaired_specs, repaired_rejected = _validate_direct_plan_specs(domain,
                        _planner_step_specs(repaired), state.goal, allowed_operations=operation_candidates,
                        max_steps=max_steps, satisfied_dependency_ids=completed_ids, forbidden_step_ids=forbidden_ids,
                        satisfied_source_operations=_completed_source_operations(state),
                        authorization_context=replan_authorization, read_domains=read_domains,
                        validation_diagnostics=repaired_diagnostics)
                    row['schema_repair'].update(rejected_step_ids=repaired_rejected,
                                               validation_diagnostics=repaired_diagnostics)
                    if repaired_specs and not repaired_rejected:
                        accepted_specs, rejected_ids = repaired_specs, []
                        row['schema_repair']['applied'] = True
                except Exception as error:
                    row['schema_repair']['error_type'] = type(error).__name__
            row["rejected_step_ids"] = list(rejected_ids)
            completed_operation_ids = {
                _compact_text(operation_id)
                for completed_step in state.completed_steps
                if completed_step.status == "completed"
                for operation_id in list(completed_step.tool_names or [])
                if _compact_text(operation_id)
            }
            completed_operation_ids.add(
                _compact_text(observation.operation_name)
            )
            replacement_operation_ids = {
                _compact_text(spec.get("operation_id"))
                for spec in accepted_specs
                if _compact_text(spec.get("operation_id"))
            }
            required_replan_metrics = normalize_order_metric_requirements(
                (
                    replan_authorization.get("semantic_contract") or {}
                ).get("metric_requirements")
                or []
            )
            missing_metrics_before_replan = missing_order_metric_requirements(
                required_replan_metrics,
                completed_operation_ids,
            )
            row["missing_metric_requirements_before_replan"] = list(
                missing_metrics_before_replan
            )
            redundant_metric_replan_operations = [
                _compact_text(spec.get("operation_id"))
                for spec in accepted_specs
                for operation_id in [_compact_text(spec.get("operation_id"))]
                if any(
                    order_metric_evidence_keys(metric_id, operation_id)
                    for metric_id in required_replan_metrics
                )
                and not any(
                    order_metric_evidence_keys(metric_id, operation_id)
                    for metric_id in missing_metrics_before_replan
                )
                and any(
                    candidate.status == "completed"
                    and any(
                        order_metric_evidence_keys(metric_id, completed_operation)
                        and order_metric_evidence_keys(metric_id, operation_id)
                        and _comparable_read_arguments(
                            dict(candidate.arguments or {}), tool_registry.get(completed_operation),
                            replan_authorization.get("semantic_contract") or {},
                        ) == _comparable_read_arguments(
                            dict(spec.get("arguments") or {}), tool_registry.get(operation_id),
                            replan_authorization.get("semantic_contract") or {},
                        )
                        for completed_operation in candidate.tool_names
                        for metric_id in required_replan_metrics
                    )
                    for candidate in state.completed_steps
                )
            ]
            row["redundant_metric_replan_operations"] = list(
                redundant_metric_replan_operations
            )
            missing_replan_metrics = missing_order_metric_requirements(
                required_replan_metrics,
                completed_operation_ids | replacement_operation_ids,
            )
            row["missing_metric_requirements"] = list(
                missing_replan_metrics
            )
            if missing_replan_metrics:
                row["rejected_reason_codes"] = [
                    f"typed_read_metric_requirement_missing:{metric_id}"
                    for metric_id in missing_replan_metrics
                ]
                accepted_specs = []
            if redundant_metric_replan_operations:
                row["rejected_reason_codes"] = list(
                    dict.fromkeys(
                        [
                            *list(row.get("rejected_reason_codes") or []),
                            *[
                                "redundant_metric_replan_operation:"
                                f"{operation_id}"
                                for operation_id in (
                                    redundant_metric_replan_operations
                                )
                            ],
                        ]
                    )
                )
                accepted_specs = []
            if accepted_specs:
                next_index = max(
                    [candidate.index for candidate in [*state.completed_steps, *state.remaining_steps]]
                    or [0]
                ) + 1
                replacement_steps: list[AgentTaskStep] = []
                for offset, spec in enumerate(accepted_specs):
                    operation_id = _compact_text(spec.get("operation_id"))
                    objective = _compact_text(spec.get("objective")) or _compact_text(state.goal)
                    replacement_steps.append(
                        AgentTaskStep(
                            index=next_index + offset,
                            step_id=_compact_text(spec.get("id")),
                            prompt=objective,
                            objective=objective,
                            depends_on=list(spec.get("depends_on") or []),
                            operation_candidates=[operation_id],
                            operation_domain=_compact_text(
                                spec.get("operation_domain")
                            ).casefold(),
                            arguments=dict(spec.get("arguments") or {}),
                            expected_evidence=list(spec.get("expected_evidence") or []),
                        )
                    )
                superseded_ids = [
                    _compact_text(candidate.step_id)
                    for candidate in state.remaining_steps
                    if _compact_text(candidate.step_id)
                ]
                if plan is not None:
                    for old_step_id in superseded_ids:
                        old_step = plan.step(old_step_id)
                        if old_step is not None:
                            old_step.status = "superseded"
                            old_step.verification_status = "superseded"
                state.remaining_steps = replacement_steps
                state.revise_goal_plan(
                    replacement_steps,
                    failed_step_id=f"observation:{observation.observation_id}",
                    reason=_compact_text(row.get("reason")),
                )
                row["superseded_step_ids"] = superseded_ids
                row["replacement_step_ids"] = [
                    candidate.step_id for candidate in replacement_steps
                ]
                row["applied"] = True
            else:
                row["decision"] = "continue"
                row["reason"] = (
                    "observation_replan_rejected_metric_coverage"
                    if missing_replan_metrics
                    else "observation_replan_rejected_redundant_metric"
                    if redundant_metric_replan_operations
                    else "observation_replan_rejected_existing_plan_continues"
                )

    evaluations.append(row)
    active_entities["goal_evaluations"] = evaluations
    state.active_entities = active_entities
    state.touch()
    return row


def _task_initial_history(history: list[dict[str, str]] | None) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    for row in list(history or [])[-24:]:
        if not isinstance(row, dict):
            continue
        role = _compact_text(row.get("role"))
        content = _compact_text(row.get("content"))
        if content:
            rows.append({"role": role, "content": content})
    return rows


MAX_TYPED_CONVERSATION_TURNS = 240


def _trim_typed_conversation_state(state: AgentSessionState) -> None:
    """Bound raw conversational events without discarding typed business memory."""

    if len(state.conversation_turns) > MAX_TYPED_CONVERSATION_TURNS:
        state.conversation_turns = list(
            state.conversation_turns[-MAX_TYPED_CONVERSATION_TURNS:]
        )
    conversation_event_ids = {
        turn.turn_id for turn in state.conversation_turns
    }
    non_conversation_events = [
        event
        for event in state.state_events
        if event.event_type != "conversation_turn"
    ]
    retained_conversation_events = [
        event
        for event in state.state_events
        if event.event_type == "conversation_turn"
        and event.entity_id in conversation_event_ids
    ]
    state.state_events = [
        *non_conversation_events,
        *retained_conversation_events,
    ]
    state.touch()


def _record_assistant_task_turn(
    state: AgentSessionState,
    *,
    answer: str,
    mode: str,
) -> None:
    clean_answer = _compact_text(answer)
    if not clean_answer:
        return
    tool_names = [
        _compact_text(name)
        for step in state.completed_steps
        for name in list(step.tool_names or [])
        if _compact_text(name)
    ]
    state.record_turn(
        role="assistant",
        content=clean_answer,
        mode=_compact_text(mode) or "task",
        objective=_compact_text(state.goal),
        tool_names=list(dict.fromkeys(tool_names)),
    )
    _trim_typed_conversation_state(state)


def record_conversation_exchange(
    *,
    session_state: AgentSessionState | dict[str, Any] | None,
    user_message: str,
    assistant_message: str,
    mode: str,
    objective: str,
    active_domain: str = "general",
    tool_names: list[Any] | tuple[Any, ...] = (),
    intent_kind: str = "",
    requested_fields: list[Any] | tuple[Any, ...] = (),
    semantic_contract: dict[str, Any] | None = None,
) -> AgentSessionState:
    """Persist one visible exchange while retaining authoritative typed state."""

    state = (
        AgentSessionState.from_dict(session_state.to_dict())
        if isinstance(session_state, AgentSessionState)
        else AgentSessionState.from_dict(dict(session_state or {}))
        if isinstance(session_state, dict)
        else AgentSessionState(
            goal=_compact_text(objective) or _compact_text(user_message),
            active_domain=_compact_text(active_domain) or "general",
        )
    )
    if _compact_text(mode) in {"clarify", "clarification"}:
        # A new clarification cannot inherit the preceding business answer's
        # verification receipt. Retain observations, selections and pending actions.
        state.active_entities["response_synthesis"] = {
            "candidate_received": False,
            "candidate_accepted": False,
            "final_projection_verified": False,
            "final_source": "typed_clarification",
        }
        state.active_entities["final_answer"] = _compact_text(assistant_message)
    state.record_turn(
        role="user",
        content=_compact_text(user_message),
        mode=_compact_text(mode) or "chat",
        objective=_compact_text(objective),
        intent_kind=_compact_text(intent_kind),
        requested_fields=requested_fields,
        semantic_contract=dict(semantic_contract or {}),
    )
    state.record_turn(
        role="assistant",
        content=_compact_text(assistant_message),
        mode=_compact_text(mode) or "chat",
        objective=_compact_text(objective),
        tool_names=tool_names,
    )
    _trim_typed_conversation_state(state)
    return state


def _fresh_task_state_from_conversation(
    *,
    goal: str,
    domain: str,
    session_state: AgentSessionState | dict[str, Any] | None,
    inherit_observation_artifacts: bool = True,
    observation_artifact_ids: list[str] | None = None,
) -> AgentSessionState:
    """Start a fresh execution session while retaining typed conversation memory."""

    state = AgentSessionState(goal=_compact_text(goal), active_domain=domain)
    if session_state is None:
        return state
    try:
        previous = (
            AgentSessionState.from_dict(session_state.to_dict())
            if isinstance(session_state, AgentSessionState)
            else AgentSessionState.from_dict(dict(session_state or {}))
        )
    except (TypeError, ValueError):
        return state

    state.conversation_turns = list(
        previous.conversation_turns[-MAX_TYPED_CONVERSATION_TURNS:]
    )
    state.active_scopes = dict(previous.active_scopes)
    state.selection_snapshots = list(previous.selection_snapshots[-60:])
    state.active_selection_ids = dict(previous.active_selection_ids)
    state.analysis_contexts = list(previous.analysis_contexts[-60:])
    state.active_analysis_ids = dict(previous.active_analysis_ids)
    state.observations = list(previous.observations[-120:])
    state.memory_summary = _compact_text(previous.memory_summary)
    workspace = (previous.active_entities or {}).get("file_workspace")
    if isinstance(workspace, dict) and _compact_text(workspace.get("session_id")):
        state.active_entities["file_workspace"] = deepcopy(workspace)
    workflow = (previous.active_entities or {}).get("workflow_invocation")
    if isinstance(workflow, dict):
        state.active_entities["workflow_invocation"] = {
            key: deepcopy(workflow[key]) for key in ("workflow_id", "revision_id", "spec_hash", "fresh_model_plan_required",
                                                    "requires_current_sources", "requires_current_approval") if key in workflow
        }
    fresh_workflow = isinstance(workflow, dict) and not previous.completed_steps and workflow.get("fresh_model_plan_required") is True
    if inherit_observation_artifacts and not fresh_workflow:
        artifact_workspace = (previous.active_entities or {}).get("observation_artifacts")
        if isinstance(artifact_workspace, dict):
            from AI.processors.observation_artifacts import transfer_observation_capabilities

            selected = observation_artifact_ids if observation_artifact_ids is not None else [
                row["artifact_id"] for row in list(artifact_workspace.get("capabilities") or [])[-16:]
                if isinstance(row, dict) and isinstance(row.get("artifact_id"), str)
            ]
            try:
                transfer_observation_capabilities(previous, state, artifact_ids=selected[:16])
            except (ValueError, TypeError, KeyError, OSError, RecursionError) as exc:
                _record_observation_artifact_event(state, phase="transfer", status="unavailable", error_type=type(exc).__name__)
    prior_context = [
        dict(row.get("context") or {})
        for row in previous.authoritative_context_rows()
        if isinstance(row, dict) and isinstance(row.get("context"), dict)
    ]
    if prior_context:
        state.active_entities["prior_authoritative_context"] = prior_context
    return state


def _planner_typed_context(state: AgentSessionState) -> list[dict[str, Any]]:
    contexts: list[dict[str, Any]] = []
    current_rows = [
        dict(row.get("context") or {})
        for row in state.authoritative_context_rows()
        if isinstance(row, dict) and isinstance(row.get("context"), dict)
    ]
    prior_rows = [
        dict(row)
        for row in list((state.active_entities or {}).get("prior_authoritative_context") or [])
        if isinstance(row, dict)
    ]
    active_kinds = {
        _compact_text(row.get("kind"))
        for row in current_rows
        if _compact_text(row.get("kind"))
    }
    # Current typed entities supersede historical entities of the same kind.
    # Passing both an active order selection and an older order selection to
    # the model made a deictic follow-up nondeterministic: providers could
    # union the two scopes even though only one is authoritative now.
    prior_rows = [
        row
        for row in prior_rows
        if _compact_text(row.get("kind")) not in active_kinds
    ]
    for context in [*prior_rows, *current_rows]:
        projected = {
            key: context.get(key)
            for key in (
                "kind",
                "source_tool",
                "action_type",
                "selection_id",
                "status",
                "order_numbers",
                "claim_ids",
                "listed_count",
                "total_count",
                "selected_record_count",
                "web_observation_id",
                "url",
                "title",
                "source_domain",
                "source_class",
                "published_at",
                "accessed_at",
                "freshness",
                "trust",
                "content_hash",
                "query_fingerprint",
                "source_revision",
                "source_snapshot_hash",
                "domain",
                "population",
                "account_scopes",
                "truncated",
                "total_matching",
                "prompt_injection_detected",
                "untrusted_content",
                "source_count",
                "citations",
            )
            if context.get(key) not in (None, "", [], {})
        }
        if projected and projected not in contexts:
            contexts.append(projected)
    workspace = (state.active_entities or {}).get("file_workspace")
    if isinstance(workspace, dict):
        attachments = [
            {key: row[key] for key in ("attachment_id", "name", "format", "size_bytes", "sha256", "imported_at") if key in row}
            for row in list(workspace.get("attachments") or [])[:64]
            if isinstance(row, dict) and _compact_text(row.get("attachment_id"))
        ]
        if attachments:
            contexts.append({"kind": "file_workspace", "attachments": attachments})
    if isinstance((state.active_entities or {}).get("observation_artifacts"), dict):
        from AI.processors.observation_artifacts import observation_artifact_refs
        try:
            refs = observation_artifact_refs(state)[-16:]
            if refs:
                contexts.append({"kind": "observation_artifact_refs", "artifacts": refs})
        except (ValueError, TypeError, KeyError, OSError, RecursionError) as exc:
            _record_observation_artifact_event(state, phase="context", status="unavailable", error_type=type(exc).__name__)
    reference_context = existing_source_reference_context(state)
    if reference_context:
        contexts.append(reference_context)
    if state_source_policy(state) == EXISTING_ONLY:
        contexts.append({"kind": "source_access_policy", "source_policy": EXISTING_ONLY,
                         "instruction": "Use granted artifacts.read observations only; no fresh DB/web/file reads. "
                         "Bind the WHOLE tool_result wrapper as reports/analysis source, then use result.* rows paths. "
                         "Prepare requested output for a NEW exact approval; do not copy transcript values as source evidence."})
    return contexts[-8:]


def _task_history_identifiers(history: list[dict[str, str]] | None) -> tuple[list[str], list[str]]:
    text = "\n".join(_compact_text(row.get("content")) for row in list(history or []) if isinstance(row, dict))
    order_ids = list(
        dict.fromkeys(
            match.upper().replace("_", "-")
            for match in re.findall(r"\bORD[-_][A-Z0-9][A-Z0-9_-]*\b", text, flags=re.IGNORECASE)
        )
    )
    claim_ids = list(
        dict.fromkeys(
            match.upper().replace("_", "-")
            for match in re.findall(r"\b(?:CLAIM|CLM)[-_][A-Z0-9][A-Z0-9_-]*\b", text, flags=re.IGNORECASE)
        )
    )
    return order_ids, claim_ids


def _planner_context_from_task_history(
    history: list[dict[str, str]] | None,
) -> list[dict[str, Any]]:
    order_ids, claim_ids = _task_history_identifiers(history)
    context: dict[str, Any] = {
        "kind": "conversation_history_selection",
        "source_tool": "conversation_history",
    }
    if order_ids:
        context["order_numbers"] = order_ids[:20]
        context["selected_record_count"] = len(order_ids[:20])
    if claim_ids:
        context["claim_ids"] = claim_ids[:20]
        context["selected_record_count"] = len(claim_ids[:20])
    return [context] if len(context) > 2 else []


def _claim_id_tokens_from_text(value: Any) -> list[str]:
    text = _compact_text(value)
    claim_ids: list[str] = []
    for pattern in (
        r"\b(?:CLAIM|CLM)[-_][A-Z0-9][A-Z0-9_-]*\b",
        r"\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b",
    ):
        for match in re.findall(pattern, text, flags=re.IGNORECASE):
            claim_id = (
                match.upper().replace("_", "-")
                if re.match(r"^(?:CLAIM|CLM)[-_]", match, flags=re.IGNORECASE)
                else match
            )
            if claim_id not in claim_ids:
                claim_ids.append(claim_id)
    return claim_ids


def _latest_return_claim_ids(
    history: list[dict[str, Any]] | None,
    typed_context: list[dict[str, Any]] | None,
) -> tuple[list[str], str]:
    """Return the latest authoritative return list without merging older scopes."""

    for context in reversed(list(typed_context or [])):
        if not isinstance(context, dict):
            continue
        claim_ids = [
            _compact_text(value)
            for value in list(context.get("claim_ids") or [])
            if _compact_text(value)
        ]
        if claim_ids and _compact_text(context.get("kind")) == "return_selection":
            return list(dict.fromkeys(claim_ids)), "typed_return_selection"
    for row in reversed(list(history or [])):
        if not isinstance(row, dict):
            continue
        context = row.get("context") if isinstance(row.get("context"), dict) else {}
        claim_ids = [
            _compact_text(value)
            for value in list(context.get("claim_ids") or [])
            if _compact_text(value)
        ]
        if not claim_ids:
            claim_ids = _claim_id_tokens_from_text(row.get("content"))
        if claim_ids:
            return list(dict.fromkeys(claim_ids)), "latest_history_return_selection"
    return [], ""


def _contextual_return_approval_plan(
    goal: str,
    *,
    history: list[dict[str, Any]] | None,
    typed_context: list[dict[str, Any]] | None,
) -> tuple[list[str], dict[str, Any]] | None:
    """Bind a singular contextual approval prepare to one exact prior claim.

    This only prepares an approval packet.  The canonical operation still
    re-reads eligibility and the separate approval protocol owns execution.
    """

    if not _goal_has_return_approval_intent(goal):
        return None
    if not _contextual_reference_requested(goal):
        return None
    claim_ids, context_source = _latest_return_claim_ids(history, typed_context)
    if not claim_ids:
        return None

    normalized = _normalized(goal)
    ordinal_words = {
        "ilk": 0,
        "birinci": 0,
        "ikinci": 1,
        "ucuncu": 2,
        "dorduncu": 3,
        "besinci": 4,
        "altinci": 5,
        "yedinci": 6,
        "sekizinci": 7,
        "dokuzuncu": 8,
        "onuncu": 9,
    }
    ordinal_index: int | None = next(
        (
            index
            for word, index in ordinal_words.items()
            if re.search(rf"(?<!\w){re.escape(word)}(?!\w)", normalized)
        ),
        None,
    )
    numeric = re.search(r"(?<!\w)(\d{1,2})\s*(?:inci|nci|uncu|ncu)(?!\w)", normalized)
    if numeric:
        ordinal_index = max(0, int(numeric.group(1)) - 1)
    if any(
        token in f" {normalized} "
        for token in (" sonuncu ", " listedeki son ", " listenin son ")
    ):
        ordinal_index = len(claim_ids) - 1
    if ordinal_index is None:
        if len(claim_ids) != 1:
            return None
        ordinal_index = 0
    if ordinal_index < 0 or ordinal_index >= len(claim_ids):
        return None

    claim_id = claim_ids[ordinal_index]
    step_id = "returns.approve.prepare"
    spec = {
        "id": step_id,
        "operation_id": "returns.approve.prepare",
        "operation_domain": "orders",
        "arguments": {"query": claim_id, "limit": 1},
        "depends_on": [],
        "objective": _compact_text(goal),
        "expected_evidence": [
            "claim_id",
            "action_type",
            "preview",
            "execute",
            "scope",
        ],
    }
    return [step_id], {
        "source": "typed_contextual_action",
        "step_ids": [step_id],
        "step_specs": [spec],
        "rejected_step_ids": [],
        "fallback_step_ids": [step_id],
        "model_plan_bypassed": True,
        "contextual_history_used": True,
        "context_direct_binding_used": True,
        "context_source": context_source,
        "context_claim_ids": claim_ids[:20],
        "selected_claim_id": claim_id,
        "selected_ordinal_index": ordinal_index,
    }


def _contextual_report_export_plan(
    state: AgentSessionState,
    goal: str,
) -> tuple[list[str], dict[str, Any]] | None:
    """Prepare an XLSX from the latest immutable Orders report snapshot.

    The follow-up must explicitly request an export and point at prior
    context.  The snapshot is intentionally not copied into the plan; the
    argument resolver binds the latest typed ``analysis_context`` at runtime
    and records that binding for auditability.
    """

    if not _goal_has_report_export_intent(goal):
        return None
    if not _contextual_reference_requested(goal):
        return None
    found, snapshot, context_source = _state_context_binding_value(
        state,
        "report_snapshot",
    )
    if not found or not isinstance(snapshot, dict):
        return None
    if _compact_text(snapshot.get("source_domain")).casefold() != "orders":
        return None
    if _compact_text(snapshot.get("report_type")).casefold() != "orders.item_sales":
        return None
    snapshot_id = _compact_text(snapshot.get("snapshot_id"))
    content_hash = _compact_text(snapshot.get("content_hash"))
    if not snapshot_id or not content_hash:
        return None

    step_id = "orders.item_sales.report_xlsx.prepare"
    spec = {
        "id": step_id,
        "operation_id": "orders.item_sales_report_xlsx.prepare",
        "operation_domain": "orders",
        "arguments": {},
        "depends_on": [],
        "objective": _compact_text(goal),
        "expected_evidence": [
            "action",
            "snapshot_id",
            "content_hash",
            "output_path",
            "file_not_created_before_approval",
        ],
    }
    return [step_id], {
        "source": "typed_contextual_artifact",
        "step_ids": [step_id],
        "step_specs": [spec],
        "rejected_step_ids": [],
        "fallback_step_ids": [step_id],
        "model_plan_bypassed": True,
        "contextual_history_used": True,
        "context_direct_binding_used": True,
        "context_source": context_source,
        "snapshot_id": snapshot_id,
        "content_hash": content_hash,
    }


def _contextual_order_number_projection_plan(
    state: AgentSessionState,
    goal: str,
) -> tuple[list[str], dict[str, Any]] | None:
    normalized = _normalized(goal)
    if not _contextual_reference_requested(goal):
        return None
    if not _explicit_read_listing_requested(goal):
        return None
    if not any(
        marker in normalized
        for marker in (
            "siparis numara",
            "siparis no",
            "order number",
            "order no",
        )
    ):
        return None
    snapshot = state.active_selection("orders")
    if snapshot is None or not snapshot.is_complete:
        return None
    order_numbers = [
        _compact_text(value)
        for value in snapshot.record_ids
        if _compact_text(value)
    ]
    if not order_numbers or len(order_numbers) > 100:
        return None
    account_ids = list(
        dict.fromkeys(
            int(ref.account)
            for ref in snapshot.refs
            if _compact_text(ref.account).isdigit()
        )
    )
    step_id = "orders.active_selection.order_numbers"
    arguments: dict[str, Any] = {
        "order_numbers": order_numbers,
        "limit": len(order_numbers),
        "mode": "list",
    }
    if account_ids:
        arguments["api_account_ids"] = account_ids
    spec = {
        "id": step_id,
        "operation_id": "orders.query",
        "operation_domain": "orders",
        "arguments": arguments,
        "depends_on": [],
        "objective": "Aktif exact siparis seciminin yalniz siparis numaralarini listele",
        "expected_evidence": [
            "order_numbers",
            "record_refs",
            "account_scopes",
        ],
    }
    return [step_id], {
        "source": "typed_selection_projection",
        "step_ids": [step_id],
        "step_specs": [spec],
        "selection_id": snapshot.selection_id,
        "selected_record_count": len(order_numbers),
        "contextual_history_used": True,
        "context_direct_binding_used": True,
        "rejected_step_ids": [],
    }


def _canonical_recovered_orders_read_plan(
    interpretation: dict[str, Any],
    goal: str,
) -> tuple[list[str], dict[str, Any]] | None:
    """Anchor repaired read intents to one minimal canonical operation."""

    recovery_source = (
        _compact_text(interpretation.get("decision_path"))
        == "typed_canonical_read_recovery"
    )
    requested_fields = {
        _compact_text(value).casefold()
        for value in list(interpretation.get("requested_fields") or [])
        if _compact_text(value)
    }
    # A scope correction for an existing action is not a read-only recovery.
    # The model-authored typed objective carries the action continuity that an
    # elliptical message such as "all waiting ones" omits.  Turning every
    # correction into one deterministic read silently discards the remaining
    # action and lets the agent claim completion after listing the records.
    if (
        not recovery_source
        and _compact_text(interpretation.get("mode")).casefold() == "correct"
        and _compact_text(interpretation.get("intent_kind")).casefold()
        == "correction"
        and "action_result" in requested_fields
    ):
        return None
    if (
        not recovery_source
        and _compact_text(interpretation.get("intent_kind"))
        not in {"data_read", "correction"}
    ):
        return None
    plan_source = (
        "typed_canonical_read_recovery"
        if recovery_source
        else "typed_canonical_read_intent"
    )
    text = _normalized(goal)
    if _goal_has_item_sales_report_intent(goal) and not _goal_has_report_export_intent(goal):
        period = "this_month"
        if any(token in text for token in ("son 21 gun", "son 3 hafta", "son uc hafta")):
            period = "last_21_days"
        elif "son 30 gun" in text:
            period = "last_30_days"
        elif "son 14 gun" in text:
            period = "last_14_days"
        elif "son 7 gun" in text:
            period = "last_7_days"
        limit_match = re.search(
            r"(?:en cok satan|cok satan|top selling)\s+(\d{1,3})",
            text,
        ) or re.search(r"\b(?:ilk|top)\s+(\d{1,3})", text)
        limit = max(
            1,
            min(100, int(limit_match.group(1)) if limit_match else 10),
        )
        step_id = "orders.item_sales.report"
        spec = {
            "id": step_id,
            "operation_id": "orders.item_sales_report",
            "operation_domain": "orders",
            "arguments": {
                "period": period,
                "group_by": "product",
                "limit": limit,
            },
            "depends_on": [],
            "objective": _compact_text(goal),
            "expected_evidence": [
                "report_snapshot",
                "item_sales_rows",
                "scope",
            ],
        }
        return [step_id], {
            "source": plan_source,
            "step_ids": [step_id],
            "step_specs": [spec],
            "rejected_step_ids": [],
            "fallback_step_ids": [step_id],
            "model_plan_bypassed": True,
        }
    read_contract = dict(interpretation.get("semantic_contract") or {})
    if order_status_codes(read_contract):
        # Exact codes require model-authored filters and projection. A coarse
        # ready/count shortcut cannot represent this population.
        return None
    if _compact_text(read_contract.get("entity")) == "order":
        metric = _compact_text(read_contract.get("metric"))
        status_scope = _compact_text(read_contract.get("status_scope"))
        period = _compact_text(read_contract.get("period")) or (
            "all" if status_scope == "ready_to_ship" else "today"
        )
        operation_id = ""
        step_id = ""
        expected_evidence: list[str] = []
        if metric == "count":
            if status_scope == "ready_to_ship":
                step_id = "orders.ready_to_ship_count"
                operation_id = "orders.ready_to_ship_count"
                expected_evidence = [
                    "count",
                    "order_numbers",
                    "api_account_ids",
                    "period_label",
                ]
            elif status_scope == "all":
                step_id = "orders.count"
                operation_id = "orders.count"
                expected_evidence = [
                    "count",
                    "api_account_ids",
                    "period_label",
                ]
        elif metric == "list" and status_scope == "ready_to_ship":
            step_id = "orders.ready_to_ship"
            operation_id = "orders.ready_to_ship"
            expected_evidence = [
                "order_numbers",
                "listed_count",
                "ready_to_ship",
                "api_account_ids",
                "period_label",
            ]
        elif metric in {"count", "list", "summary", "status"} and status_scope == "nonfinal":
            step_id = "orders.nonfinal_summary"
            operation_id = "orders.nonfinal_summary"
            expected_evidence = [
                "total_count",
                "status_counts",
                "final_statuses",
                "account_scopes",
            ]
        elif metric == "summary" and status_scope == "all":
            step_id = "orders.summary"
            operation_id = "orders.summary"
            expected_evidence = [
                "total_orders",
                "status_counts",
                "api_account_ids",
                "period_label",
            ]
        if step_id and operation_id:
            spec = {
                "id": step_id,
                "operation_id": operation_id,
                "operation_domain": "orders",
                "arguments": {"period": period},
                "depends_on": [],
                "objective": _compact_text(goal),
                "expected_evidence": expected_evidence,
            }
            return [step_id], {
                "source": plan_source,
                "step_ids": [step_id],
                "step_specs": [spec],
                "rejected_step_ids": [],
                "fallback_step_ids": [step_id],
                "model_plan_bypassed": True,
                "semantic_read_contract": read_contract,
                "correction_target": dict(
                    interpretation.get("correction_target") or {}
                ),
            }
    if (
        _goal_has_waiting_return_count_intent(goal)
        and not _explicit_read_listing_requested(goal)
    ):
        step_id = "returns.waiting.count"
        spec = {
            "id": step_id,
            "operation_id": "returns.waiting_action_count",
            "operation_domain": "orders",
            "arguments": {"period": "all"},
            "depends_on": [],
            "objective": _compact_text(goal),
            "expected_evidence": ["count", "scope"],
        }
        return [step_id], {
            "source": plan_source,
            "step_ids": [step_id],
            "step_specs": [spec],
            "rejected_step_ids": [],
            "fallback_step_ids": [step_id],
            "model_plan_bypassed": True,
        }
    recent_return_match = re.search(
        r"\bson\s+(\d{1,2})\s+(?:iade|return|claim)",
        text,
    )
    if (
        recent_return_match
        and any(token in text for token in ("listele", "goster", "getir", "sirala"))
    ):
        limit = max(1, min(100, int(recent_return_match.group(1))))
        step_id = "returns.recent.list"
        spec = {
            "id": step_id,
            "operation_id": "returns.query",
            "operation_domain": "orders",
            "arguments": {
                "period": "all",
                "sort": "claim_date_desc",
                "limit": limit,
                "mode": "list",
            },
            "depends_on": [],
            "objective": _compact_text(goal),
            "expected_evidence": [
                "claim_ids",
                "order_numbers",
                "status",
                "reasons",
                "total_count",
                "scope",
            ],
        }
        return [step_id], {
            "source": plan_source,
            "step_ids": [step_id],
            "step_specs": [spec],
            "rejected_step_ids": [],
            "fallback_step_ids": [step_id],
            "model_plan_bypassed": True,
        }
    if (
        any(token in text for token in ("iade", "return", "claim"))
        and any(token in text for token in ("onay bekleyen", "aksiyon bekleyen"))
        and any(token in text for token in ("listele", "goster", "getir", "sirala"))
    ):
        step_id = "returns.waiting.list"
        spec = {
            "id": step_id,
            "operation_id": "returns.query",
            "operation_domain": "orders",
            "arguments": {
                "period": "all",
                "filters": {"waiting_action_only": True},
                "sort": "claim_date_desc",
                "limit": 100,
                "mode": "list",
            },
            "depends_on": [],
            "objective": _compact_text(goal),
            "expected_evidence": ["claim_ids", "status", "scope"],
        }
        return [step_id], {
            "source": plan_source,
            "step_ids": [step_id],
            "step_specs": [spec],
            "rejected_step_ids": [],
            "fallback_step_ids": [step_id],
            "model_plan_bypassed": True,
        }
    return None


def _contextualize_orders_plan(
    step_ids: list[str],
    goal: str,
    history: list[dict[str, str]] | None,
    *,
    step_specs: list[dict[str, Any]] | None = None,
    typed_context: list[dict[str, Any]] | None = None,
) -> tuple[list[str], dict[str, Any], list[dict[str, Any]]]:
    normalized_goal = _normalized(goal)
    contextual_reference = any(
        token in normalized_goal
        for token in (
            "bu ",
            "bunu",
            "bunlar",
            "onlar",
            "listedeki",
            "onceki",
            "az onceki",
            "olan",
        )
    )
    history_order_ids, history_claim_ids = _task_history_identifiers(history)
    typed_order_ids: list[str] = []
    typed_claim_ids: list[str] = []
    typed_order_binding_available = False
    for context in list(typed_context or []):
        if not isinstance(context, dict):
            continue
        context_order_ids = [
            _compact_text(value)
            for value in list(context.get("order_numbers") or [])
            if _compact_text(value)
        ]
        typed_order_ids.extend(context_order_ids)
        if context_order_ids and _compact_text(context.get("kind")) in {
            "order_selection",
            "pending_action",
        }:
            typed_order_binding_available = True
        typed_claim_ids.extend(
            _compact_text(value)
            for value in list(context.get("claim_ids") or [])
            if _compact_text(value)
        )
    order_ids = list(dict.fromkeys([*typed_order_ids, *history_order_ids]))
    claim_ids = list(dict.fromkeys([*typed_claim_ids, *history_claim_ids]))
    removed: list[str] = []
    contextual = list(step_ids)
    order_context_steps = {
        "orders.full_context",
        "orders.product_public_identities",
        "orders.labels.prepare",
        "orders.labels.extracted.prepare",
        "orders.cargo.change.prepare",
        "orders.cargo.bulk_change.prepare",
        "orders.profit.export.prepare",
    }
    semantic_by_id = {
        _compact_text(spec.get("id")): (
            _canonical_step_id_for_operation(spec.get("operation_id"))
            or _compact_text(spec.get("id"))
        )
        for spec in list(step_specs or [])
        if isinstance(spec, dict) and _compact_text(spec.get("id"))
    }
    operation_by_id = {
        _compact_text(spec.get("id")): _compact_text(
            spec.get("operation_id")
        )
        for spec in list(step_specs or [])
        if isinstance(spec, dict) and _compact_text(spec.get("id"))
    }
    semantic_step_ids = [semantic_by_id.get(step_id, step_id) for step_id in contextual]
    if contextual_reference and order_ids and any(
        semantic_id in order_context_steps for semantic_id in semantic_step_ids
    ):
        for step_id in list(contextual):
            if semantic_by_id.get(step_id, step_id) in {
                "orders.ready_to_ship",
                "orders.recent",
            }:
                contextual.remove(step_id)
                removed.append(step_id)
    if contextual_reference and claim_ids and "returns.approve.prepare" in semantic_step_ids:
        for step_id in list(contextual):
            if semantic_by_id.get(step_id, step_id) == "returns.waiting.list":
                contextual.remove(step_id)
                removed.append(step_id)
    final_step_ids = contextual or list(step_ids)
    final_step_id_set = set(final_step_ids)
    contextual_specs: list[dict[str, Any]] = []
    context_bound_direct = False
    rebound_step_ids: list[str] = []
    for raw in list(step_specs or []):
        if not isinstance(raw, dict):
            continue
        spec = dict(raw)
        step_id = _compact_text(spec.get("id"))
        if step_id not in final_step_id_set:
            continue
        spec["depends_on"] = [
            _compact_text(value)
            for value in list(spec.get("depends_on") or [])
            if _compact_text(value) in final_step_id_set
            and _compact_text(value) != step_id
        ]
        arguments = dict(spec.get("arguments") or {})
        for name, value in list(arguments.items()):
            if (
                isinstance(value, dict)
                and _compact_text(value.get("$from_step")) in removed
            ):
                arguments.pop(name, None)
        spec["arguments"] = arguments
        semantic_step_id = semantic_by_id.get(step_id, step_id)
        operation_id = operation_by_id.get(step_id, "")
        planned_order_numbers = [
            _compact_text(value)
            for value in list(arguments.get("order_numbers") or [])
            if _compact_text(value)
        ]
        if (
            contextual_reference
            and order_ids
            and (
                semantic_step_id in order_context_steps
                or operation_id == "orders.query"
            )
        ):
            exact_order_ids = order_ids[:20]
            if set(planned_order_numbers) != set(exact_order_ids):
                rebound_step_ids.append(step_id)
            if typed_order_binding_available:
                # Do not copy deictic targets into model-authored arguments.
                # The execution boundary binds the active typed
                # Selection/PendingAction and records ``session_context:...``
                # provenance.  Keeping direct arguments here produced the same
                # values but erased the audit trail that proves where
                # "bu siparisler" came from.
                arguments.pop("order_numbers", None)
            else:
                # Transitional history-only callers do not carry a typed state
                # entity the execution boundary can bind.  Preserve their exact
                # bounded IDs for compatibility; new conversation runtime paths
                # use the branch above.
                arguments["order_numbers"] = exact_order_ids
            spec["arguments"] = arguments
            context_bound_direct = True
        contextual_specs.append(spec)
    return final_step_ids, {
        "contextual_history_used": bool(removed or context_bound_direct),
        "context_direct_binding_used": bool(context_bound_direct),
        "context_order_ids": order_ids[:20],
        "context_claim_ids": claim_ids[:20],
        "context_removed_step_ids": removed,
        "context_removed_semantic_step_ids": [
            semantic_by_id.get(step_id, step_id) for step_id in removed
        ],
        "context_rebound_step_ids": list(dict.fromkeys(rebound_step_ids)),
    }, contextual_specs


def _tool_names_from_turn(data: dict[str, Any]) -> list[str]:
    calls = data.get("tool_calls")
    if isinstance(calls, list) and calls:
        return [_compact_text(row.get("tool")) for row in calls if isinstance(row, dict) and _compact_text(row.get("tool"))]
    tool_call = data.get("tool_call")
    if isinstance(tool_call, dict) and _compact_text(tool_call.get("tool")):
        return [_compact_text(tool_call.get("tool"))]
    decision = data.get("decision")
    if decision is not None:
        tool_calls = list(getattr(decision, "tool_calls", ()) or [])
        if tool_calls:
            return [_compact_text(getattr(call, "tool_name", "")) for call in tool_calls if _compact_text(getattr(call, "tool_name", ""))]
        if _compact_text(getattr(decision, "tool_name", "")):
            return [_compact_text(getattr(decision, "tool_name", ""))]
    return []


def _completed_dependency_steps(
    state: AgentSessionState,
    step: AgentTaskStep,
) -> dict[str, AgentTaskStep]:
    allowed = {
        _compact_text(value)
        for value in list(step.depends_on or [])
        if _compact_text(value)
    }
    return {
        _compact_text(candidate.step_id): candidate
        for candidate in state.completed_steps
        if candidate.status == "completed"
        and _compact_text(candidate.step_id) in allowed
    }






def _contextual_reference_requested(value: Any) -> bool:
    text = _normalized(value)
    return any(
        token in f" {text} "
        for token in (
            " bu ",
            " bunu ",
            " bunlari ",
            " bunlar ",
            " su ",
            " onu ",
            " onlari ",
            " listedeki ",
            " onceki ",
            " az onceki ",
        )
    )


def _contextual_order_subset(
    goal: Any,
    values: list[str],
) -> tuple[list[str], str]:
    """Apply an explicit ordinal/limit to an ordered typed selection."""

    ordered = list(dict.fromkeys(_compact_text(value) for value in values if _compact_text(value)))
    if not ordered:
        return [], ""
    text = _normalized(goal)
    counted = re.search(
        r"(?<!\w)(?:ilk|en\s+son|en\s+yeni)\s+(?:siradaki\s+)?(\d+)\s+siparis",
        text,
    )
    if counted:
        limit = max(1, int(counted.group(1)))
        return ordered[:limit], f"ordered_first_{limit}"

    # Resolve an ordinal against the immutable display order.  This is a
    # language-level RecordRef operation, not an Orders business heuristic:
    # "first row", "second order" and "3rd item" all select one member of the
    # already-authoritative ordered set.
    word_ordinals = {
        "ilk": 0,
        "birinci": 0,
        "ikinci": 1,
        "ucuncu": 2,
        "dorduncu": 3,
        "besinci": 4,
        "altinci": 5,
        "yedinci": 6,
        "sekizinci": 7,
        "dokuzuncu": 8,
        "onuncu": 9,
    }
    word_match = re.search(
        r"(?<!\w)(?:bu\s+)?(?:listedeki\s+)?"
        r"(ilk|birinci|ikinci|ucuncu|dorduncu|besinci|altinci|yedinci|"
        r"sekizinci|dokuzuncu|onuncu)\s+(?:siradaki\s+)?siparis",
        text,
    )
    ordinal_index: int | None = (
        word_ordinals.get(word_match.group(1)) if word_match else None
    )
    if ordinal_index is None:
        numeric_match = re.search(
            r"(?<!\w)(?:bu\s+)?(?:listedeki\s+)?(\d{1,3})\s*"
            r"(?:\.|inci|nci|uncu)\s*(?:siradaki\s+)?siparis",
            text,
        )
        if numeric_match:
            ordinal_index = max(0, int(numeric_match.group(1)) - 1)
    if ordinal_index is None and re.search(
        r"(?<!\w)(?:bu\s+)?(?:listedeki\s+)?(?:sonuncu|son\s+siradaki)\s+siparis",
        text,
    ):
        ordinal_index = len(ordered) - 1
    if ordinal_index is not None:
        if ordinal_index >= len(ordered):
            return [], f"ordered_ordinal_out_of_range_{ordinal_index + 1}"
        qualifier = (
            "ordered_first_1"
            if ordinal_index == 0
            else f"ordered_index_{ordinal_index + 1}"
        )
        return [ordered[ordinal_index]], qualifier
    if re.search(
        r"(?<!\w)(?:(?:bu\s+)?listedeki\s+)?(?:en\s+son|en\s+yeni)\s+siparis",
        text,
    ):
        return ordered[:1], "ordered_first_1"
    return ordered, ""


def _contextual_order_reference_count(value: Any) -> int | None:
    """Read an explicit cardinality from a deictic order reference."""

    text = _normalized(value)
    numeric = re.search(
        r"(?<!\w)(?:bu|su|o)?\s*(\d{1,3})\s+siparis\w*(?!\w)",
        text,
    )
    if numeric:
        return max(1, int(numeric.group(1)))
    word_numbers = {
        "bir": 1,
        "iki": 2,
        "uc": 3,
        "dort": 4,
        "bes": 5,
        "alti": 6,
        "yedi": 7,
        "sekiz": 8,
        "dokuz": 9,
        "on": 10,
    }
    for word, count in word_numbers.items():
        if re.search(
            rf"(?<!\w)(?:bu|su|o)?\s*{word}\s+siparis\w*(?!\w)",
            text,
        ):
            return count
    return None


def _state_context_binding_value(
    state: AgentSessionState,
    name: str,
) -> tuple[bool, Any, str]:
    interpretation = (
        dict((state.active_entities or {}).get("turn_interpretation") or {})
        if isinstance(
            (state.active_entities or {}).get("turn_interpretation"),
            dict,
        )
        else {}
    )
    semantic_contract = (
        dict(interpretation.get("semantic_contract") or {})
        if isinstance(interpretation.get("semantic_contract"), dict)
        else {}
    )
    if (
        name == "order_numbers"
        and _compact_text(
            semantic_contract.get("record_scope")
        ).casefold()
        == "all_matching"
        and semantic_contract.get("contextual_item_identity_required") is not True
    ):
        return False, None, ""
    if not _contextual_reference_requested(state.goal):
        return False, None, ""
    if name == "order_numbers":
        requested_count = _contextual_order_reference_count(state.goal)
        pending_action = state.active_pending_action()
        if pending_action is not None:
            pending_context = state._pending_action_context(pending_action)
            pending_values = [
                _compact_text(value)
                for value in list(pending_context.get("order_numbers") or [])
                if _compact_text(value)
            ]
            if pending_values and (
                requested_count is None
                or len(pending_values) == requested_count
            ):
                values, qualifier = _contextual_order_subset(
                    state.goal,
                    pending_values,
                )
                if values:
                    binding_kind = "pending_action"
                    if qualifier:
                        binding_kind = f"{binding_kind}.{qualifier}"
                    return True, values, binding_kind
        prior_pending_contexts = [
            dict(row)
            for row in list(
                (state.active_entities or {}).get(
                    "prior_authoritative_context"
                )
                or []
            )
            if isinstance(row, dict)
            and _compact_text(row.get("kind")) == "pending_action"
        ]
        for pending_context in reversed(prior_pending_contexts):
            pending_values = [
                _compact_text(value)
                for value in list(
                    pending_context.get("order_numbers") or []
                )
                if _compact_text(value)
            ]
            if not pending_values or (
                requested_count is not None
                and len(pending_values) != requested_count
            ):
                continue
            values, qualifier = _contextual_order_subset(
                state.goal,
                pending_values,
            )
            if values:
                binding_kind = "pending_action"
                if qualifier:
                    binding_kind = f"{binding_kind}.{qualifier}"
                return True, values, binding_kind
        active_selection = state.active_selection("orders")
        selection_candidates = [
            snapshot
            for snapshot in reversed(state.selection_snapshots)
            if snapshot.domain == "orders"
        ]
        if active_selection is not None:
            selection_candidates = [
                active_selection,
                *[
                    snapshot
                    for snapshot in selection_candidates
                    if snapshot.selection_id != active_selection.selection_id
                ],
            ]
        selected_snapshot = next(
            (
                snapshot
                for snapshot in selection_candidates
                if (
                    requested_count is None
                    or (
                        snapshot.is_complete
                        and len(snapshot.record_ids) == requested_count
                    )
                )
            ),
            None,
        )
        if selected_snapshot is not None:
            values, qualifier = _contextual_order_subset(
                state.goal,
                list(selected_snapshot.record_ids),
            )
            if values:
                binding_kind = "order_selection"
                if qualifier:
                    binding_kind = f"{binding_kind}.{qualifier}"
                return True, values, binding_kind
        if requested_count is not None:
            # An explicit "these N orders" reference cannot safely fall back
            # to a stale, truncated or differently-sized history selection.
            return False, None, "order_selection.cardinality_mismatch"
    rows = [
        dict(row)
        for row in list((state.active_entities or {}).get("prior_authoritative_context") or [])
        if isinstance(row, dict)
    ]
    rows.extend(_planner_typed_context(state))
    for context in reversed(rows):
        value = context.get(name)
        if value in (None, "", [], {}) and _compact_text(
            context.get("kind")
        ) == "analysis_context":
            value = dict(context.get("facts") or {}).get(name)
        if name in {"order_numbers", "claim_ids"}:
            values = [
                _compact_text(item)
                for item in list(value or [])
                if _compact_text(item)
            ]
            if values:
                binding_kind = _compact_text(context.get("kind")) or "typed_context"
                if name == "order_numbers":
                    values, qualifier = _contextual_order_subset(state.goal, values)
                    if qualifier:
                        binding_kind = f"{binding_kind}.{qualifier}"
                return True, list(dict.fromkeys(values)), binding_kind
        elif value not in (None, "", [], {}):
            return True, deepcopy(value), _compact_text(context.get("kind")) or "typed_context"
    return False, None, ""


def _resolve_step_arguments(
    state: AgentSessionState,
    step: AgentTaskStep,
    tool: Any,
    *,
    db_name: str | None = None,
) -> tuple[dict[str, Any], list[str], dict[str, str]]:
    """Resolve only immutable outputs of declared, completed dependencies."""

    dependencies = _completed_dependency_steps(state, step)
    operation_id = _compact_text(getattr(tool, "name", ""))
    problems = _source_bound_operation_argument_problems(
        operation_id, dict(step.arguments or {}), set(dependencies),
        source_operations={
            source_id: (source.tool_names[0] if len(source.tool_names) == 1 else "")
            for source_id, source in dependencies.items()
        },
    )
    problems.extend(source_operation_problems(operation_id, state=state))
    bindings: dict[str, str] = {}
    resolved = _resolve_argument_value(
        dict(step.arguments or {}),
        dependencies=dependencies,
        path="arguments",
        problems=problems,
        bindings=bindings,
    )
    kwargs = dict(resolved or {}) if isinstance(resolved, dict) else {}
    from AI.processors.child_task_runtime import bind_child_read_arguments
    kwargs, child_scope_problems = bind_child_read_arguments(tool, kwargs)
    problems.extend(child_scope_problems)
    if operation_id == "artifacts.read":
        from AI.processors.observation_artifacts import observation_artifact_refs
        try:
            permitted = {row["artifact_id"] for row in observation_artifact_refs(state)}
        except (ValueError, TypeError, KeyError, OSError, RecursionError):
            permitted = set()
        if kwargs.get("artifact_id") not in permitted:
            problems.append("arguments.artifact_id:binding_observation_artifact_not_authorized")
    if operation_id in {"files.list", "files.read"}:
        workspace = (state.active_entities or {}).get("file_workspace")
        if not isinstance(workspace, dict) or not _compact_text(workspace.get("session_id")):
            problems.append("arguments.session_id:binding_import_workspace_authority_missing")
            kwargs.pop("session_id", None)
        else:
            kwargs["session_id"] = _compact_text(workspace["session_id"])
            bindings["session_id"] = "trusted_file_workspace.session_id"
            attachments = {
                _compact_text(row.get("attachment_id"))
                for row in list(workspace.get("attachments") or [])
                if isinstance(row, dict)
            }
            if operation_id == "files.read" and _compact_text(kwargs.get("attachment_id")) not in attachments:
                problems.append("arguments.attachment_id:binding_attachment_not_authorized")
    if operation_id in {"reports.build_snapshot", "analysis.calculate", "analysis.table", "reports.xlsx.prepare"}:
        from AI.processors.observation_projection import source_projection_hash
        from AI.processors.tools import available_tools

        registry = available_tools()
        if operation_id == "reports.xlsx.prepare":
            binding = (step.arguments or {}).get("report_snapshot")
            source_id = _compact_text(binding.get("$from_step")) if isinstance(binding, dict) else ""
            source = dependencies.get(source_id)
            source_result = dict((source.result_data or {}).get("tool_result") or {}) if source else {}
            if (
                source is None
                or source.tool_names != ["reports.build_snapshot"]
                or not isinstance(source_result.get("report_snapshot"), dict)
                or source_projection_hash(kwargs.get("report_snapshot"))
                != source_projection_hash(source_result.get("report_snapshot"))
            ):
                problems.append("arguments.report_snapshot:binding_builder_receipt_invalid")
        else:
            for index, raw_source in enumerate(list(kwargs.get("sources") or [])):
                projected = raw_source if isinstance(raw_source, dict) else {}
                source_id = _compact_text(projected.get("source_step_id"))
                source = dependencies.get(source_id)
                source_tool = registry.get(_compact_text(projected.get("operation_id")))
                if (
                    source is None or source_tool is None
                    or source.tool_names != [source_tool.name]
                    or not source_tool.read_only or source_tool.destructive
                    or source_tool.requires_approval or source_tool.action_type != "read"
                    or source.verification_status not in {"observed", "verified"}
                    or source_projection_hash(projected.get("result"))
                    != source_projection_hash((source.result_data or {}).get("tool_result"))
                ):
                    problems.append(f"arguments.sources[{index}].result:binding_authoritative_read_receipt_invalid")

    schema = tool.parameters if isinstance(tool.parameters, dict) else {}
    required = [
        _compact_text(name)
        for name in list(schema.get("required") or [])
        if _compact_text(name)
    ]
    schema_properties = (
        set(schema.get("properties") or {})
        if isinstance(schema.get("properties"), dict)
        else set()
    )
    interpretation = (
        dict((state.active_entities or {}).get("turn_interpretation") or {})
        if isinstance(
            (state.active_entities or {}).get("turn_interpretation"),
            dict,
        )
        else {}
    )
    semantic_contract = (
        dict(interpretation.get("semantic_contract") or {})
        if isinstance(interpretation.get("semantic_contract"), dict)
        else {}
    )
    contract_period = _compact_text(
        semantic_contract.get("period")
    ).casefold()
    if (
        contract_period
        and _compact_text(state.active_domain).casefold() != "general"
        and contract_period != "unspecified"
        and "period" in schema_properties
        and bool(getattr(tool, "read_only", False))
        and not bool(getattr(tool, "destructive", False))
        and _compact_text(getattr(tool, "action_type", "read")).casefold()
        == "read"
        and _compact_text(kwargs.get("period")).casefold() != contract_period
    ):
        # A domain read keeps its typed boundary. A general goal can compare
        # multiple source periods; their actual bounds are verified after read.
        kwargs["period"] = contract_period
        bindings["period"] = "typed_semantic_contract.period"
    contextual_product_ordinal = semantic_contract.get(
        "contextual_product_ordinal"
    )
    if (
        _compact_text(getattr(tool, "name", ""))
        == "orders.product_public_identities"
        and "item_ordinal" in schema_properties
        and isinstance(contextual_product_ordinal, int)
        and not isinstance(contextual_product_ordinal, bool)
        and contextual_product_ordinal > 0
    ):
        kwargs["item_ordinal"] = int(contextual_product_ordinal)
        bindings["item_ordinal"] = (
            "typed_semantic_contract.contextual_product_ordinal"
        )
    public_research_facets = [
        _compact_text(value).casefold()
        for value in list(semantic_contract.get("public_research_facets") or [])
        if _compact_text(value).casefold() in {"user_opinions"}
    ]
    if (
        _compact_text(getattr(tool, "name", ""))
        == "orders.product_public_identities"
        and "research_facets" in schema_properties
        and public_research_facets
    ):
        kwargs["research_facets"] = list(dict.fromkeys(public_research_facets))
        bindings["research_facets"] = (
            "typed_semantic_contract.public_research_facets"
        )
    bindable_names = list(
        dict.fromkeys(
            required
            + sorted(schema_properties.intersection(_AUTO_BOUND_DEPENDENCY_FIELDS))
        )
    )
    for name in bindable_names:
        contextual_population_item_sales = bool(
            _compact_text(getattr(tool, "name", ""))
            == "orders.item_sales_summary"
            and semantic_contract.get("contextual_item_identity_required") is True
            and _compact_text(semantic_contract.get("record_scope")).casefold()
            == "all_matching"
        )
        if name == "order_numbers" and contextual_population_item_sales:
            # The active order identifies the product in the preceding
            # privacy-safe identity step; it is not the population filter for
            # the sales aggregate. Auto-binding it here silently turns an
            # all-history question back into the single selected order.
            kwargs.pop(name, None)
            continue
        if name == "api_account_ids" and _compact_text(db_name):
            from AI.processors.tools import resolve_active_api_account_scope_for_query

            scope_result = resolve_active_api_account_scope_for_query(
                db_name=_compact_text(db_name),
                query=state.goal,
            )
            if not scope_result.success:
                kwargs.pop(name, None)
                problems.append(
                    "arguments.api_account_ids:account_scope_unresolved"
                )
                continue
            scope_data = dict(scope_result.data or {})
            resolved_ids = [
                int(value)
                for value in list(scope_data.get("api_account_ids") or [])
                if value not in (None, "")
            ]
            active_scope = state.active_scopes.get(
                _compact_text(getattr(tool, "domain", "")).casefold()
                or state.active_domain.casefold()
            )
            active_ids: list[int] = []
            if active_scope is not None:
                for value in active_scope.account_ids:
                    try:
                        active_ids.append(int(value))
                    except (TypeError, ValueError):
                        continue
            user_explicit = bool(scope_data.get("user_explicit"))
            scoped_ids = (
                resolved_ids
                if user_explicit
                else list(dict.fromkeys(active_ids))
                if active_ids
                else resolved_ids
            )
            if not scoped_ids:
                if user_explicit:
                    kwargs.pop(name, None)
                    problems.append(
                        "arguments.api_account_ids:account_scope_empty"
                    )
                continue
            # Account ids are internal database keys. A model may repeat a
            # public SellerID such as 2738 in this field, but it is never the
            # authority that maps user-visible account identity to a database
            # scope. Resolve and overwrite at the execution boundary.
            kwargs[name] = list(dict.fromkeys(scoped_ids))
            source = (
                "explicit"
                if user_explicit
                else "typed_active_scope"
                if active_ids
                else "environment_default"
                if scope_data.get("explicit")
                else "active_accounts"
            )
            bindings[name] = f"goal_account_scope:{source}"
            continue
        if (
            name == "platform_code"
            and _compact_text(getattr(tool, "name", ""))
            == "orders.cargo_provider_options"
            and _contextual_reference_requested(state.goal)
        ):
            active_selection = state.active_selection("orders")
            platforms = list(
                dict.fromkeys(
                    canonical_platform_code(row.get("platform"))
                    for row in list(
                        active_selection.account_scopes
                        if active_selection is not None
                        else []
                    )
                    if canonical_platform_code(row.get("platform"))
                )
            )
            if not platforms:
                active_scope = state.active_scopes.get("orders")
                platforms = list(
                    dict.fromkeys(
                        canonical_platform_code(value)
                        for value in list(
                            active_scope.marketplaces if active_scope is not None else []
                        )
                        if canonical_platform_code(value)
                    )
                )
            if len(platforms) == 1:
                kwargs[name] = platforms[0]
                bindings[name] = "session_context:order_selection.platform_code"
                continue
            if len(platforms) > 1:
                kwargs.pop(name, None)
                problems.append("arguments.platform_code:ambiguous_selection_scope")
                continue
        contextual_identity_source = bool(
            _compact_text(getattr(tool, "name", ""))
            == "orders.product_public_identities"
            and (
                semantic_contract.get("contextual_item_identity_required") is True
                or semantic_contract.get(
                    "contextual_public_product_web_research_required"
                )
                is True
            )
        )
        if (
            name in {"order_numbers", "claim_ids"}
            and _contextual_reference_requested(state.goal)
            and (
                _compact_text(
                    semantic_contract.get("record_scope")
                ).casefold()
                != "all_matching"
                or contextual_identity_source
            )
        ):
            found, value, context_kind = _state_context_binding_value(state, name)
            if found:
                # A retry/replan is not allowed to weaken or erase the exact
                # typed selection behind "bu/bunlar".  Initial plans already
                # pass through _contextualize_orders_plan; this execution-boundary
                # guard applies the same invariant to model-authored replacement
                # steps as well.
                kwargs[name] = value
                bindings[name] = f"session_context:{context_kind}.{name}"
                continue
            if kwargs.get(name) in (None, "", [], {}):
                kwargs.pop(name, None)
                problems.append(f"arguments.{name}:context_binding_missing")
                continue
        if name in kwargs:
            current_value = kwargs.get(name)
            property_schema = (
                dict((schema.get("properties") or {}).get(name) or {})
                if isinstance(schema.get("properties"), dict)
                and isinstance((schema.get("properties") or {}).get(name), dict)
                else {}
            )
            empty_array_is_valid = bool(
                isinstance(current_value, list)
                and not current_value
                and property_schema.get("type") == "array"
                and int(property_schema.get("minItems") or 0) == 0
            )
            if current_value not in (None, "", [], {}) or empty_array_is_valid:
                continue
        kwargs.pop(name, None)
        candidates: list[tuple[str, Any]] = []
        for dependency_id, dependency in dependencies.items():
            tool_result = (
                dict((dependency.result_data or {}).get("tool_result") or {})
                if isinstance((dependency.result_data or {}).get("tool_result"), dict)
                else {}
            )
            if name in tool_result:
                candidates.append((dependency_id, tool_result[name]))
        if len(candidates) == 1:
            dependency_id, value = candidates[0]
            kwargs[name] = deepcopy(value)
            bindings[name] = f"{dependency_id}:tool_result.{name}"
        elif len(candidates) > 1:
            problems.append(f"arguments.{name}:ambiguous_dependency_output")
        elif name in {
            "order_numbers",
            "claim_ids",
            "selection_id",
            "report_snapshot",
        }:
            found, value, context_kind = _state_context_binding_value(state, name)
            if found:
                kwargs[name] = value
                bindings[name] = f"session_context:{context_kind}.{name}"

    if _compact_text(getattr(tool, "name", "")) == "orders.query":
        exact_order_numbers = list(
            dict.fromkeys(
                _compact_text(value)
                for value in list(kwargs.get("order_numbers") or [])
                if _compact_text(value)
            )
        )
        normalized_goal = _normalized(state.goal)
        explicit_subset = bool(
            re.search(
                r"(?<!\w)(?:ilk|en\s+son|en\s+yeni|en\s+fazla|azami|"
                r"maksimum|max|limit|sayfa)\b",
                normalized_goal,
            )
        )
        full_contextual_projection = bool(
            exact_order_numbers
            and _contextual_reference_requested(state.goal)
            and _explicit_read_listing_requested(state.goal)
            and not explicit_subset
        )
        if exact_order_numbers and (
            full_contextual_projection
            or (
                kwargs.get("limit") in (None, "")
                and kwargs.get("page_size") in (None, "")
            )
        ):
            kwargs["limit"] = min(100, len(exact_order_numbers))
            bindings["limit"] = "exact_order_numbers_cardinality"
            if full_contextual_projection:
                kwargs.pop("page_size", None)
                kwargs["offset"] = 0
                kwargs["page"] = 1
                bindings["offset"] = "exact_order_numbers_first_page"
                bindings["page"] = "exact_order_numbers_first_page"

    if _compact_text(getattr(tool, "name", "")) == "labels.create_from_orders.prepare":
        from Labels.processors.catalog import resolve_label_model_reference

        label_model = resolve_label_model_reference(
            state.goal,
            brand_code=_compact_text(kwargs.get("brand_code")),
            model_code=_compact_text(kwargs.get("model_code")),
        )
        if label_model is not None:
            kwargs["brand_code"] = _compact_text(label_model.get("brand_code"))
            kwargs["model_code"] = _compact_text(label_model.get("model_code"))
            bindings["brand_code"] = "goal_label_catalog_reference"
            bindings["model_code"] = "goal_label_catalog_reference"

    return kwargs, list(dict.fromkeys(problems)), bindings


def _run_bound_domain_read_step(
    state: AgentSessionState,
    step: AgentTaskStep,
    *,
    db_name: str | None,
    delegation_context: dict[str, Any] | None = None,
) -> Result | None:
    domain = _compact_text(state.active_domain).casefold()
    from AI.processors.tools import available_tools

    direct_operation_id = next(
        (
            _compact_text(value)
            for value in list(step.operation_candidates or [])
            if _compact_text(value)
        ),
        "",
    )
    is_direct_plan_step = bool(direct_operation_id)
    if is_direct_plan_step:
        operation_id = direct_operation_id
    else:
        if domain in {"orders", "stock"}:
            return None
        catalog = TASK_DOMAIN_STEP_CATALOGS.get(domain, {})
        if step.step_id not in catalog or step.step_id in _WRITE_STEP_IDS:
            return None
        operation_id = _compact_text(step.step_id)

    tool = available_tools().get(operation_id)
    policy_problems = source_operation_problems(operation_id, state=state)
    if policy_problems:
        return Result.fail("Bu görevde yeni kaynak okuma yetkisi yok; mevcut doğrulanmış kaynaklar kullanılmalı.",
                           close_dialog=False, data={"tool": operation_id, "retryable": False,
                                                     "argument_problems": policy_problems})
    expected_operation_domain = (
        _compact_text(step.operation_domain).casefold() or domain
    )
    unsafe_binding = bool(
        tool is None
        or not tool.read_only
        or tool.destructive
        or _compact_text(getattr(tool, "domain", "")).casefold()
        != expected_operation_domain
        or (not is_direct_plan_step and tool.requires_approval)
    )
    if unsafe_binding:
        return Result.fail(
            "Task planindaki atomic operation guvenli bicimde baglanamadi.",
            close_dialog=False,
            data={"tool": operation_id, "retryable": False},
        )
    kwargs: dict[str, Any] = {}
    dependency_bindings: dict[str, str] = {}
    if is_direct_plan_step:
        kwargs, binding_problems, dependency_bindings = _resolve_step_arguments(
            state,
            step,
            tool,
            db_name=db_name,
        )
        if binding_problems:
            return Result.fail(
                "Atomic operation dependency ciktilari guvenli bicimde baglanamadi.",
                close_dialog=False,
                data={
                    "tool": operation_id,
                    "retryable": False,
                    "argument_problems": binding_problems,
                },
            )
        for target_field in (
            "order_numbers",
            "claim_ids",
            "api_account_ids",
            "limit",
            "offset",
            "page",
        ):
            target_is_dependency_bound = any(
                binding_path == target_field
                or binding_path.startswith(f"{target_field}[")
                or binding_path.startswith(f"{target_field}.")
                for binding_path in dependency_bindings
            )
            if target_is_dependency_bound and target_field in kwargs:
                step.arguments[target_field] = deepcopy(kwargs[target_field])
    from AI.processors.child_task_runtime import bind_child_read_arguments, child_observation_problems
    kwargs, child_problems = bind_child_read_arguments(tool, kwargs)
    argument_problems = [*child_problems, *_tool_argument_problems(tool, kwargs)]
    if argument_problems:
        return Result.fail(
            "Atomic operation argumanlari tool semasiyla uyusmuyor.",
            close_dialog=False,
            data={
                "tool": operation_id,
                "retryable": False,
                "argument_problems": argument_problems,
            },
        )
    clean_db = _compact_text(db_name)
    if clean_db and "db_name" in inspect.signature(tool.handler).parameters:
        kwargs["db_name"] = clean_db
    invocation_kwargs = dict(kwargs)
    if operation_id == "agent.delegate":
        invocation_kwargs["runtime_context"] = delegation_context
    if operation_id == "artifacts.read":
        invocation_kwargs["session_id"] = state.session_id
        invocation_kwargs["authorized_capabilities"] = [
            deepcopy(row) for row in list((state.active_entities.get("observation_artifacts") or {}).get("capabilities") or [])
            if isinstance(row, dict) and row.get("artifact_id") == kwargs.get("artifact_id")
        ]
    try:
        tool_result = tool.handler(**invocation_kwargs)
    except Exception as exc:
        return Result.fail(
            map_error_to_message(exc),
            error=exc,
            close_dialog=False,
            data={"tool": operation_id, "retryable": False},
        )
    payload = dict(tool_result.data or {}) if isinstance(tool_result.data, dict) else {}
    child_problems = child_observation_problems(tool, payload)
    if child_problems:
        return Result.fail("Alt çalışmanın gözlenen kapsamı yetkili kapsamla uyuşmadı.", close_dialog=False,
                           data={"tool": operation_id, "retryable": False, "argument_problems": child_problems})
    return Result(
        success=tool_result.success,
        message=tool_result.message,
        error=tool_result.error,
        close_dialog=False,
        data={
            "mode": "tool",
            "answer": tool_result.message,
            "tool_call": {"tool": operation_id, "arguments": kwargs},
            "tool_result": payload,
            "conversation_context": (
                dict(payload.get("conversation_context") or {})
                if isinstance(payload.get("conversation_context"), dict)
                else {}
            ),
            "bound_catalog_read": bool(not tool.requires_approval),
            "bound_catalog_operation": True,
            "dependency_bindings": dependency_bindings,
        },
    )


def _bind_pending_action_to_active_selection(
    action: dict[str, Any],
    state: AgentSessionState | None,
) -> dict[str, Any]:
    """Attach immutable source provenance when prepare kept the exact set."""

    payload = dict(action or {})
    if state is None:
        return payload
    source_selection = state.active_selection("orders")
    if source_selection is None or not source_selection.is_complete:
        return payload
    prepared = PendingActionSnapshot.from_action(payload)
    source_keys = {
        (ref.record_type, ref.record_id, ref.account, ref.environment)
        for ref in source_selection.refs
    }
    prepared_keys = {
        (ref.record_type, ref.record_id, ref.account, ref.environment)
        for ref in prepared.refs
    }
    if not source_keys or source_keys != prepared_keys:
        return payload

    arguments = dict(payload.get("arguments") or {})
    validation_hash = _compact_text(
        arguments.get("validation_source_snapshot_hash")
    )
    source_hash = _compact_text(source_selection.source_snapshot_hash)
    stale = bool(
        validation_hash
        and source_hash
        and validation_hash != source_hash
    )
    arguments.update(
        {
            "source_selection_id": source_selection.selection_id,
            "source_query_fingerprint": source_selection.query_fingerprint,
            "source_revision": source_selection.source_revision,
            "source_snapshot_hash": source_hash,
        }
    )
    payload["arguments"] = arguments
    payload["selection_id"] = source_selection.selection_id
    if stale:
        warnings = [
            _compact_text(value)
            for value in list(payload.get("warnings") or [])
            if _compact_text(value)
        ]
        warning = (
            "Kaynak siparis snapshot'i prepare sirasinda degisti; "
            "islem yeniden okunup hazirlanmadan calistirilamaz."
        )
        if warning not in warnings:
            warnings.append(warning)
        payload["warnings"] = warnings
        payload["execute_enabled"] = False
        payload["requires_reprepare"] = True
        payload["stale_reason"] = "source_snapshot_changed"
    return payload


def _pending_action_from_turn(
    data: dict[str, Any],
    *,
    state: AgentSessionState | None = None,
) -> dict[str, Any] | None:
    tool_result = data.get("tool_result")
    if isinstance(tool_result, dict):
        action = tool_result.get("action")
        if isinstance(action, dict) and bool(action.get("requires_approval", action.get("approval_required", True))):
            action = _bind_pending_action_to_active_selection(action, state)
            return PendingActionSnapshot.refresh_identity(action)
        if tool_result.get("route_status") == "needs_payload" and isinstance(tool_result.get("match"), dict):
            action = {
                "action_type": (tool_result.get("match") or {}).get("capability_id", ""),
                "approval_required": True,
                "execute_enabled": False,
                "missing_parameters": list(tool_result.get("missing_parameters") or []),
                "payload": dict(tool_result.get("payload") or {}),
            }
            return PendingActionSnapshot.from_action(action).to_action(action)
        if tool_result.get("approval_required") and isinstance(tool_result.get("capability"), dict):
            action = {
                "action_type": (tool_result.get("capability") or {}).get("capability_id", ""),
                "approval_required": True,
                "execute_enabled": False,
                "missing_parameters": list(tool_result.get("missing_parameters") or []),
                "payload": dict(tool_result.get("payload") or {}),
            }
            return PendingActionSnapshot.from_action(action).to_action(action)
    return None


def _record_typed_step_observation(
    state: AgentSessionState,
    *,
    step: AgentTaskStep,
    data: dict[str, Any],
    result: Result,
) -> Observation | None:
    """Project a tool turn into authoritative typed state.

    Conversation history is still retained for answer style during migration,
    but later action scope can now bind to immutable ids instead of mining that
    prose again.
    """

    if bool(data.get("session_state_applied")):
        operation_names = _tool_names_from_turn(data)
        if not operation_names:
            return None
        for observation in reversed(state.observations):
            if observation.operation_name in operation_names:
                return observation
        return None
    context = (
        dict(data.get("conversation_context") or {})
        if isinstance(data.get("conversation_context"), dict)
        else {}
    )
    tool_result = (
        dict(data.get("tool_result") or {})
        if isinstance(data.get("tool_result"), dict)
        else {}
    )
    if not context and isinstance(tool_result.get("conversation_context"), dict):
        context = dict(tool_result.get("conversation_context") or {})

    web_observation = tool_result.get("web_observation")
    if isinstance(web_observation, dict) and web_observation.get("observation_id"):
        context = {
            "kind": "web_observation",
            "web_observation_id": _compact_text(web_observation.get("observation_id")),
            "url": _compact_text(web_observation.get("url")),
            "title": _compact_text(web_observation.get("title")),
            "query_summary": _compact_text(web_observation.get("query_summary")),
            "source_domain": _compact_text(web_observation.get("source_domain")),
            "source_class": _compact_text(web_observation.get("source_class")),
            "published_at": _compact_text(web_observation.get("published_at")),
            "accessed_at": _compact_text(web_observation.get("accessed_at")),
            "freshness": _compact_text(web_observation.get("freshness")),
            "trust": _compact_text(web_observation.get("trust")),
            "content_hash": _compact_text(web_observation.get("content_hash")),
            "prompt_injection_detected": bool(
                web_observation.get("prompt_injection_detected")
            ),
            "untrusted_content": True,
        }
    elif _compact_text(tool_result.get("tool")) == "web.compare_sources":
        context = {
            "kind": "web_comparison",
            "status": _compact_text(tool_result.get("status")),
            "claim": _compact_text(tool_result.get("claim")),
            "source_count": int(tool_result.get("source_count") or 0),
            "citations": [
                dict(row)
                for row in list(tool_result.get("citations") or [])[:20]
                if isinstance(row, dict)
            ],
        }
    elif isinstance(tool_result.get("report_snapshot"), dict):
        report_snapshot = dict(tool_result.get("report_snapshot") or {})
        context = {
            "kind": "analysis_context",
            "domain": _compact_text(step.operation_domain).casefold() or "orders",
            "analysis_type": _compact_text(
                report_snapshot.get("report_type")
            ) or "report_snapshot",
            "source_tools": [
                _compact_text(tool_result.get("tool")) or _compact_text(step.step_id)
            ],
            "facts": {
                "report_snapshot": report_snapshot,
                "snapshot_id": _compact_text(tool_result.get("snapshot_id")),
                "content_hash": _compact_text(tool_result.get("content_hash")),
                "period": _compact_text(tool_result.get("period")),
                "period_label": _compact_text(tool_result.get("period_label")),
                "account_scopes": list(tool_result.get("account_scopes") or []),
            },
            "aggregates": {
                key: tool_result.get(key)
                for key in (
                    "row_count",
                    "order_count",
                    "product_count",
                    "total_quantity",
                )
                if tool_result.get(key) is not None
            },
            "account_scopes": list(tool_result.get("account_scopes") or []),
        }

    tool_names = tuple(_tool_names_from_turn(data))
    operation_name = tool_names[0] if tool_names else _compact_text(step.step_id)
    if not operation_name:
        return None
    if not context:
        # Result schemas may use `orders`/`returns` for a scalar count. Only
        # record collections can establish a selection or be iterated here.
        order_rows = tool_result.get("orders")
        return_rows = tool_result.get("returns")
        materialized_order_numbers = [
            _compact_text(
                row.get("order_number") or row.get("orderNumber")
            )
            for row in (order_rows if isinstance(order_rows, (list, tuple)) else [])
            if isinstance(row, dict)
            and _compact_text(
                row.get("order_number") or row.get("orderNumber")
            )
        ]
        order_numbers = (
            materialized_order_numbers
            if operation_name == "orders.query"
            else [
                _compact_text(value)
                for value in list(tool_result.get("order_numbers") or [])
                if _compact_text(value)
            ]
            or materialized_order_numbers
        )
        order_numbers = list(dict.fromkeys(order_numbers))
        claim_ids = [
            _compact_text(value)
            for value in list(tool_result.get("claim_ids") or [])
            if _compact_text(value)
        ]
        return_order_numbers: list[str] = []
        for row in (return_rows if isinstance(return_rows, (list, tuple)) else []):
            if not isinstance(row, dict):
                continue
            claim_id = _compact_text(
                row.get("claim_id") or row.get("claimId")
            )
            order_number = _compact_text(
                row.get("order_number") or row.get("orderNumber")
            )
            if claim_id and claim_id not in claim_ids:
                claim_ids.append(claim_id)
            if order_number and order_number not in return_order_numbers:
                return_order_numbers.append(order_number)
        if order_numbers:
            listed_count = (
                len(order_numbers)
                if operation_name == "orders.query"
                else int(tool_result.get("listed_count") or len(order_numbers))
            )
            total_count = int(
                tool_result.get("total_count")
                or tool_result.get("count")
                or tool_result.get("ready_to_ship")
                or listed_count
            )
            context = {
                "kind": "order_selection",
                "source_tool": operation_name,
                "period": _compact_text(tool_result.get("period")),
                "period_label": _compact_text(tool_result.get("period_label")),
                "order_numbers": order_numbers,
                "listed_count": listed_count,
                "total_count": total_count,
                "truncated": bool(tool_result.get("truncated")),
                "query_fingerprint": _compact_text(
                    tool_result.get("query_fingerprint")
                ),
                "source_revision": _compact_text(
                    tool_result.get("source_revision")
                ),
                "source_snapshot_hash": _compact_text(
                    tool_result.get("source_snapshot_hash")
                ),
                "account_by_order": dict(tool_result.get("account_by_order") or {}),
                "environment_by_account": dict(tool_result.get("environment_by_account") or {}),
                "account_scopes": list(tool_result.get("account_scopes") or []),
            }
        elif claim_ids:
            listed_count = int(tool_result.get("listed_count") or len(claim_ids))
            total_count = int(tool_result.get("total_count") or tool_result.get("count") or listed_count)
            context = {
                "kind": "return_selection",
                "source_tool": operation_name,
                "period": _compact_text(tool_result.get("period")),
                "claim_ids": claim_ids,
                "order_numbers": list(
                    tool_result.get("order_numbers") or return_order_numbers
                ),
                "listed_count": listed_count,
                "total_count": total_count,
                "truncated": bool(tool_result.get("truncated")),
                "account_by_claim": dict(tool_result.get("account_by_claim") or {}),
                "environment_by_account": dict(tool_result.get("environment_by_account") or {}),
                "account_scopes": list(tool_result.get("account_scopes") or []),
            }
    if not context and isinstance(tool_result.get("account_scopes"), list):
        # Aggregate reads often have no record selection, but their account
        # scope is still authoritative context for the next conversation turn.
        scope_rows = [
            {
                key: row.get(key)
                for key in (
                    "api_account_id",
                    "account_id",
                    "store_name",
                    "platform",
                    "environment",
                )
                if row.get(key) not in (None, "")
            }
            for row in tool_result["account_scopes"][:50]
            if isinstance(row, dict)
        ]
        if scope_rows:
            read_evidence = dict(tool_result.get("read_evidence") or {})
            account_population_read = operation_name == "marketplaces.account_lookup"
            truncated = bool(tool_result.get("truncated")) if account_population_read else False
            if account_population_read:
                population = (
                    "partial_registered_accounts"
                    if truncated
                    else "all_registered_accounts"
                    if _compact_text(read_evidence.get("scope")) == "all_accounts"
                    else "matching_registered_accounts"
                )
            else:
                population = "accounts_in_read_result"
            context = {
                "kind": "read_scope",
                "source_tool": operation_name,
                "population": population,
                "account_scopes": scope_rows,
                "period": _compact_text(tool_result.get("period")),
                "truncated": truncated,
                "total_matching": (
                    tool_result.get("total_matching") if account_population_read else None
                ),
            }
    if (
        operation_name == "orders.query"
        and _compact_text(context.get("kind")) == "order_selection"
    ):
        source_selection = state.active_selection("orders")
        candidate_selection = SelectionSnapshot.from_context(context)
        bound_order_numbers = {
            _compact_text(value)
            for value in list(step.arguments.get("order_numbers") or [])
            if _compact_text(value)
        }
        source_keys = {
            (
                ref.record_id,
                ref.account,
                ref.environment,
            )
            for ref in (source_selection.refs if source_selection else ())
        }
        candidate_keys = {
            (
                ref.record_id,
                ref.account,
                ref.environment,
            )
            for ref in (candidate_selection.refs if candidate_selection else ())
        }
        source_hash = _compact_text(
            source_selection.source_snapshot_hash
            if source_selection is not None
            else ""
        )
        validation_hash = _compact_text(
            candidate_selection.source_snapshot_hash
            if candidate_selection is not None
            else ""
        )
        exact_lineage = bool(
            source_selection is not None
            and source_selection.is_complete
            and candidate_selection is not None
            and candidate_selection.is_complete
            and source_keys
            and source_keys == candidate_keys
            and (
                not bound_order_numbers
                or bound_order_numbers
                == set(source_selection.record_ids)
            )
            and (
                not source_hash
                or source_hash == validation_hash
            )
        )
        lineage = {
            "validated": exact_lineage,
            "source_selection_id": (
                source_selection.selection_id
                if source_selection is not None
                else ""
            ),
            "candidate_selection_id": (
                candidate_selection.selection_id
                if candidate_selection is not None
                else ""
            ),
            "validation_operation": operation_name,
            "record_count": len(candidate_keys),
            "source_snapshot_hash": source_hash,
            "validation_source_snapshot_hash": validation_hash,
            "validation_query_fingerprint": _compact_text(
                candidate_selection.query_fingerprint
                if candidate_selection is not None
                else ""
            ),
        }
        lineage_rows = [
            dict(row)
            for row in list(
                state.active_entities.get(
                    "selection_lineage_validations"
                )
                or []
            )
            if isinstance(row, dict)
        ]
        lineage_rows.append(lineage)
        state.active_entities["selection_lineage_validations"] = (
            lineage_rows[-60:]
        )
        step.result_data["selection_lineage"] = dict(lineage)
        if exact_lineage and source_selection is not None:
            context = source_selection.to_context()
            data["conversation_context"] = dict(context)
            step.result_data["conversation_context"] = dict(context)
    aggregates = {
        key: tool_result.get(key)
        for key in ("count", "listed_count", "total_count", "matched_count")
        if tool_result.get(key) is not None
    }
    if (
        operation_name == "orders.item_sales_summary"
        and int(tool_result.get("identity_filter_count") or 0) == 1
    ):
        dependency_binding = _compact_text(
            dict(step.result_data or {})
            .get("dependency_bindings", {})
            .get("product_identities")
        )
        binding_suffix = ":tool_result.product_identities"
        identity_step_id = (
            dependency_binding[: -len(binding_suffix)]
            if dependency_binding.endswith(binding_suffix)
            else ""
        )
        identity_step = next(
            (
                candidate
                for candidate in state.completed_steps
                if _compact_text(candidate.step_id) == identity_step_id
                and "orders.product_public_identities"
                in {
                    _compact_text(value)
                    for value in list(candidate.tool_names or [])
                }
            ),
            None,
        )
        identity_result = (
            dict(
                dict(identity_step.result_data or {}).get("tool_result") or {}
            )
            if identity_step is not None
            else {}
        )
        product_identities = [
            dict(value)
            for value in list(identity_result.get("product_identities") or [])
            if isinstance(value, dict) and _compact_text(value.get("product_name"))
        ]
        rows = [
            {
                key: row.get(key)
                for key in (
                    "product_name",
                    "quantity",
                    "order_count",
                    "gross_amount",
                    "currency",
                )
                if row.get(key) is not None
            }
            for row in list(tool_result.get("rows") or [])
            if isinstance(row, dict) and _compact_text(row.get("product_name"))
        ]
        authoritative_empty_summary = bool(
            tool_result.get("empty_result") is True
            and tool_result.get("metrics_complete") is True
            and not rows
            and int(tool_result.get("order_count") or 0) == 0
            and int(tool_result.get("matched_order_count") or 0) == 0
            and int(tool_result.get("total_quantity") or 0) == 0
            and float(tool_result.get("total_gross_amount") or 0.0) == 0.0
            and not dict(tool_result.get("gross_amount_by_currency") or {})
        )
        if len(product_identities) == 1 and (
            rows or authoritative_empty_summary
        ):
            contextual_summary = {
                "verified": True,
                "product_name": _compact_text(
                    product_identities[0].get("product_name")
                ),
                "identity_dependency_step_id": identity_step_id,
                "identity_filter_count": 1,
                "period": _compact_text(tool_result.get("period")),
                "period_label": _compact_text(tool_result.get("period_label")),
                "order_count": tool_result.get("order_count"),
                "matched_order_count": tool_result.get("matched_order_count"),
                "population_order_count": tool_result.get(
                    "population_order_count"
                ),
                "total_quantity": tool_result.get("total_quantity"),
                "gross_amount_by_currency": dict(
                    tool_result.get("gross_amount_by_currency") or {}
                ),
                "total_gross_amount": tool_result.get("total_gross_amount"),
                "currency": _compact_text(tool_result.get("currency")),
                "empty_result": bool(tool_result.get("empty_result")),
                "metrics_complete": bool(tool_result.get("metrics_complete")),
                "currency_applicable": bool(
                    tool_result.get("currency_applicable")
                ),
                "rows": rows,
                "source_revision": tool_result.get("source_revision"),
                "source_snapshot_hash": _compact_text(
                    tool_result.get("source_snapshot_hash")
                ),
            }
            contextual_summary["evidence_sha256"] = hashlib.sha256(
                json.dumps(
                    contextual_summary,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            aggregates["contextual_item_sales_summary"] = contextual_summary
    return state.ingest_tool_observation(
        context=context,
        operation_name=operation_name,
        success=bool(result.success),
        message=_compact_text(result.message),
        aggregates=aggregates,
        domain=_compact_text(step.operation_domain).casefold(),
    )


def _action_type(action: dict[str, Any]) -> str:
    return _compact_text(action.get("action_type") or action.get("operation") or action.get("capability_id"))


def _append_action_event(
    state: AgentSessionState,
    *,
    phase: str,
    status: str,
    action: dict[str, Any],
    step_index: int | None = None,
    result: Result | None = None,
    approved_by: str = "",
    audit_path: str = "",
) -> None:
    data = dict(result.data or {}) if result is not None else {}
    event: dict[str, Any] = {
        "phase": phase,
        "status": status,
        "action_type": _action_type(action),
        "step_index": step_index,
        "approved_by": _compact_text(approved_by),
        "approval_required": bool(action.get("approval_required", action.get("requires_approval", True))),
        "execute_enabled": bool(action.get("execute_enabled", False)),
        "action": dict(action or {}),
    }
    if result is not None:
        event.update(
            {
                "success": bool(result.success),
                "result_message": _compact_text(result.message),
                "verify": dict(data.get("verify") or {}) if isinstance(data.get("verify"), dict) else {},
            }
        )
    if audit_path:
        event["audit_path"] = audit_path
    state.action_history.append(event)


def _sync_goal_plan_step(
    state: AgentSessionState,
    step: AgentTaskStep,
) -> None:
    plan = state.active_goal_plan()
    if plan is None:
        return
    target = plan.step(step.step_id)
    if target is None:
        target = next(
            (row for row in plan.steps if int(row.index) == int(step.index)),
            None,
        )
    if target is None:
        plan.steps.append(step)
    elif target is not step:
        restored = AgentTaskStep.from_dict(step.to_dict())
        target.__dict__.update(restored.__dict__)
    plan.touch()


def _action_with_runtime_db(action: dict[str, Any], db_name: str | None) -> dict[str, Any]:
    clean_db = _compact_text(db_name)
    if not clean_db:
        return dict(action or {})
    if _action_type(dict(action or {})) in {
        "orders.action_export_order_profit_excel",
        "orders.action_export_report_snapshot_xlsx",
        "ai.action_export_report_snapshot_xlsx",
        "ai.action_save_workflow_spec",
    }:
        return dict(action or {})
    updated = dict(action or {})
    arguments = dict(updated.get("arguments") or {})
    payload = dict(arguments.get("payload") or {})
    if not payload:
        rows = [row for row in updated.get("rows") or [] if isinstance(row, dict)]
        if len(rows) == 1 and isinstance(rows[0].get("payload"), dict):
            payload = dict(rows[0].get("payload") or {})
    payload.setdefault("db_name", clean_db)
    arguments["payload"] = payload
    updated["arguments"] = arguments
    return updated


def _complete_state_if_idle(state: AgentSessionState) -> None:
    if state.status == "running" and not state.remaining_steps and not state.pending_actions:
        if _unmet_goal_obligations(state):
            _stop_incomplete_task(state, _unmet_goal_obligations(state)[0])
            return
        if (state.active_entities or {}).get("web_research_uncertainty", {}).get("reason") == "no_search_results":
            _stop_incomplete_task(state, "no_search_results")
            return
        unresolved_failures = [
            step
            for step in state.completed_steps
            if step.status == "failed"
            and _compact_text((step.result_data or {}).get("replan_status")) != "superseded"
        ]
        if unresolved_failures:
            state.status = "failed"
            state.set_goal_plan_status("failed")
            state.memory_summary = f"{len(unresolved_failures)} task step could not be resolved."
            state.touch()
            return
        evaluations = [
            row for row in list((state.active_entities or {}).get("goal_evaluations") or [])
            if isinstance(row, dict)
        ]
        latest_observation = state.observations[-1] if state.observations else None
        verified_execution = bool(
            latest_observation is not None
            and latest_observation.success
            and latest_observation.facts.get("phase") == "execute_readback"
            and latest_observation.facts.get("verified") is True
        )
        model_owned_evaluation = bool(
            evaluations
            and (
                evaluations[-1].get("model_invoked") is True
                or state.active_goal_plan() is not None
                and state.active_goal_plan().source in {
                    "llm_direct", "llm_direct_repaired", "llm_canonical_resolved"
                }
            )
        )
        if model_owned_evaluation and not verified_execution and not (
            evaluations[-1].get("decision") == "complete"
            and evaluations[-1].get("applied") is True
        ):
            _stop_incomplete_task(state, _compact_text(evaluations[-1].get("reason")) or "goal_completion_unverified")
            return
        state.status = "complete"
        state.set_goal_plan_status("complete")
        action_count = len([row for row in state.action_history if row.get("phase") == "execute" and row.get("success")])
        suffix = f", {action_count} approved action executed" if action_count else ""
        state.memory_summary = f"{len(state.completed_steps)} orders task step completed{suffix}."
        state.touch()


_ACTION_RESULT_LABELS = {
    "labels.action_create_labels_from_selected_orders": "Siparis etiketleri olusturuldu",
    "labels.mark_orders_extracted_from_label_result": "Fis/cikti durumu isaretlendi",
    "orders.change_order_cargo_provider": "Siparisin kargo firmasi degistirildi",
    "orders.change_orders_cargo_provider_bulk": "Siparislerin kargo firmasi degistirildi",
    "orders.approve_return_claim": "Iade onaylandi",
    "orders.action_export_order_profit_excel": "Siparis kar Excel dosyasi olusturuldu",
    "orders.action_export_report_snapshot_xlsx": "Dogrulanmis Excel raporu olusturuldu",
    "ai.action_export_report_snapshot_xlsx": "Kaynaklı Excel raporu oluşturuldu",
    "orders.get_orders_from_companies": "Pazaryeri siparis verileri senkronize edildi",
    "orders.mark_return_claims_stale": "Stale iade kayitlari pasiflestirildi",
    "orders.restore_return_claims_from_stale": "Stale iade kayitlari geri alindi",
}


def _execute_evidence_rows(state: AgentSessionState) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for event in state.action_history:
        if event.get("phase") != "execute" or event.get("success") is not True:
            continue
        verify = dict(event.get("verify") or {}) if isinstance(event.get("verify"), dict) else {}
        identifiers: list[str] = []
        for key in ("order_number", "claim_id", "output_path"):
            value = _compact_text(verify.get(key))
            if value and value not in identifiers:
                identifiers.append(value)
        for key in ("order_numbers", "claim_ids", "active_claim_ids"):
            for value in list(verify.get(key) or []):
                text = _compact_text(value)
                if text and text not in identifiers:
                    identifiers.append(text)
        action = dict(event.get("action") or {})
        arguments = dict(action.get("arguments") or {})
        payload = dict(arguments.get("payload") or {})
        for key in ("order_number", "order", "claim_id"):
            value = _compact_text(
                payload.get(key)
                or arguments.get(key)
            )
            if value and value not in identifiers:
                identifiers.append(value)
        for key in ("order_numbers", "orders", "claim_ids"):
            values = payload.get(key) or arguments.get(key) or []
            for value in list(values if isinstance(values, (list, tuple, set)) else []):
                text = _compact_text(value)
                if text and text not in identifiers:
                    identifiers.append(text)
        action_type = _compact_text(event.get("action_type"))
        rows.append(
            {
                "action_type": action_type,
                "label": _ACTION_RESULT_LABELS.get(action_type, "Onayli islem tamamlandi"),
                "verified": verify.get("verified") is True,
                "verified_by": _compact_text(verify.get("verified_by")),
                "identifiers": identifiers[:12],
                "audit_recorded": bool(_compact_text(event.get("audit_path"))),
                "sync_observability": {
                    "accounts": list(verify.get("accounts") or []),
                    "fetched": dict(verify.get("fetched") or {}),
                    "writes": dict(verify.get("writes") or {}),
                    "skipped": dict(verify.get("skipped") or {}),
                    "errors": dict(verify.get("errors") or {}),
                    "watermark": dict(verify.get("watermark") or {}),
                    "db_readback": dict(verify.get("db_readback") or {}),
                }
                if action_type == "orders.get_orders_from_companies"
                else {},
            }
        )
    return rows


def _format_execute_evidence_lines(state: AgentSessionState) -> list[str]:
    lines: list[str] = []
    for row in _execute_evidence_rows(state):
        suffixes: list[str] = []
        if row.get("verified"):
            suffixes.append("dogrulandi")
        if row.get("audit_recorded"):
            suffixes.append("audit kaydi olustu")
        identifiers = ", ".join(str(value) for value in list(row.get("identifiers") or [])[:8])
        detail = f": {identifiers}" if identifiers else ""
        sync = dict(row.get("sync_observability") or {})
        if sync:
            accounts = list(sync.get("accounts") or [])
            account_labels = [
                " / ".join(
                    value
                    for value in (
                        _compact_text(account.get("store")) or f"hesap {account.get('api_account_id')}",
                        _compact_text(account.get("environment")),
                    )
                    if value
                )
                for account in accounts
                if isinstance(account, dict)
            ]
            fetched = dict(sync.get("fetched") or {})
            writes = dict(sync.get("writes") or {})
            skipped = dict(sync.get("skipped") or {})
            errors = dict(sync.get("errors") or {})
            readback = dict(sync.get("db_readback") or {})
            watermark = dict(sync.get("watermark") or {})
            scope = ", ".join(account_labels) or "hesap kapsami bilinmiyor"
            unique_orders = int(fetched.get("unique_orders") or 0)
            snapshots = int(fetched.get("order_snapshots") or 0)
            inserted = int(writes.get("order_snapshots_inserted") or 0)
            updated = int(writes.get("order_snapshots_updated") or 0)
            existing = int(writes.get("order_snapshots_already_present") or 0)
            found = int(readback.get("found_order_snapshots") or 0)
            requested = int(readback.get("requested_order_snapshots") or 0)
            found_items = int(readback.get("found_item_rows") or 0)
            requested_items = int(readback.get("requested_item_rows") or 0)
            found_returns = int(readback.get("found_return_snapshots") or 0)
            requested_returns = int(readback.get("requested_return_snapshots") or 0)
            skipped_rows = int(skipped.get("source_rows") or 0)
            error_count = int(errors.get("count") or 0)
            fresh_through = int(watermark.get("fresh_through_ms") or 0)
            detail = (
                f": {scope}; {unique_orders} siparis / {snapshots} snapshot cekildi; "
                f"{inserted} yeni, {updated} guncellendi, {existing} zaten kayitli; "
                f"{skipped_rows} atlanan, {error_count} hata; "
                f"DB read-back {found}/{requested} siparis snapshot"
                + (
                    f", {found_items}/{requested_items} kalem"
                    if requested_items or found_items
                    else ""
                )
                + (
                    f", {found_returns}/{requested_returns} iade snapshot"
                    if requested_returns or found_returns
                    else ""
                )
                + (f"; tazelik siniri {fresh_through}" if fresh_through else "")
            )
        proof = f" ({', '.join(suffixes)})" if suffixes else ""
        lines.append(f"- {row.get('label')}{detail}{proof}.")
    return lines


def _web_research_gap_projection(
    state: AgentSessionState,
    inadequate_steps: list[AgentTaskStep],
) -> tuple[str, list[dict[str, Any]], str]:
    """Project a grounded research-gap answer from opened source evidence."""

    checked_sources: list[dict[str, Any]] = []
    seen_urls: set[str] = set()
    opinion_requested = False
    product_name = ""
    for completed in state.completed_steps:
        tool_result = (
            dict((completed.result_data or {}).get("tool_result") or {})
            if isinstance((completed.result_data or {}).get("tool_result"), dict)
            else {}
        )
        if _compact_text(tool_result.get("tool")) == "orders.product_public_identities":
            identities = [
                dict(row)
                for row in list(tool_result.get("product_identities") or [])
                if isinstance(row, dict)
            ]
            product_name = _compact_text(
                (identities[0] if identities else {}).get("product_name")
            )
            break
    for step in inadequate_steps:
        tool_result = dict((step.result_data or {}).get("tool_result") or {})
        assessment = dict(tool_result.get("goal_evidence_assessment") or {})
        opinion_requested = opinion_requested or bool(
            assessment.get("opinion_requested")
        )
        observation = (
            dict(tool_result.get("web_observation") or {})
            if isinstance(tool_result.get("web_observation"), dict)
            else {}
        )
        url = _compact_text(observation.get("url") or tool_result.get("url"))
        if (
            not url
            or url in seen_urls
            or "goal_topic_evidence_missing" in list(assessment.get("findings") or [])
        ):
            continue
        seen_urls.add(url)
        checked_sources.append(
            {
                "title": _compact_text(observation.get("title")) or url,
                "url": url,
                "observation_id": _compact_text(observation.get("observation_id")),
                "finding_codes": list(assessment.get("findings") or []),
                "opinion_review_count": int(
                    assessment.get("opinion_review_count") or 0
                ),
                "opinion_evaluation_count": int(
                    assessment.get("opinion_evaluation_count") or 0
                ),
            }
        )

    source_count = len(inadequate_steps)
    if opinion_requested:
        subject = f"“{product_name}” için " if product_name else "Bu ürün için "
        counted_sources = [
            row
            for row in checked_sources
            if int(row.get("opinion_review_count") or 0)
            or int(row.get("opinion_evaluation_count") or 0)
        ]
        lines = [
            (
                f"{subject}{source_count} public ürün/inceleme sayfasını açıp içeriğini "
                "kontrol ettim. Bu sayfaların hiçbiri kullanıcı yorumlarının metnini, "
                "doğrulanabilir bir puan özetini veya değerlendirme dağılımını göstermedi; "
                "bu nedenle insanların ne söylediğine "
                "dair doğrulanmamış bir özet üretmedim. Arama sonucu snippet'lerini kanıt "
                "saymadım."
            )
        ]
        if counted_sources:
            count_fragments: list[str] = []
            for row in counted_sources[:5]:
                evidence_parts: list[str] = []
                evaluation_count = int(
                    row.get("opinion_evaluation_count") or 0
                )
                review_count = int(row.get("opinion_review_count") or 0)
                if evaluation_count:
                    evidence_parts.append(f"{evaluation_count} değerlendirme")
                if review_count:
                    evidence_parts.append(f"{review_count} yorum")
                count_fragments.append(
                    f"{_compact_text(row.get('title'))}: "
                    + ", ".join(evidence_parts)
                )
            lines.append(
                "Yalnız yorum/değerlendirme varlığına ilişkin şu sayısal kanıt "
                "görülebildi; yorum içerikleri açılmadığı için bunlardan duygu veya "
                "görüş sonucu çıkarmadım: "
                + "; ".join(count_fragments)
                + "."
            )
        if checked_sources:
            lines.append("Kontrol edilen ve ürün tipiyle ilişkili bulunan sayfalar:")
            for row in checked_sources[:5]:
                label = re.sub(
                    r"[\[\]\r\n]+",
                    " ",
                    _compact_text(row.get("title")),
                ).strip() or _compact_text(row.get("url"))
                lines.append(f"- [{label}]({_compact_text(row.get('url'))})")
        return "\n".join(lines), checked_sources, "user_opinion_evidence_unavailable"

    return (
        (
            f"Web araştırmasında {source_count} public kaynak açıp içeriğini inceledim; "
            "ancak hiçbiri istediğin bilgi için doğrulanabilir ve hedefle ilişkili kanıt "
            "taşımadı. Bu nedenle arama sonucu başlıklarını veya ilgisiz sayfa metnini "
            "cevap diye kullanmadım. Daha doğrudan ilgili bir public kaynak bağlantısı "
            "verirsen onu kontrollü biçimde inceleyebilirim."
        ),
        checked_sources,
        "opened_sources_lack_goal_evidence",
    )


def _fallback_task_final_answer(state: AgentSessionState) -> str:
    web_uncertainty = (
        dict((state.active_entities or {}).get("web_research_uncertainty") or {})
        if isinstance((state.active_entities or {}).get("web_research_uncertainty"), dict)
        else {}
    )
    if web_uncertainty.get("reason") == "no_search_results":
        return (
            "Web araması tamamlandı ancak açılıp doğrulanabilecek bir kaynak bulunamadı. "
            "Arama sonucu snippet'leri kanıt sayılmadığı için doğrulanmamış bir bulgu üretmedim."
        )
    evidence_lines = _format_execute_evidence_lines(state)
    if evidence_lines:
        return "\n".join(
            [
                "Islem tamamlandi ve sonucu dogrulandi:",
                *evidence_lines,
            ]
        )
    if len(state.completed_steps) == 1:
        step = state.completed_steps[0]
        authoritative_answer = _compact_text(
            (step.result_data or {}).get("answer") or step.result_message
        )
        if authoritative_answer:
            # A one-step read already has the authoritative, user-facing tool
            # answer.  Re-wrapping it in a technical task summary both loses
            # information and gives the final LLM another chance to omit the
            # only fact the user asked for.
            return authoritative_answer
    lines: list[str] = [f"Agent gorevi tamamlandi: {len(state.completed_steps)} okuma adimi calisti."]
    for step in state.completed_steps[:8]:
        tool_text = ", ".join(step.tool_names or []) or "-"
        answer = _compact_text((step.result_data or {}).get("answer") or step.result_message)
        if len(answer) > 260:
            answer = answer[:257].rstrip() + "..."
        lines.append(f"{step.index}. {tool_text}: {answer or step.status}")
    return "\n".join(lines).strip()


