            # keeps a negated output such as ``yuzdeye cevirme`` from
            # surviving as a positive ratio column.
            explicit_direct_authority = set(
                _explicit_repeat_projection_fields(message)
            )
            if not _goal_has_total_order_count_requirement(message):
                explicit_direct_authority.discard("count")
            if not _goal_has_order_status_distribution_requirement(message):
                explicit_direct_authority.discard("status")
            if not _explicit_percentage_relation_requested(message):
                explicit_direct_authority.discard("ratio")
